### 📌 `HabitListViewController.swift`
```swift
import UIKit

class HabitListViewController: UIViewController, UITableViewDataSource, UITableViewDelegate {
    var habits: [Habit] = []
    private let tableView = UITableView()
    private let addHabitButton = UIButton()

    override func viewDidLoad() {
        super.viewDidLoad()
        setupUI()
    }

    private func setupUI() {
        view.backgroundColor = .white

        // Table View
        tableView.dataSource = self
        tableView.delegate = self
        tableView.register(UITableViewCell.self, forCellReuseIdentifier: "cell")
        view.addSubview(tableView)
        tableView.frame = view.bounds

        // Add Habit Button
        addHabitButton.setTitle("Add Habit", for: .normal)
        addHabitButton.backgroundColor = .systemBlue
        addHabitButton.setTitleColor(.white, for: .normal)
        addHabitButton.addTarget(self, action: #selector(addHabitTapped), for: .touchUpInside)
        view.addSubview(addHabitButton)
        addHabitButton.translatesAutoresizingMaskIntoConstraints = false
        NSLayoutConstraint.activate([
            addHabitButton.bottomAnchor.constraint(equalTo: view.safeAreaLayoutGuide.bottomAnchor, constant: -16),
            addHabitButton.leadingAnchor.constraint(equalTo: view.leadingAnchor, constant: 16),
            addHabitButton.trailingAnchor.constraint(equalTo: view.trailingAnchor, constant: -16)
        ])
    }

    @objc private func addHabitTapped() {
        let vc = AddHabitViewController()
        vc.habit = Habit(id: UUID(), name: "", description: "", isCompleted: false)
        vc.delegate = self
        navigationController?.pushViewController(vc, animated: true)
    }

    // MARK: - Table View Data Source
    func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habits.count
    }

    func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "cell", for: indexPath)
        let habit = habits[indexPath.row]
        cell.textLabel?.text = habit.name
        cell.detailTextLabel?.text = habit.description
        cell.accessoryType = habit.isCompleted ? .checkmark : .none
        return cell
    }

    // MARK: - Table View Delegate
    func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        let habit = habits[indexPath.row]
        habit.isCompleted.toggle()
        tableView.reloadRows(at: [indexPath], with: .none)
    }
}
```

