### 📌 **SwiftUI Habit Tracking App (Swift)**
```swift
import SwiftUI

// 1. Define the Habit data model
struct Habit: Identifiable {
    let id = UUID()
    var name: String
    var description: String
    var completed: Bool
}

// 2. Main app view
struct ContentView: View {
    @State private var habits: [Habit] = [
        Habit(name: "Drink Water", description: "8 glasses a day", completed: false),
        Habit(name: "Exercise", description: "30 minutes daily", completed: false)
    ]
    @State private var showingAddHabit = false
    @State private var newHabitName = ""
    @State private var newHabitDescription = ""

    var body: some View {
        NavigationView {
            List {
                // 3. Display habits with toggle for completion
                ForEach(habits) { habit in
                    HStack {
                        Text(habit.name)
                            .font(.headline)

                        Spacer()

                        Toggle(isOn: $habits.first(where: { $0.id == habit.id })?.completed ?? false) {
                            Text("Done")
                        }
                        .onChange(of: habit.completed) { newValue in
                            // Update habit's completion status
                            if let index = habits.firstIndex(where: { $0.id == habit.id }) {
                                habits[index].completed = newValue
                            }
                        }
                    }
                }
                .onDelete(perform: deleteHabit)
            }
            .navigationTitle("Habits")
            .toolbar {
                Button("Add Habit") {
                    showingAddHabit = true
                }
            }
            .sheet(isPresented: $showingAddHabit) {
                HabitFormView(
                    newHabitName: $newHabitName,
                    newHabitDescription: $newHabitDescription,
                    onSave: { name, description in
                        let newHabit = Habit(name: name, description: description, completed: false)
                        habits.append(newHabit)
                        showingAddHabit = false
                        newHabitName = ""
                        newHabitDescription = ""
                    }
                )
            }
        }
    }

    // 4. Delete habit function
    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
    }
}

// 5. Habit form view
struct HabitFormView: View {
    @Binding var newHabitName: String
    @Binding var newHabitDescription: String
    let onSave: (String, String) -> Void

    var body: some View {
        VStack {
            TextField("Habit Name", text: $newHabitName)
                .padding()
                .textFieldStyle(RoundedBorderTextFieldStyle())

            TextField("Description", text: $newHabitDescription)
                .padding()
                .textFieldStyle(RoundedBorderTextFieldStyle())

            Button("Save") {
                onSave(newHabitName, newHabitDescription)
            }
            .padding()
            .background(Color.blue)
            .foregroundColor(.white)
            .cornerRadius(8)
        }
        .padding()
    }
}

// 6. Preview for SwiftUI
struct ContentView_Previews: PreviewProvider {
    static var previews: some View {
        ContentView()
    }
}
```

