Here's a basic implementation of a native iOS habit tracking app using **Swift** and **UIKit** (Xcode). This includes a simple UI for tracking habits, marking them as completed, and storing data locally with `UserDefaults`.

---

### 📁 Project Structure
```
HabitTracker/
├── HabitTracker.swift
├── HabitListViewController.swift
├── HabitDetailViewController.swift
├── Habit.swift
├── Info.plist
└── main.storyboard
```

---

### 📌 `Habit.swift` (Model)
```swift
import Foundation

struct Habit {
    let name: String
    var completed: Bool
    var streak: Int
}
```

---

### 📌 `HabitListViewController.swift` (Main View Controller)
```swift
import UIKit

class HabitListViewController: UITableViewController {
    var habits: [Habit] = []
    let defaults = UserDefaults.standard

    override func viewDidLoad() {
        super.viewDidLoad()
        loadHabits()
        navigationItem.title = "Habit Tracker"
        navigationItem.rightBarButtonItem = UIBarButtonItem(barButtonSystemItem: .add, target: self, action: #selector(addHabit))
    }

    @objc func addHabit() {
        let alert = UIAlertController(title: "New Habit", message: nil, preferredStyle: .alert)
        alert.addTextField { textField in
            textField.placeholder = "Habit name"
        }
        let addAction = UIAlertAction(title: "Add", style: .default) { [weak self] _ in
            guard let name = alert.textFields?.first?.text, !name.isEmpty else { return }
            let newHabit = Habit(name: name, completed: false, streak: 0)
            self?.habits.append(newHabit)
            self?.saveHabits()
            self?.tableView.reloadData()
        }
        let cancelAction = UIAlertAction(title: "Cancel", style: .cancel)
        alert.addAction(addAction)
        alert.addAction(cancelAction)
        present(alert, animated: true)
    }

    func loadHabits() {
        if let data = defaults.data(forKey: "habits"), let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            habits = decoded
        }
    }

    func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            defaults.set(encoded, forKey: "habits")
        }
    }

    override func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        return habits.count
    }

    override func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "HabitCell", for: indexPath)
        let habit = habits[indexPath.row]
        cell.textLabel?.text = habit.name
        cell.accessoryType = habit.completed ? .checkmark : .none
        return cell
    }

    override func tableView(_ tableView: UITableView, didSelectRowAt indexPath: IndexPath) {
        let habit = habits[indexPath.row]
        habit.completed.toggle()
        habits[indexPath.row] = habit
        saveHabits()
        tableView.reloadRows(at: [indexPath], with: .none)
    }
}
```

