import UIKit

class HabitDetailViewController: UIViewController {
    var habit: Habit!
    var streak: Int = 0

    override func viewDidLoad() {
        super.viewDidLoad()
        title = habit.name
        let checkmarkButton = UIBarButtonItem(title: "Mark Complete", style: .plain, target: self, action: #selector(markComplete))
        navigationItem.rightBarButtonItem = checkmarkButton
    }

