### 📌 **3. Habit Manager (UserDefaults)**
Add a helper class to manage habit data persistence.  
```swift
import Foundation

class HabitManager {
    static let shared = HabitManager()
    private let userDefaults = UserDefaults(suiteName: "group.com.yourapp")!

    func saveHabits(_ habits: [Habit]) {
        if let encoded = try? JSONEncoder().encode(habits) {
            userDefaults.set(encoded, forKey: "habits")
        }
    }

    func loadHabits() -> [Habit] {
        if let data = userDefaults.data(forKey: "habits") {
            return try! JSONDecoder().decode([Habit].self, from: data)
        }
        return []
    }

    func addHabit(_ habit: Habit) {
        var habits = loadHabits()
        habits.append(habit)
        saveHabits(habits)
    }

    func toggleCompletion(for habit: Habit) -> Habit {
        var updatedHabit = habit
        updatedHabit.isCompleted.toggle()
        updatedHabit.lastCompletedDate = updatedHabit.isCompleted ? Date() : nil
        return updatedHabit
    }
}
