import SwiftUI

// MARK: - Models
struct Habit: Identifiable, Codable {
    let id: UUID
    let name: String
    var isCompleted: Bool
    var lastCompletedDate: Date?

    init(name: String) {
        self.id = UUID()
        self.name = name
        self.isCompleted = false
        self.lastCompletedDate = nil
    }
}

// MARK: - View Model
class HabitViewModel: ObservableObject {
    @Published var habits: [Habit] = []

    func saveHabits() {
        if let encoded = try? JSONEncoder().encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits"),
           let decoded = try? JSONDecoder().decode([Habit].self, from: data) {
            self.habits = decoded
        }
    }

    func addHabit(name: String) {
        let habit = Habit(name: name)
        habits.append(habit)
        saveHabits()
    }

    func toggleCompletion(for habit: Habit) {
        var updatedHabit = habit
        updatedHabit.isCompleted.toggle()
        if updatedHabit.isCompleted {
            updatedHabit.lastCompletedDate = Date()
        }
        if let index = habits.firstIndex(where: { $0.id == habit.id }) {
            habits[index] = updatedHabit
            saveHabits()
        }
    }
}

// MARK: - Views
struct ContentView: View {
    @StateObject private var viewModel = HabitViewModel()

    var body: some View {
        NavigationView {
            VStack {
                HStack {
                    Text("Habit Tracker")
                        .font(.largeTitle)
                        .padding()
                    Spacer()
                }

                List {
                    ForEach(viewModel.habits) { habit in
                        HStack {
                            Text(habit.name)
                                .padding()
                            Spacer()
                            Toggle(isOn: Binding(get: { habit.isCompleted }, set: { value in
                                viewModel.toggleCompletion(for: habit)
                            })) {
                                Image(systemName: "checkmark.circle.fill")
                                    .foregroundColor(.green)
                            }
                        }
                        .padding(.vertical, 2)
                    }
                    .onDelete { indexSet in
                        viewModel.habits.remove(atOffsets: indexSet)
                        viewModel.saveHabits()
                    }
                }

                NavigationLink("Add Habit") {
                    AddHabitView(viewModel: viewModel)
                }
            }
            .navigationTitle("Habits")
            .onAppear {
                viewModel.loadHabits()
            }
        }
    }
}

