                    HStack {
                        Text(habit.name)
                            .padding(.trailing, 10)

                        Toggle("", isOn: Binding(
                            get: { habit.completed },
                            set: { viewModel.toggleHabitCompletion(id: habit.id) }
                        ))
                        .onChange(of: habit.completed) { _ in
                            viewModel.saveHabits()
                        }
                    }
                }
            }
            .navigationTitle("Habit Tracker")
            .toolbar {
                Button("Add Habit") {
                    showingAddHabit = true
                }
            }
