import SwiftUI

// MARK: - Habit Model
struct Habit: Identifiable, Codable {
    let id: UUID
    var name: String
    var isDone: Bool

    init(id: UUID = UUID(), name: String, isDone: Bool = false) {
        self.id = id
        self.name = name
        self.isDone = isDone
    }
}

// MARK: - View
struct ContentView: View {
    @State private var habits: [Habit] = []
    @State private var newHabitName: String = ""

    var body: some View {
        NavigationView {
            List {
                // Display habits
                ForEach(habits) { habit in
                    HStack {
                        Text(habit.name)
                        Spacer()
                        Toggle("", isOn: $habits.first(where: { $0.id == habit.id })?.isDone ?? false)
                            .onChange(of: habit.isDone) { newValue in
                                saveHabits()
                            }
                    }
                }
                .onDelete(perform: deleteHabit)
            }
            .navigationTitle("Habit Tracker")
            .toolbar {
                ToolbarItem(placement: .navigationBarTrailing) {
                    Button("Add") {
                        addHabit()
                    }
                }
            }
        }
        .onAppear(perform: loadHabits)
    }

    // MARK: - Actions
    func addHabit() {
        let newHabit = Habit(name: newHabitName)
        habits.append(newHabit)
        saveHabits()
        newHabitName = ""
    }

    func deleteHabit(at offsets: IndexSet) {
        habits.remove(atOffsets: offsets)
        saveHabits()
    }

    func saveHabits() {
        let encoder = JSONEncoder()
        if let encoded = try? encoder.encode(habits) {
            UserDefaults.standard.set(encoded, forKey: "habits")
        }
    }

    func loadHabits() {
        if let data = UserDefaults.standard.data(forKey: "habits") {
            let decoder = JSONEncoder()
            if let decoded = try? decoder.decode([Habit].self, from: data) {
                habits = decoded
            }
        }
    }
}
