### **3. Main Activity (UI + Logic):**
```kotlin
class MainActivity : AppCompatActivity() {
    private lateinit var db: AppDatabase
    private lateinit var account: Account
    private lateinit var transactionList: List<Transaction>

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        // Initialize Room database
        db = Room.databaseBuilder(
            applicationContext,
            AppDatabase::class.java,
            "banking_db"
        ).build()

        // Initialize account (or fetch from DB)
        account = db.accountDao().getAccount() ?: Account(1, 1000.0)
        db.accountDao().insertAccount(account)

        // Load transactions
        transactionList = db.transactionDao().getAllTransactions()

        // Update UI
        updateUI()
    }

    private fun updateUI() {
        findViewById<TextView>(R.id.balanceTextView).text = "Balance: $${account.balance}"
        findViewById<ListView>(R.id.transactionsListView).adapter = ArrayAdapter(
            this,
            android.R.layout.simple_list_item_1,
            transactionList.map { "${it.type} $${it.amount}" }
        )
    }

    // Example: Add a deposit
    fun addDeposit(view: View) {
        val amount = 500.0
        account.balance += amount
        db.accountDao().updateAccount(account)

        val transaction = Transaction(
            id = System.currentTimeMillis(),
            type = "deposit",
            amount = amount
        )
        db.transactionDao().insertTransaction(transaction)

        updateUI()
    }

    // Example: Withdraw funds
    fun withdrawFunds(view: View) {
        val amount = 200.0
        if (account.balance >= amount) {
            account.balance -= amount
            db.accountDao().updateAccount(account)

            val transaction = Transaction(
                id = System.currentTimeMillis(),
                type = "withdrawal",
                amount = amount
            )
            db.transactionDao().insertTransaction(transaction)

            updateUI()
        } else {
            Toast.makeText(this, "Insufficient funds", Toast.LENGTH_SHORT).show()
        }
    }
}
```

