```dart
// main.dart
import 'package:flutter/material.dart';
import 'package:sqflite/sqflite.dart';
import 'package:http/http.dart' as http;
import 'package:connectivity_plus/connectivity_plus.dart';

// Database helper class
class SurveyDatabase {
  static final _databaseName = 'survey.db';
  static final _version = 1;

  static final _tableName = 'surveys';
  static final _columns = {
    'id': 'INTEGER PRIMARY KEY AUTOINCREMENT',
    'timestamp': 'TEXT',
    'location': 'TEXT',
    'notes': 'TEXT',
    'synced': 'BOOLEAN DEFAULT FALSE'
  };

  static final _db = openDatabase(
    inMemoryDatabasePath,
    version: _version,
    onCreate: _onCreate,
  );

  static Future<void> _onCreate(Database db, int version) async {
    await db.execute('''
      CREATE TABLE IF NOT EXISTS $(_tableName) (
        ${_columns['id']}, 
        ${_columns['timestamp']}, 
        ${_columns['location']}, 
        ${_columns['notes']}, 
        ${_columns['synced']}
      )
    ''');
  }

  static Future<void> saveSurvey({
    required String timestamp,
    required String location,
    required String notes,
  }) async {
    final db = await _db;
    await db.insert(
      _tableName,
      {
        'timestamp': timestamp,
        'location': location,
        'notes': notes,
      },
    );
  }

  static Future<List<Map<String, dynamic>>> getUnsyncedSurveys() async {
    final db = await _db;
    return await db.query(
      _tableName,
      where: 'synced = ?',
      whereArgs: [0],
    );
  }

  static Future<void> markAsSynced(int id) async {
    final db = await _db;
    await db.update(
      _tableName,
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}

// Sync service
class SyncService {
  static Future<void> syncSurveys() async {
    final connectivityResult = await Connectivity().checkConnectivity();

    if (connectivityResult != ConnectivityResult.none) {
      try {
        final unsynced = await SurveyDatabase.getUnsyncedSurveys();

        if (unsynced.isNotEmpty) {
          final response = await http.post(
            Uri.parse('https://your-api.com/sync'),
            headers: {'Content-Type': 'application/json'},
            body: jsonEncode(unsynced.map((s) => s['data']).toList()),
          );

          if (response.statusCode == 200) {
            for (final item in unsynced) {
              await SurveyDatabase.markAsSynced(item['id']);
            }
          }
        }
      } catch (e) {
        // Handle sync error (e.g., retry, log)
        print('Sync failed: $e');
      }
    }
  }
}

// Main app
