  final _formKey = GlobalKey<FormState>();
  final _timestampController = TextEditingController();
  final _locationController = TextEditingController();
  final _notesController = TextEditingController();

  @override
  void initState() {
    super.initState();
    // Sync when app starts
    SyncService.syncSurveys();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Field Survey')),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Form(
          key: _formKey,
          child: Column(
            children: [
              TextFormField(
                controller: _timestampController,
                decoration: InputDecoration(labelText: 'Timestamp'),
                validator: (value) {
                  if (value == null || value.isEmpty) {
                    return 'Please enter a timestamp';
                  }
                  return null;
                },
              ),
              TextFormField(
                controller: _locationController,
                decoration: InputDecoration(labelText: 'Location'),
                validator: (value) {
                  if (value == null || value.isEmpty) {
                    return 'Please enter a location';
                  }
                  return null;
                },
              ),
              TextFormField(
                controller: _notesController,
                decoration: InputDecoration(labelText: 'Notes'),
                maxLines: 3,
              ),
              SizedBox(height: 16),
              ElevatedButton(
                onPressed: () async {
                  if (_formKey.currentState!.validate()) {
                    final timestamp = _timestampController.text;
                    final location = _locationController.text;
                    final notes = _notesController.text;

                    await SurveyDatabase.saveSurvey(
                      timestamp: timestamp,
                      location: location,
                      notes: notes,
                    );

                    // Clear form
