class _SurveyAppState extends State<SurveyApp> {
  final dbHelper = SurveyDatabase();
  bool isOnline = true;

  @override
  void initState() {
    super.initState();
    _checkConnectivity();
    Connectivity().onConnectivityChanged.listen((connectivityResult) {
      setState(() {
        isOnline = connectivityResult != ConnectivityResult.none;
      });
      if (isOnline) {
        syncData();
      }
    });
  }

  Future<void> _checkConnectivity() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    setState(() {
      isOnline = connectivityResult != ConnectivityResult.none;
    });
    if (isOnline) {
      syncData();
    }
  }

  Future<void> syncData() async {
    final unsynced = await dbHelper.getUnsyncedSurveys();
    if (unsynced.isNotEmpty) {
      try {
        final response = await http.post(
          Uri.parse('https://your-server.com/api/sync'),
          body: {
            'surveys': jsonEncode(unsynced.map((s) => {
              'id': s['id'],
              'name': s['name'],
              'location': s['location'],
              'timestamp': s['timestamp'],
            }).toList()),
          },
        );
        if (response.statusCode == 200) {
          for (var item in unsynced) {
            await dbHelper.markAsSynced(item['id']);
          }
        } else {
          print('Sync failed: ${response.reasonPhrase}');
        }
      } catch (e) {
        print('Sync error: $e');
      }
    }
  }

  void _addSurvey() {
    dbHelper.addSurvey('Test Survey', 'Test Location');
