```dart
import 'package:firebase_database/firebase_database.dart';
import 'package:firebase_core/firebase_core.dart';
import 'package:flutter/services.dart';
import 'database/database_helper.dart';

class FirebaseService {
  static final FirebaseDatabase _instance = FirebaseDatabase.instance;
  static DatabaseReference get ref => _instance.ref();

  static Future<void> initializeApp() async {
    await Firebase.initializeApp();
  }

  static Future<void> syncSurveys() async {
    final dbHelper = DatabaseHelper();
    final List<Survey> localSurveys = await dbHelper.getAllSurveys();

    for (final survey in localSurveys) {
      if (!survey.id.startsWith('synced_')) {
        final snapshot = await ref.child('surveys').push();
        await snapshot.set(survey.toMap());
        await dbHelper.updateSurveyStatus(survey.id, 'synced');
      }
    }
  }

  static Future<void> updateSurveyStatus(String id, String status) async {
    final dbHelper = DatabaseHelper();
    await dbHelper.updateSurveyStatus(id, status);
  }
}
