```javascript
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, FlatList, Alert } from 'react-native';
import SQLite from 'react-native-sqlite-storage';
import NetInfo from '@react-native-community/netinfo';

// Initialize SQLite database
const db = SQLite.openDatabase({
  name: 'survey.db',
  location: 'default',
});

// Create table on app start
useEffect(() => {
  db.transaction(tx => {
    tx.executeSql(
      'CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT, data TEXT)',
      [],
      () => console.log('Table created'),
      error => console.error('Error creating table', error)
    );
  });
}, []);

// Sync data to backend when online
const syncData = async () => {
  try {
    const result = await db.transaction(tx => {
      return new Promise((resolve, reject) => {
        tx.executeSql(
          'SELECT * FROM surveys WHERE synced = 0',
          [],
          (_, { rows: { _array } }) => {
            if (_array.length === 0) {
              resolve();
              return;
            }

            // Mock API call to sync data
            const syncPromises = _array.map(survey => {
              return fetch('https://your-backend.com/api/sync', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(survey),
              });
            });

            Promise.all(syncPromises)
              .then(responses => {
                // Mark synced rows
                db.transaction(tx => {
                  tx.executeSql(
                    'UPDATE surveys SET synced = 1 WHERE synced = 0',
                    [],
                    () => resolve(),
                    error => reject(error)
                  );
                });
              })
              .catch(error => reject(error));
          },
          error => reject(error)
        );
      });
    });

    Alert.alert('Success', 'Data synced successfully!');
  } catch (error) {
    Alert.alert('Error', 'Failed to sync data. Check your connection.');
    console.error('Sync error:', error);
  }
};

// Check connectivity and sync
useEffect(() => {
  const unsubscribe = NetInfo.addEventListener(state => {
    if (state.isConnected) {
      syncData();
    }
  });
  return () => unsubscribe();
}, []);

// Add survey data
const addSurvey = (data) => {
  db.transaction(tx => {
    tx.executeSql(
      'INSERT INTO surveys (timestamp, data) VALUES (?, ?)',
      [new Date().toISOString(), data],
      (_, { insertId }) => {
        console.log('Survey added with ID:', insertId);
      },
      error => console.error('Error adding survey', error)
    );
  });
};

// Render surveys
const renderSurvey = ({ item }) => (
  <View style={{ padding: 10, borderBottomWidth: 1, borderColor: '#ccc' }}>
    <Text>Timestamp: {item.timestamp}</Text>
    <Text>Data: {item.data}</Text>
  </View>
);

export default function App() {
  const [input, setInput] = useState('');
  const [surveys, setSurveys] = useState([]);

  // Load surveys from local DB
  useEffect(() => {
    db.transaction(tx => {
      tx.executeSql(
        'SELECT * FROM surveys',
        [],
        (_, { rows: { _array } }) => {
          setSurveys(_array);
        },
        error => console.error('Error loading surveys', error)
      );
    });
  }, []);

  const handleAdd = () => {
    if (input.trim()) {
      addSurvey(input);
      setInput('');
    }
  };

  return (
    <View style={{ padding: 20 }}>
      <TextInput
        value={input}
        onChangeText={setInput}
        placeholder="Enter survey data"
        style={{ borderWidth: 1, padding: 10, marginBottom: 10 }}
      />
      <Button title="Add Survey" onPress={handleAdd} />
      <FlatList
        data={surveys}
        renderItem={renderSurvey}
        keyExtractor={item => item.id.toString()}
      />
    </View>
  );
}
