import 'package:connectivity/connectivity.dart';

// Define your Survey model
class Survey {
  final String id;
  final String name;
  final String timestamp;
  final String data;

  Survey({
    required this.id,
    required this.name,
    required this.timestamp,
    required this.data,
  });

  // Convert to Map for Hive
  Map<String, dynamic> toJson() {
    return {
      'id': id,
      'name': name,
      'timestamp': timestamp,
      'data': data,
    };
  }

  // Factory constructor from Map
  factory Survey.fromJson(Map<String, dynamic> json) {
    return Survey(
      id: json['id'],
      name: json['name'],
      timestamp: json['timestamp'],
      data: json['data'],
    );
  }
}

// Hive adapter for Survey
class SurveyAdapter extends HiveAdapter {
  @override
  Future<void> configure() async {
    await registerAdapter(SurveyAdapter());
  }

  @override
  Future<void> registerAdapter() async {
    await registerAdapter(SurveyAdapter());
  }
}

void main async () {
  WidgetsFlutterBinding.ensureInitialized();
  await Hive.initFlutter();
  Hive.registerAdapter(SurveyAdapter());
  await Hive.openBox('surveys');
