class _SurveyFormPageState extends State<SurveyFormPage> {
  final _formKey = GlobalKey<FormState>();
  final _nameController = TextEditingController();
  final _dataController = TextEditingController();
  final _box = Hive.box('surveys');

  @override
  void dispose() {
    _nameController.dispose();
    _dataController.dispose();
    super.dispose();
  }

  Future<void> _saveSurvey() async {
    if (_formKey.currentState!.validate()) {
      final now = DateTime.now().toString();
      final id = DateTime.now().microsecondsSinceEpoch.toString();
      final survey = Survey(
        id: id,
        name: _nameController.text,
        timestamp: now,
        data: _dataController.text,
      );

      await _box.add(survey.toJson());
      _formKey.currentState!.reset();
      _nameController.clear();
      _dataController.clear();
      _showSnackbar('Survey saved offline');
    }
  }

  Future<void> _syncSurveys() async {
    final connectivityResult = await (Connectivity().checkConnectivity());
    if (connectivityResult == ConnectivityResult.none) {
      _showSnackbar('No internet connection. Sync failed.');
      return;
    }

    final List<dynamic> unsynced = _box.values.toList();
    if (unsynced.isEmpty) {
      _showSnackbar('No unsynced surveys.');
      return;
    }

    try {
      final response = await http.post(
        Uri.parse('https://your-backend.com/api/sync'), // Replace with your backend
        body: {
          'surveys': jsonEncode(unsynced),
        },
      );

      if (response.statusCode == 200) {
        _box.clear();
        _showSnackbar('Surveys synced successfully!');
      } else {
        _showSnackbar('Failed to sync surveys. Status code: ${response.statusCode}');
      }
    } catch (e) {
      _showSnackbar('Sync error: $e');
    }
  }

  void _showSnackbar(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message)),
    );
  }

