#### **3.2. Data Service (services/data_service.dart)**
```dart
import 'package:hive_flutter/hive_flutter.dart';
import 'package:connectivity_plus/connectivity_plus.dart';
import 'package:http/http.dart' as http;
import 'package:field_survey_app/models/survey.dart';

class DataService {
  static final _box = Hive.box('surveys');

  // Save survey locally
  static Future<void> saveSurvey(Survey survey) async {
    await _box.add(survey.toMap());
  }

  // Get all unsynced surveys
  static List<Survey> getUnsyncedSurveys() {
    final List<dynamic> surveysData = _box.values.toList();
    return surveysData.map((data) => Survey.fromMap(data)).toList();
  }

  // Sync data to backend
  static Future<void> syncSurveys() async {
    final List<Survey> surveys = getUnsyncedSurveys();
    if (surveys.isEmpty) return;

    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult != ConnectivityResult.none) {
      for (var survey in surveys) {
        try {
          final response = await http.post(
            Uri.parse('https://your-api.com/sync'), // Replace with your backend URL
            body: survey.toMap(),
          );
          if (response.statusCode == 200) {
            _box.delete(survey.id); // Mark as synced
          }
        } catch (e) {
          print('Sync failed: $e');
        }
      }
    }
  }
}
