### 🧩 **1. Database Setup** (`database_helper.dart`)
```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._privateConstructor();
  static Database? _database;
  factory DatabaseHelper() => _instance;

  DatabaseHelper._privateConstructor();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  Future<Database> _initDatabase() async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, 'survey.db');
    return await openDatabase(path, version: 1, onCreate: _onCreate);
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute('''
      CREATE TABLE surveys(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        date TEXT
      )
    ''');
    await db.execute('''
      CREATE TABLE survey_entries(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        survey_id INTEGER,
        question TEXT,
        answer TEXT,
        FOREIGN KEY(survey_id) REFERENCES surveys(id)
      )
    ''');
  }

  Future<void> addSurvey(String name, DateTime date) async {
    final db = await database;
    await db.insert(
      'surveys',
      {'name': name, 'date': date.toIso8601String()},
    );
  }

  Future<void> addSurveyEntry(int surveyId, String question, String answer) async {
    final db = await database;
    await db.insert(
      'survey_entries',
      {'survey_id': surveyId, 'question': question, 'answer': answer},
    );
  }

  Future<List<Map<String, dynamic>>> getUnsyncedSurveys() async {
    final db = await database;
    return await db.query('surveys');
  }
}
