### 🔄 **3. Sync Logic** (`sync_service.dart`)
```dart
import 'package:flutter/material.dart';
import 'package:connectivity/connectivity.dart';
import 'package:http/http.dart' as http;
import 'database_helper.dart';

class SyncService {
  static Future<void> syncData() async {
    final connectivityResult = await Connectivity().checkConnectivity();
    if (connectivityResult != ConnectivityResult.none) {
      final surveys = await DatabaseHelper().getUnsyncedSurveys();
      for (var survey in surveys) {
        final surveyId = survey['id'];
        final entries = await DatabaseHelper().querySurveyEntries(surveyId);
        final response = await http.post(
          Uri.parse('https://your-backend.com/api/sync'), // Replace with your backend
          body: {
            'surveyId': surveyId.toString(),
            'entries': entries.map((e) => e['question'] + ': ' + e['answer']).join(';'),
          },
        );
        if (response.statusCode == 200) {
          await DatabaseHelper().markSurveyAsSynced(surveyId);
        }
      }
    }
  }

  static Future<void> markSurveyAsSynced(int surveyId) async {
    final db = await DatabaseHelper().database;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [surveyId],
    );
  }
}
