#### **`sync_service.dart`**
```dart
import 'package:http/http.dart' as http;
import 'package:hive_flutter/hive_flutter.dart';
import 'package:connectivity/connectivity.dart';

class SyncService {
  Future<void> syncSurveys() async {
    final box = Hive.box('surveyData');
    final unsyncedSurveys = box.values.where((survey) => survey['synced'] == null).toList();

    if (unsyncedSurveys.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('No unsynced data.')),
      );
      return;
    }

    try {
      final response = await http.post(
        Uri.parse('https://your-backend.com/api/sync'),
        headers: {'Content-Type': 'application/json'},
        body: jsonEncode(unsyncedSurveys),
      );

      if (response.statusCode == 200) {
        for (var survey in unsyncedSurveys) {
          survey['synced'] = true;
          box.put(box.keyAt(box.values.indexOf(survey)), survey);
        }
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Data synced successfully!')),
        );
      } else {
        throw Exception('Failed to sync data');
      }
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('Sync failed: $e')),
      );
    }
  }
}
