import 'package:sqflite/sqflite.dart';
import 'package:sqflite/sqlite_api.dart';
import 'package:path/path.dart';
import 'package:survey_app/models/survey_model.dart';

class SurveyDB {
  static final _databaseName = 'survey.db';
  static final _version = 1;

  static final table = 'surveys';
  static final idColumn = 'id';
  static final nameColumn = 'name';
  static final locationColumn = 'location';
  static final timestampColumn = 'timestamp';

  static final SurveyDB _instance = SurveyDB._init();
  factory SurveyDB() => _instance;

  SurveyDB._init();

  Future<Database> get database async {
    final dbPath = await getDatabasesPath();
    final path = join(dbPath, _databaseName);
    return await openDatabase(path, version: _version, onCreate: _onCreate);
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute('''
      CREATE TABLE $table (
        $idColumn INTEGER PRIMARY KEY AUTOINCREMENT,
        $nameColumn TEXT NOT NULL,
        $locationColumn TEXT NOT NULL,
        $timestampColumn DATETIME NOT NULL
      )
    ''');
  }

  Future<void> addSurvey(Survey survey) async {
    final db = await database;
    await db.insert(table, survey.toJson());
  }

  Future<List<Survey>> getAllSurveys() async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query(table);
    return List.generate(maps.length, (i) => Survey.fromJson(maps[i]));
  }

  Future<void> deleteSurvey(int id) async {
    final db = await database;
    await db.delete(table, where: '$idColumn = ?', whereArgs: [id]);
  }
}
