import 'package:http/http.dart' as http;
import 'dart:convert';
import 'package:survey_app/models/survey_model.dart';
import 'package:survey_app/database/survey_db.dart';
import 'package:survey_app/utils/connectivity_utils.dart';

class SyncService {
  static const _syncUrl = 'https://your-backend.com/api/sync'; // Replace with your backend

  static Future<void> syncSurveys() async {
    final db = await SurveyDB().database;
    final surveys = await SurveyDB().getAllSurveys();

    if (surveys.isEmpty) return;

    final jsonList = surveys.map((survey) => survey.toJson()).toList();
    final response = await http.post(
      Uri.parse(_syncUrl),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(jsonList),
    );

    if (response.statusCode == 200) {
      // Mark surveys as synced (optional)
      for (var survey in surveys) {
        await SurveyDB().deleteSurvey(survey.id);
      }
    } else {
      print('Sync failed: ${response.statusCode}');
    }
  }
}
