### **5. Display Surveys (`SurveyList.js`)**
```javascript
import React, { useEffect, useState } from 'react';
import { View, FlatList, Text } from 'react-native';
import { db } from './db';

export default function SurveyList() {
  const [surveys, setSurveys] = useState([]);

  useEffect(() => {
    const onChange = (change) => {
      setSurveys(change.docs.map((doc) => ({ ...doc, _id: doc._id })));
    };

    db.changes({ since: 'now', live: true, include_docs: true }).on('change', onChange);

    return () => db.cancel();
  }, []);

  return (
    <View style={{ padding: 20 }}>
      <Text style={{ fontSize: 20, marginBottom: 10 }}>Survey History</Text>
      <FlatList
        data={surveys}
        keyExtractor={(item) => item._id}
        renderItem={({ item }) => (
          <View style={{ marginBottom: 10, padding: 10, backgroundColor: '#f0f0f0' }}>
            <Text>{item.name} - {item.location}</Text>
            <Text>{item.timestamp}</Text>
          </View>
        )}
      />
    </View>
  );
}
