const String _syncUrl = 'https://api.example.com/sync';

// Survey model
class Survey {
  final int id;
  final String name;
  final String location;
  final DateTime timestamp;

  Survey({required this.id, required this.name, required this.location, required this.timestamp});
}

// Database helper
class SurveyDB {
  static final _dbName = 'survey.db';
  static final _dbVersion = 1;

  static Database? _database;

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  Future<Database> _initDatabase() async {
    String path = join(await getDatabasesPath(), _dbName);
    return await openDatabase(path, version: _dbVersion, onCreate: _onCreate);
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute('CREATE TABLE surveys(id INTEGER PRIMARY KEY, name TEXT, location TEXT, timestamp DATETIME)');
  }

  Future<void> addSurvey(Survey survey) async {
    final db = await database;
    await db.insert(
      'surveys',
      survey.toMap(),
      conflictAlgorithm: ConflictAlgorithm.replace,
    );
  }

  Future<List<Survey>> getSurveys() async {
    final db = await database;
    final List<Map<String, dynamic>> maps = await db.query('surveys');
    return List.generate(maps.length, (i) => Survey.fromMap(maps[i]));
  }
}

extension SurveyMap on Survey {
  Map<String, dynamic> toMap() {
    return {
      'name': name,
      'location': location,
      'timestamp': timestamp.toIso8601String(),
    };
  }
}

extension SurveyFromMap on Map<String, dynamic> {
  Survey fromMap() {
    return Survey(
      id: this['id'] as int,
      name: this['name'] as String,
      location: this['location'] as String,
      timestamp: DateTime.parse(this['timestamp'] as String),
    );
  }
}

// Sync data to backend
Future<void> syncSurveys() async {
  final db = await SurveyDB().database;
  final List<Map<String, dynamic>> maps = await db.query('surveys');
  final List<Survey> surveys = List.generate(maps.length, (i) => Survey.fromMap(maps[i]));

  if (surveys.isEmpty) return;

  try {
    final response = await http.post(
      Uri.parse(_syncUrl),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(surveys.map((s) => s.toMap()).toList()),
    );

    if (response.statusCode == 200) {
      // Clear local data after successful sync
      await db.delete('surveys');
    }
  } catch (e) {
    print('Sync failed: $e');
  }
}

