    final path = join(dbPath, _dbName);
    return openDatabase(
      path,
      version: _dbVersion,
      onCreate: (db, version) async {
        await db.execute(
          'CREATE TABLE $ _tableName ('
          '${_columns['id']}, '
          '${_columns['location']}, '
          '${_columns['timestamp']}, '
          '${_columns['notes']})',
        );
      },
    );
  }

  // Save survey data locally
