  // Fetch all surveys
  static Future<List<Map<String, dynamic>>> getSurveys() async {
    final db = await db;
    return await db.query(_tableName);
  }

  // Delete all surveys
  static Future<void> deleteAllSurveys() async {
    final db = await db;
    await db.delete(_tableName);
  }
}

