  final connectivityResult = await Connectivity().checkConnectivity();
  if (connectivityResult == ConnectivityResult.none) {
    print('No internet connection. Sync skipped.');
    return;
  }

  final surveys = await SurveyDB.getSurveys();
  if (surveys.isEmpty) return;

  final url = Uri.parse('https://your-backend.com/api/sync'); // Replace with your server
  final response = await http.post(
    url,
    headers: {'Content-Type': 'application/json'},
    body: jsonEncode(surveys.map((s) => s).toList()),
  );

  if (response.statusCode == 200) {
    print('Sync successful. Deleting local data...');
    await SurveyDB.deleteAllSurveys();
  } else {
    print('Sync failed: ${response.statusCode}');
  }
}

