const String syncUrl = 'https://jsonplaceholder.typicode.com/posts';

// Database helper
class SurveyDB {
  static final SurveyDB _instance = SurveyDB._init();
  factory SurveyDB() => _instance;

  static Database? _db;

  Future<Database> get db async {
    if (_db != null) return _db!;
    _db = await _initDB();
    return _db!;
  }

  Future<Database> _initDB() async {
    String path = join(await getDatabasesPath(), 'survey.db');
    return openDatabase(path, onCreate: _onCreate, version: 1);
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute(
      'CREATE TABLE surveys(id INTEGER PRIMARY KEY AUTOINCREMENT, timestamp TEXT, location TEXT, notes TEXT)',
    );
  }

  Future<void> addSurvey(String timestamp, String location, String notes) async {
    final db = await db;
    await db.insert(
      'surveys',
      {'timestamp': timestamp, 'location': location, 'notes': notes},
    );
  }

  Future<List<Map<String, dynamic>>> getUnsyncedSurveys() async {
    final db = await db;
    return await db.query('surveys', where: 'synced = ?', whereArgs: [0]);
  }

  Future<void> markAsSynced(int id) async {
    final db = await db;
    await db.update(
      'surveys',
      {'synced': 1},
      where: 'id = ?',
      whereArgs: [id],
    );
  }
}

// Sync function
Future<void> syncSurveys() async {
  try {
    final connectivityResult = await (Connectivity().checkConnectivity());
    if (connectivityResult != ConnectivityResult.wifi && connectivityResult != ConnectivityResult.mobile) {
      print("No internet connection. Skipping sync.");
      return;
    }

    final surveys = await SurveyDB().getUnsyncedSurveys();
    if (surveys.isEmpty) {
      print("No unsynced surveys to sync.");
      return;
    }

    final response = await http.post(
      Uri.parse(syncUrl),
      headers: {'Content-Type': 'application/json'},
      body: jsonEncode(surveys.map((s) => {
        'timestamp': s['timestamp'],
        'location': s['location'],
        'notes': s['notes']
      }).toList()),
    );

    if (response.statusCode == 200) {
      for (final survey in surveys) {
        await SurveyDB().markAsSynced(survey['id']);
      }
      print("Synced ${surveys.length} surveys.");
    } else {
      print("Failed to sync surveys: ${response.statusCode}");
    }
  } catch (e) {
    print("Sync error: $e");
  }
}

