      'surveys',
      {'timestamp': timestamp, 'location': location, 'notes': notes},
    );
  }

  Future<List<Map<String, dynamic>>> getSurveys() async {
    final List<Map<String, dynamic>> result = await _db.query('surveys');
    return result;
  }
}

// Firebase Sync
class SyncService {
  final FirebaseFirestore _db = FirebaseFirestore.instance;

  Future<void> syncSurveys() async {
    final db = SurveyDB();
    await db.init();
    final List<Map<String, dynamic>> surveys = await db.getSurveys();

    for (var survey in surveys) {
      await _db.collection('surveys').add({
        'timestamp': survey['timestamp'],
        'location': survey['location'],
        'notes': survey['notes'],
      });
    }

    // Clear local data after sync
    await db._db.delete('surveys');
  }
}

