### 📁 **database_helper.dart**  
```dart
import 'package:sqflite/sqflite.dart';
import 'package:path/path.dart';

class DatabaseHelper {
  static final DatabaseHelper _instance = DatabaseHelper._init();
  static Database? _database;
  factory DatabaseHelper() => _instance;

  DatabaseHelper._init();

  Future<Database> get database async {
    if (_database != null) return _database!;
    _database = await _initDatabase();
    return _database!;
  }

  Future<Database> _initDatabase() async {
    String path = join(await getDatabasesPath(), 'survey.db');
    return openDatabase(path, onCreate: _onCreate, version: 1);
  }

  Future<void> _onCreate(Database db, int version) async {
    await db.execute(
      'CREATE TABLE surveys(id INTEGER PRIMARY KEY AUTOINCREMENT, location TEXT, notes TEXT, timestamp TEXT)',
    );
  }

  Future<int> insertSurvey(Map<String, dynamic> survey) async {
    final db = await database;
    return await db.insert('surveys', survey);
  }

  Future<List<Map<String, dynamic>>> getAllSurveys() async {
    final db = await database;
    return await db.query('surveys');
  }

  Future<void> deleteSurvey(int id) async {
    final db = await database;
    await db.delete('surveys', where: 'id = ?', whereArgs: [id]);
  }
}
