    const { userId, text } = data;
    const message = new Message({ userId, text });
    message.save();
    io.to(userId).emit('receiveMessage', data);
  });

  // Real-time notification
  socket.on('notify', (userId) => {
    io.to(userId).emit('notification', { message: 'New message received!' });
  });

  socket.on('disconnect', () => {
    console.log('User disconnected');
  });
});

