### 🧩 **4. Frontend (React + Chart.js)**

**`client/App.js`**:
```javascript
import React, { useEffect, useState } from 'react';
import Chart from 'chart.js/auto';

function App() {
  const [formData, setFormData] = useState({ value: '' });
  const [dataPoints, setDataPoints] = useState([]);

  // Initialize chart
  useEffect(() => {
    const ctx = document.getElementById('dataChart').getContext('2d');
    const chart = new Chart(ctx, {
      type: 'line',
      data: {
        labels: [],
        datasets: [{
          label: 'Real-Time Data',
          data: [],
          borderColor: 'blue',
          fill: false,
        }]
      },
      options: {
        responsive: true,
        animation: false,
      }
    });

    // WebSocket connection
    const ws = new WebSocket('ws://localhost:5000');

    ws.onmessage = (event) => {
      const newData = JSON.parse(event.data);
      setDataPoints(newData);
      chart.data.labels = newData.map(dp => new Date(dp.timestamp).toLocaleTimeString());
      chart.data.datasets[0].data = newData.map(dp => dp.value);
      chart.update();
    };

    // Form submission
    const handleFormSubmit = (e) => {
      e.preventDefault();
      if (formData.value.trim()) {
        ws.send(JSON.stringify({ value: formData.value }));
        setFormData({ value: '' });
      }
    };

    return () => {
      ws.close();
      chart.destroy();
    };
  }, []);

  return (
    <div style={{ padding: '20px' }}>
      <h1>Real-Time Dashboard</h1>
      <form onSubmit={(e) => handleFormSubmit(e)}>
        <input
          type="number"
          placeholder="Enter value"
          value={formData.value}
          onChange={(e) => setFormData({ ...formData, value: e.target.value })}
          required
        />
        <button type="submit">Add Data</button>
      </form>
      <canvas id="dataChart" style={{ marginTop: '20px' }}></canvas>
    </div>
  );
}

export default App;
```

