### 📜 `content.js`
```javascript
// List of known tracking domains (example)
const trackingDomains = [
  "tracking.example.com",
  "ads.example.net",
  "analytics.example.org"
];

// Function to check if a URL is a tracking script
function isTrackingScript(url) {
  return trackingDomains.some(domain => url.includes(domain));
}

// Inject a script to block tracking scripts
(function() {
  const observer = new MutationObserver(mutations => {
    mutations.forEach(mutation => {
      mutation.addedNodes.forEach(node => {
        if (node.tagName && node.tagName.toLowerCase() === 'script') {
          const script = node;
          const src = script.src;
          if (src && isTrackingScript(src)) {
            script.remove();
            console.log(`Blocked tracking script: ${src}`);
          }
        }
      });
    });
  });

  observer.observe(document.body, {
    childList: true,
    subtree: true
  });
})();
```

