### 📜 `content.js`
```javascript
// List of known tracking domains (example)
const trackingDomains = [
  "tracking.example.com",
  "ads.example.com",
  "analytics.example.com",
  "pixel.example.com"
];

// Function to check if a script is a tracking script
function isTrackingScript(script) {
  if (!script.src) return false;
  try {
    const domain = new URL(script.src).hostname;
    return trackingDomains.includes(domain);
  } catch (e) {
    return false;
  }
}

// Check existing scripts
document.querySelectorAll('script').forEach(script => {
  if (isTrackingScript(script)) {
    script.remove();
  }
});

// Observe new scripts added to the DOM
const observer = new MutationObserver((mutations) => {
  mutations.forEach(mutation => {
    mutation.addedNodes.forEach(node => {
      if (node.tagName && node.tagName.toLowerCase() === 'script') {
        const script = node;
        if (isTrackingScript(script)) {
          script.remove();
        }
      }
    });
  });
});

// Observe the entire document for new scripts
observer.observe(document.documentElement, { childList: true, subtree: true });
