    {
      "matches": ["<all_urls>"],
      "js": ["content.js"]
    }
  ],
  "icons": {
    "16": "icon16.png",
    "48": "icon48.png",
    "128": "icon128.png"
  }
}
```

---

### 📜 `background.js`
```javascript
// List of known tracking domains (expand this list in production)
const trackingDomains = [
  "tracking.example.com",
  "ads.example.org",
  "analytics.example.net",
  "pixel.example.io"
];

chrome.webRequest.onBeforeRequest.addListener(
  function(details) {
    const url = new URL(details.url);
    if (trackingDomains.some(domain => url.hostname.endsWith(domain))) {
      console.log(`Blocking tracking request to: ${url.href}`);
      return { cancel: true };
    }
  },
  { urls: ["<all_urls>"] },
  ["blocking"]
);
```

---

### 📜 `content.js`
```javascript
