  const trackingScriptElements = document.querySelectorAll(
    'script[src*="tracking"], script[src*="ads"], script[src*="analytics"]'
  );
  trackingScriptElements.forEach(script => {
    script.remove(); // Remove tracking scripts from the DOM
    console.log(`Removed tracking script: ${script.src}`);
  });
})();
```

