// Remove tracking scripts by removing elements with data-track or tracking classes
function blockTrackingElements() {
  const trackingSelectors = [
    '[data-track]', // Common tracking attribute
    '.tracking-script', // Example class for tracking scripts
    'script[src*="tracking"]', // Example script src pattern
  ];

  trackingSelectors.forEach(selector => {
    const elements = document.querySelectorAll(selector);
    elements.forEach(el => {
      if (el && el.parentNode) {
        el.parentNode.removeChild(el);
      }
    });
  });
}

// Run on page load
