```javascript
// List of known tracking domains (expand this list as needed)
const trackingDomains = [
  "analytics.google.com",
  "doubleclick.net",
  "adsrvr.org",
  "tracking.maxcdn.com",
  "taboola.com"
];

// Function to block tracking scripts
function blockTrackingScripts() {
  const scripts = document.querySelectorAll("script");
  scripts.forEach(script => {
    const src = script.src || "";
    if (trackingDomains.some(domain => src.includes(domain))) {
      script.remove();
      console.log(`Blocked tracking script: ${src}`);
    }
  });
}

// Run on page load
