    const INITIAL_TIME_INTERVALS = ['2023-01', '2023-02', '2023-03', '2023-04', '2023-05'];
    const INITIAL_PRICES = [
      [150, 160, 155, 200, 180],
      [165, 170, 168, 210, 185],
      [175, 180, 178, 220, 190],
      [185, 190, 188, 230, 195],
      [195, 200, 198, 240, 200]
    ];

    let timeIntervals = [...INITIAL_TIME_INTERVALS];
    let prices = [...INITIAL_PRICES];

