      const price = Math.random() * 100;
      const timestamp = Date.now();
      ws.send(JSON.stringify({ symbol: stockSymbol, price, timestamp }));
    }, 2000);

    function updateHeatmap() {
      // Filter latest 50 data points for performance
      const latestData = data.slice(-50);
      currentData = latestData;

      // Update scales
      xScale.domain([0, latestData.length]);
      yScale.domain([0, 100]); // Assuming price range is 0-100

      // Clear existing elements
      g.selectAll("*").remove();

      // Draw grid
      const grid = g.append("g")
        .attr("class", "grid")
        .attr("transform", `translate(${0}, ${0})`);

      grid.selectAll(".grid-line")
        .data(d3.range(0, 101, 10))
        .enter()
        .append("line")
        .attr("x1", 0)
        .attr("x2", width)
        .attr("y1", (d) => yScale(d))
        .attr("y2", (d) => yScale(d))
        .attr("stroke", "#ccc")
        .attr("stroke-width", 1);

      grid.selectAll(".grid-line-vertical")
        .data(d3.range(0, latestData.length, 1))
        .enter()
        .append("line")
        .attr("y1", 0)
        .attr("y2", height)
        .attr("x1", (d) => xScale(d))
        .attr("x2", (d) => xScale(d))
        .attr("stroke", "#ccc")
        .attr("stroke-width", 1);

      // Draw heatmap cells
      const heatmap = g.append("g")
        .attr("class", "heatmap");

      heatmap.selectAll("rect")
        .data(latestData)
        .enter()
        .append("rect")
        .attr("x", (d, i) => xScale(i))
        .attr("y", (d) => yScale(d.price))
        .attr("width", (d, i) => width / latestData.length)
        .attr("height", (d) => height / 100)
        .attr("fill", (d) => colorScale(d.price))
        .attr("stroke", "#fff")
        .attr("stroke-width", 0.5);
    }

    // Initial render
    updateHeatmap();
