Here's a minimal working example using **JavaScript** with **D3.js** for an interactive stock price heatmap with real-time updates and zoom/pan interactions:

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Stock Price Heatmap</title>
  <script src="https://d3js.org/d3.v7.min.js"></script>
  <style>
    body { margin: 0; overflow: hidden; }
    #heatmap {
      width: 100vw;
      height: 100vh;
    }
  </style>
</head>
<body>
  <svg id="heatmap"></svg>

  <script>
    const svg = d3.select("#heatmap")
      .attr("width", window.innerWidth)
      .attr("height", window.innerHeight);

    const width = +svg.attr("width");
    const height = +svg.attr("height");

    // Mock real-time data: 10 stocks × 100 time intervals
    let data = d3.range(100).map(() => 
      d3.range(10).map(() => Math.random() * 100)
    );

    const cellSize = 30;
    const cols = data[0].length;
    const rows = data.length;

    const xScale = d3.scaleLinear()
      .domain([0, cols - 1])
      .range([0, width]);

    const yScale = d3.scaleLinear()
      .domain([0, rows - 1])
      .range([height, 0]);

    const colorScale = d3.scaleLinear()
      .domain([0, 100])
      .range(["#00ff00", "#ff0000"]);

    const zoom = d3.zoom()
      .scaleExtent([0.1, 5])
      .on("zoom", (event) => {
        svg.select("g")
          .attr("transform", event.transform);
      });

    const g = svg.append("g")
      .call(zoom);

    function updateHeatmap() {
      const cells = g.selectAll("rect")
        .data(data.flat());

      cells.enter()
        .append("rect")
        .merge(cells)
        .attr("x", (d, i) => xScale(i % cols))
        .attr("y", (d, i) => yScale(Math.floor(i / cols)))
        .attr("width", cellSize)
        .attr("height", cellSize)
        .attr("fill", (d) => colorScale(d))
        .on("mouseover", (event, d) => {
          d3.select(event.currentTarget)
            .attr("fill", "#ffff00");
        })
        .on("mouseout", (event, d) => {
          d3.select(event.currentTarget)
            .attr("fill", colorScale(d));
        });

      cells.exit().remove();

      // Update data for real-time
      data = d3.range(100).map(() => 
        d3.range(10).map(() => Math.random() * 100)
      );
    }

    // Initial render
    updateHeatmap();

    // Real-time updates every 2 seconds
    setInterval(updateHeatmap, 2000);
  </script>
</body>
</html>
```

