### ✅ **Minimal Working Example**
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>Stock Price Heatmap</title>
  <script src="https://d3js.org/d3.v7.min.js"></script>
  <style>
    body { font-family: sans-serif; }
    #heatmap {
      width: 100vw;
      height: 80vh;
      display: block;
      margin: 20px auto;
    }
  </style>
</head>
<body>
  <h2>Stock Price Heatmap (Real-Time)</h2>
  <div id="heatmap"></div>

  <script>
    const width = 800;
    const height = 600;
    const margin = { top: 20, right: 20, bottom: 30, left: 40 };

    // Simulate stock data: [stock, price]
    let data = Array.from({ length: 100 }, (_, i) =>
      Array.from({ length: 100 }, (_, j) => ({
        x: j,
        y: i,
        value: Math.random() * 100 // Random price
      }))
    );

    const svg = d3.select("#heatmap")
      .append("svg")
      .attr("width", width)
      .attr("height", height)
      .call(d3.zoom().on("zoom", zoomed));

    const g = svg.append("g");

    const xScale = d3.scaleLinear()
      .domain([0, data[0].length - 1])
      .range([margin.left, width - margin.right]);

    const yScale = d3.scaleLinear()
      .domain([0, data.length - 1])
      .range([height - margin.bottom, margin.top]);

    const colorScale = d3.scaleLinear()
      .domain([0, 100])
      .range(["#000080", "#FF0000"]); // Blue to Red gradient

    const cells = g.selectAll("rect")
      .data(data.flat())
      .join("rect")
      .attr("x", d => xScale(d.x))
      .attr("y", d => yScale(d.y))
      .attr("width", xScale.range()[1] - xScale.range()[0] / data[0].length)
      .attr("height", yScale.range()[1] - yScale.range()[0] / data.length)
      .attr("fill", d => colorScale(d.value))
      .attr("opacity", 0.8);

    function zoomed(event) {
      const { transform } = event;
      g.attr("transform", transform);
    }

    // Simulate real-time updates
    setInterval(() => {
      data = data.map(row => 
        row.map(cell => ({
          ...cell,
          value: Math.random() * 100 // Random price update
        }))
      );

      cells.data(data.flat())
        .attr("fill", d => colorScale(d.value));
    }, 1000);
  </script>
</body>
</html>
```

