      g.selectAll("*").remove(); // Clear previous data

      const x = d3.scaleLinear()
        .domain([0, cols - 1])
        .range([0, chartWidth]);

      const y = d3.scaleLinear()
        .domain([0, rows - 1])
        .range([chartHeight, 0]);

      const cells = g.selectAll("rect")
        .data(data)
        .enter()
        .append("rect")
        .attr("x", d => x(d.col))
        .attr("y", d => y(d.row))
        .attr("width", chartWidth / cols)
        .attr("height", chartHeight / rows)
        .attr("fill", d => colorScale(d.value))
        .on("click", (event, d) => alert(`Stock ${d.row}-${d.col}: ${d.value.toFixed(2)}`));
    }

    // Zoom handler
    function zoomed(event) {
      g.attr("transform", event.transform);
    }

    // Real-time update simulation
    function updateData() {
      data = data.map(d => ({
        ...d,
        value: d.value + (Math.random() - 0.5) * 10 // Random fluctuation
      }));
      drawHeatmap();
    }

    // Initial draw
    drawHeatmap();

    // Simulate real-time updates every 2 seconds
    setInterval(updateData, 2000);
  </script>
</body>
</html>
```

