```js
// server.js
const express = require('express');
const http = require('http');
const socketIO = require('socket.io');
const mongoose = require('mongoose');
const { v4: uuidv4 } = require('uuid');

const app = express();
const server = http.createServer(app);
const io = socketIO(server);

// MongoDB model for tasks
const TaskSchema = new mongoose.Schema({
  _id: { type: String, default: uuidv4() },
  text: String,
  columnId: String,
});
const Task = mongoose.model('Task', TaskSchema);

// Connect to MongoDB
mongoose.connect('mongodb://localhost:27017/projectManagement', {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Load initial tasks
const loadTasks = async (boardId) => {
  const tasks = await Task.find({ boardId });
  return tasks;
};

// Handle socket connections
io.on('connection', (socket) => {
  console.log('Client connected');

  // Load initial data
  socket.emit('update', { columns: [] }); // Placeholder for initial data

  // Handle task addition
  socket.on('addTask', async (data) => {
    const { boardId, task } = data;
    const newTask = new Task({ ...task, boardId });
    await newTask.save();
    io.emit('update', { columns: await loadTasks(boardId) });
  });

  // Handle task movement
  socket.on('moveTask', async (data) => {
    const { boardId, taskId, newColumnId } = data;
    const task = await Task.findOne({ _id: taskId, boardId });
    if (task) {
      task.columnId = newColumnId;
      await task.save();
      io.emit('update', { columns: await loadTasks(boardId) });
    }
  });

  // Handle disconnection
  socket.on('disconnect', () => {
    console.log('Client disconnected');
  });
});

// Serve frontend
app.use(express.static('public'));

server.listen(3001, () => {
  console.log('Server running on http://localhost:3001');
});
```

