Here's a simplified implementation of a browser-based project management app with drag-and-drop and real-time collaboration using **JavaScript (frontend)** and **Node.js + WebSocket (backend)**. This example uses **HTML5 Drag and Drop API** and **WebSocket** for real-time updates.

---

### 🧩 **Frontend (HTML + JavaScript)**  
```html
<!DOCTYPE html>
<html>
<head>
  <title>Task Board</title>
  <style>
    body { font-family: Arial; }
    .board { width: 45%; float: left; margin: 10px; border: 1px solid #ccc; padding: 10px; }
    .task { padding: 10px; margin: 5px 0; border: 1px solid #ddd; cursor: grab; }
    .task.dragging { opacity: 0.5; }
  </style>
</head>
<body>
  <h2>Task Boards</h2>
  <div class="board" id="todo-board" ondragover="allowDrop(event)" ondrop="drop(event)">
    <h3>To Do</h3>
    <div id="todo-tasks"></div>
  </div>
  <div class="board" id="inprogress-board" ondragover="allowDrop(event)" ondrop="drop(event)">
    <h3>In Progress</h3>
    <div id="inprogress-tasks"></div>
  </div>
  <div class="board" id="done-board" ondragover="allowDrop(event)" ondrop="drop(event)">
    <h3>Done</h3>
    <div id="done-tasks"></div>
  </div>

  <script>
    const boards = {
      'todo': document.getElementById('todo-tasks'),
      'inprogress': document.getElementById('inprogress-tasks'),
      'done': document.getElementById('done-tasks')
    };

    const socket = new WebSocket('ws://localhost:8080');

    // Initialize tasks
    let tasks = [
      { id: 1, text: 'Task 1', board: 'todo' },
      { id: 2, text: 'Task 2', board: 'todo' },
      { id: 3, text: 'Task 3', board: 'inprogress' }
    ];

    function renderTasks() {
      boards.todo.innerHTML = '';
      boards.inprogress.innerHTML = '';
      boards.done.innerHTML = '';
      tasks.forEach(task => {
        const taskEl = document.createElement('div');
        taskEl.className = 'task';
        taskEl.draggable = true;
        taskEl.textContent = task.text;
        taskEl.dataset.board = task.board;
        taskEl.dataset.id = task.id;
        taskEl.addEventListener('dragstart', dragStart);
        boards[task.board].appendChild(taskEl);
      });
    }

    function allowDrop(event) {
      event.preventDefault();
    }

    function dragStart(event) {
      event.dataTransfer.setData('text/plain', event.target.dataset.id);
    }

    function drop(event) {
      event.preventDefault();
      const taskId = event.dataTransfer.getData('text/plain');
      const task = tasks.find(t => t.id === parseInt(taskId));
      const targetBoard = event.currentTarget.dataset.board;

      if (task.board !== targetBoard) {
        task.board = targetBoard;
        socket.send(JSON.stringify({ type: 'update', task }));
        renderTasks();
      }
    }

    // Listen for updates from other clients
    socket.onmessage = (event) => {
      const data = JSON.parse(event.data);
      if (data.type === 'update') {
        const task = data.task;
        const index = tasks.findIndex(t => t.id === task.id);
        if (index !== -1) {
          tasks[index] = task;
          renderTasks();
        }
      }
    };

    // Initial render
    renderTasks();
  </script>
</body>
</html>
```

