```javascript
const { useState, useEffect } = React;
const { DndProvider, useDrag, useDrop } = ReactDnd;

const Task = ({ id, text, columnId, onMove }) => {
  const [{ isDragging }, drag] = useDrag({
    type: 'task',
    item: { id, columnId },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  const [, drop] = useDrop({
    accept: 'task',
    drop: (item) => onMove(id, item.columnId),
  });

  return (
    <div ref={(node) => drag(drop(node))} style={{ opacity: isDragging ? 0.5 : 1 }}>
      {text}
    </div>
  );
};

const Column = ({ id, tasks, onMove }) => {
  return (
    <div className="column">
      <h3>Column {id}</h3>
      {tasks.map((task) => (
        <Task key={task.id} id={task.id} text={task.text} columnId={id} onMove={onMove} />
      ))}
    </div>
  );
};

const App = () => {
  const [tasks, setTasks] = useState([]);
  const [socket, setSocket] = useState(null);

  useEffect(() => {
    const socket = io('http://localhost:3000');
    setSocket(socket);

    socket.on('taskMoved', (data) => {
      setTasks((prevTasks) => {
        const updatedTasks = [...prevTasks];
        const task = updatedTasks.find((t) => t.id === data.taskId);
        if (task) {
          task.columnId = data.newColumnId;
        }
        return updatedTasks;
      });
    });

    return () => {
      socket.disconnect();
    };
  }, []);

  const handleAddTask = () => {
    const newTask = {
      id: Date.now(),
      text: `Task ${Date.now()}`,
      columnId: 1,
    };
    setTasks([...tasks, newTask]);
    socket.emit('addTask', newTask);
  };

  const handleMoveTask = (taskId, newColumnId) => {
    socket.emit('moveTask', { taskId, newColumnId });
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="board">
        <Column id={1} tasks={tasks.filter((t) => t.columnId === 1)} onMove={handleMoveTask} />
        <Column id={2} tasks={tasks.filter((t) => t.columnId === 2)} onMove={handleMoveTask} />
        <Column id={3} tasks={tasks.filter((t) => t.columnId === 3)} onMove={handleMoveTask} />
      </div>
      <button onClick={handleAddTask}>Add Task</button>
    </DndProvider>
  );
};

ReactDOM.createRoot(document.getElementById('root')).render(<App />);
