### 🧩 `App.js` (Main Application Logic)
```javascript
import React, { useEffect, useState } from "react";
import { db, ref, onValue, set, push, update } from "./firebase";
import { ItemTypes } from "./constants";
import TaskBoard from "./TaskBoard";
import Sidebar from "./Sidebar";

const App = () => {
  const [columns, setColumns] = useState([]);
  const [tasks, setTasks] = useState([]);

  // Fetch initial data from Firebase
  useEffect(() => {
    const columnsRef = ref(db, "columns");
    const tasksRef = ref(db, "tasks");

    onValue(columnsRef, (snapshot) => {
      const data = snapshot.val();
      setColumns(data ? Object.values(data) : []);
    });

    onValue(tasksRef, (snapshot) => {
      const data = snapshot.val();
      setTasks(data ? Object.values(data) : []);
    });

    return () => {
      // Cleanup if needed
    };
  }, []);

  // Update task position in Firebase
  const updateTaskPosition = (taskId, newColumnId) => {
    const task = tasks.find((task) => task.id === taskId);
    if (!task) return;

    // Update task in Firebase
    update(ref(db, `tasks/${taskId}`), { columnId: newColumnId });

    // Update local state
    setTasks(
      tasks.map((t) =>
        t.id === taskId ? { ...t, columnId: newColumnId } : t
      )
    );
  };

  return (
    <div style={{ display: "flex", padding: "20px" }}>
      <TaskBoard columns={columns} tasks={tasks} />
      <Sidebar />
    </div>
  );
};

export default App;
```

