### **1. Front-End (React + React DnD + Firebase)**
```jsx
<language>React</language>
import React, { useEffect, useState } from 'react';
import { DndProvider, useDrag, useDrop } from 'react-dnd';
import { HTML5Backend } from 'react-dnd-html5-backend';
import { db, auth } from './firebase'; // Firebase setup
import './App.css';

const Task = ({ task, index, columnId, onMoveTask }) => {
  const [{ isDragging }, drag] = useDrag({
    type: 'task',
    item: { task, columnId },
    collect: (monitor) => ({
      isDragging: monitor.isDragging(),
    }),
  });

  const [, drop] = useDrop({
    accept: 'task',
    hover: (item, monitor) => {
      if (!columnId || !item.columnId) return;
      const dragIndex = item.index;
      const hoverIndex = index;
      if (dragIndex === hoverIndex) return;
      const newTasks = [...task.tasks];
      newTasks.splice(hoverIndex, 0, newTasks.splice(dragIndex, 1)[0]);
      onMoveTask(newTasks, columnId);
    },
  });

  return (
    <div ref={(node) => drag(drop(node))} style={{ opacity: isDragging ? 0.5 : 1 }}>
      <div className="task">{task.text}</div>
    </div>
  );
};

const Column = ({ column, tasks, onMoveTask }) => {
  return (
    <div className="column">
      <h3>{column.title}</h3>
      <div className="tasks">
        {tasks.map((task, index) => (
          <Task
            key={task.id}
            task={task}
            index={index}
            columnId={column.id}
            onMoveTask={onMoveTask}
          />
        ))}
      </div>
    </div>
  );
};

const App = () => {
  const [columns, setColumns] = useState([]);
  const [tasks, setTasks] = useState([]);

  useEffect(() => {
    // Fetch initial data from Firebase
    const unsubscribe = db.collection('columns').onSnapshot((snapshot) => {
      const columns = [];
      const tasks = {};
      snapshot.forEach((doc) => {
        const column = doc.data();
        column.id = doc.id;
        columns.push(column);
        column.tasks.forEach((task) => {
          tasks[task.id] = task;
        });
      });
      setColumns(columns);
      setTasks(tasks);
    });

    return () => unsubscribe();
  }, []);

  const handleMoveTask = (newTasks, columnId) => {
    const updatedColumns = columns.map((col) => {
      if (col.id === columnId) {
        return { ...col, tasks: newTasks };
      }
      return col;
    });

    // Update Firebase
    db.collection('columns')
      .doc(columnId)
      .update({ tasks: newTasks });
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="app">
        <h1>Project Management</h1>
        <div className="board">
          {columns.map((column) => (
            <Column
              key={column.id}
              column={column}
              tasks={tasks[column.id] || []}
              onMoveTask={handleMoveTask}
            />
          ))}
        </div>
      </div>
    </DndProvider>
  );
};

export default App;
```

