const { useState, useEffect } = React;

const App = () => {
  const [tasks, setTasks] = useState([]);
  const [newTask, setNewTask] = useState("");

  useEffect(() => {
    // Fetch initial tasks from backend
    fetch("/api/tasks")
      .then((res) => res.json())
      .then(setTasks);

    // Listen for real-time updates
    const socket = new WebSocket("ws://localhost:3001");

    socket.onmessage = (event) => {
      const updatedTasks = JSON.parse(event.data);
      setTasks(updatedTasks);
    };

    return () => socket.close();
  }, []);

  const addTask = (column) => {
    if (!newTask.trim()) return;
    const task = {
      id: Date.now(),
      text: newTask,
      column,
    };
    fetch("/api/tasks", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(task),
    });
    setNewTask("");
  };

  const moveTask = (taskId, newColumn) => {
    fetch(`/api/tasks/${taskId}`, {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ column: newColumn }),
    });
  };

  return (
    <div>
      <input
        type="text"
        value={newTask}
        onChange={(e) => setNewTask(e.target.value)}
        placeholder="Add new task"
      />
      <button onClick={() => addTask("todo")}>Add to To Do</button>

      <div id="task-boards">
        <div className="column" id="todo">
          <h2>To Do</h2>
          <div className="tasks">
            {tasks
              .filter((t) => t.column === "todo")
              .map((task) => (
                <div
                  key={task.id}
                  className="task"
                  draggable
                  onDragStart={(e) => e.dataTransfer.setData("taskId", task.id)}
                  onDragEnd={() => moveTask(task.id, "in-progress")}
                >
                  {task.text}
                </div>
              ))}
          </div>
        </div>
        {/* Similar for in-progress and done columns */}
      </div>
    </div>
  );
};

ReactDOM.createRoot(document.getElementById("app")).render(<App />);
