```javascript
const socket = io();

// Load initial tasks
socket.on('updateTasks', (tasks) => {
  renderTasks(tasks);
});

// Render tasks into the DOM
function renderTasks(tasks) {
  const column1 = document.getElementById('column1-tasks');
  const column2 = document.getElementById('column2-tasks');
  const column3 = document.getElementById('column3-tasks');

  column1.innerHTML = '';
  column2.innerHTML = '';
  column3.innerHTML = '';

  tasks.forEach(task => {
    const taskDiv = document.createElement('div');
    taskDiv.className = 'task';
    taskDiv.draggable = true;
    taskDiv.textContent = task.text;
    taskDiv.dataset.column = task.column;

    taskDiv.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', task.id);
    });

    taskDiv.addEventListener('dragover', (e) => {
      e.preventDefault();
    });

    taskDiv.addEventListener('drop', (e) => {
      e.preventDefault();
      const taskId = e.dataTransfer.getData('text/plain');
      const newColumn = e.target.closest('.column').id.replace('column', '');
      const updatedTasks = tasks.map(t => {
        if (t.id === taskId) {
          return { ...t, column: newColumn };
        }
        return t;
      });

      socket.emit('moveTask', updatedTasks);
    });

    if (task.column === '1') column1.appendChild(taskDiv);
    else if (task.column === '2') column2.appendChild(taskDiv);
    else column3.appendChild(taskDiv);
  });
}
