// App.tsx
import React, { useState, useEffect } from 'react';
import { io } from 'socket.io-client';

const App: React.FC = () => {
  const [tasks, setTasks] = useState<Array<{ id: string; text: string; column: string }>>([]);
  const [newTaskText, setNewTaskText] = useState('');
  const [socket, setSocket] = useState<any>(null);

  // Connect to backend
  useEffect(() => {
    const socket = io('http://localhost:3001');
    setSocket(socket);

    // Listen for real-time updates
    socket.on('taskUpdated', (updatedTask) => {
      setTasks((prevTasks) =>
        prevTasks.map((task) =>
          task.id === updatedTask.id ? { ...task, ...updatedTask } : task
        )
      );
    });

    return () => socket.disconnect();
  }, []);

  // Handle task creation
  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTaskText.trim()) return;

    const newTask = {
      id: Date.now().toString(),
      text: newTaskText,
      column: 'To Do',
    };

    setTasks([...tasks, newTask]);
    setNewTaskText('');
    socket?.emit('createTask', newTask);
  };

  // Handle drag-and-drop (simplified)
  const handleDragStart = (e: React.DragEvent, task: any) => {
    e.dataTransfer.setData('text/plain', task.id);
  };

  const handleDrop = (e: React.DragEvent, column: string) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    const updatedTask = { ...tasks.find((t) => t.id === taskId), column };
    setTasks(tasks.map((t) => (t.id === taskId ? updatedTask : t)));
    socket?.emit('updateTask', updatedTask);
  };

  return (
    <div style={{ display: 'flex', gap: '20px', padding: '20px' }}>
      <div style={{ width: '300px', border: '1px solid #ccc', padding: '10px' }}>
        <h3>Create Task</h3>
        <form onSubmit={handleCreateTask}>
          <input
            type="text"
            value={newTaskText}
            onChange={(e) => setNewTaskText(e.target.value)}
            placeholder="Enter task"
          />
          <button type="submit">Add</button>
        </form>
      </div>
      <div style={{ display: 'flex', gap: '20px' }}>
        <div
          onDrop={(e) => handleDrop(e, 'To Do')}
          onDragOver={(e) => e.preventDefault()}
          style={{ border: '1px solid #ccc', padding: '10px', width: '300px' }}
        >
          <h3>To Do</h3>
          {tasks
            .filter((task) => task.column === 'To Do')
            .map((task) => (
              <div
                key={task.id}
                draggable
                onDragStart={(e) => handleDragStart(e, task)}
                style={{ marginBottom: '10px', padding: '5px', border: '1px solid #ddd' }}
              >
                {task.text}
              </div>
            ))}
        </div>
        <div
          onDrop={(e) => handleDrop(e, 'In Progress')}
          onDragOver={(e) => e.preventDefault()}
          style={{ border: '1px solid #ccc', padding: '10px', width: '300px' }}
        >
          <h3>In Progress</h3>
          {tasks
            .filter((task) => task.column === 'In Progress')
            .map((task) => (
              <div
                key={task.id}
                draggable
                onDragStart={(e) => handleDragStart(e, task)}
                style={{ marginBottom: '10px', padding: '5px', border: '1px solid #ddd' }}
              >
                {task.text}
              </div>
            ))}
        </div>
        <div
          onDrop={(e) => handleDrop(e, 'Done')}
          onDragOver={(e) => e.preventDefault()}
          style={{ border: '1px solid #ccc', padding: '10px', width: '300px' }}
        >
          <h3>Done</h3>
          {tasks
            .filter((task) => task.column === 'Done')
            .map((task) => (
              <div
                key={task.id}
                draggable
                onDragStart={(e) => handleDragStart(e, task)}
                style={{ marginBottom: '10px', padding: '5px', border: '1px solid #ddd' }}
              >
                {task.text}
              </div>
            ))}
        </div>
      </div>
    </div>
  );
};

export default App;
