const socket = io();

// Map column IDs to task containers
const columnMap = {
  'todo': '#todo-tasks',
  'inprogress': '#inprogress-tasks',
  'done': '#done-tasks'
};

// Render tasks from the server
socket.on('tasks', (tasks) => {
  renderTasks(tasks);
});

// Render tasks in the UI
function renderTasks(tasks) {
  Object.values(columnMap).forEach(container => {
    $(container).empty();
  });

  tasks.forEach(task => {
    const taskElement = document.createElement('div');
    taskElement.className = 'task';
    taskElement.draggable = true;
    taskElement.textContent = task.text;
    taskElement.dataset.column = task.column;
    taskElement.dataset.id = task.id;

    // Handle drag start
    taskElement.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', task.id);
      taskElement.classList.add('dragging');
    });

    // Handle drag end
    taskElement.addEventListener('dragend', () => {
      taskElement.classList.remove('dragging');
    });

    // Append to the correct column
    $(columnMap[task.column]).append(taskElement);
  });
}

// Handle drag over (allow drop)
document.querySelectorAll('.column').forEach(column => {
  column.addEventListener('dragover', (e) => {
    e.preventDefault();
  });

  // Handle drop
  column.addEventListener('drop', (e) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('text/plain');
    const task = tasks.find(t => t.id === parseInt(taskId));
    if (task) {
      task.column = column.id;
      socket.emit('updateTask', task);
    }
  });
});
