const socket = new WebSocket(`ws://${window.location.host}`);

// Initialize tasks
const tasks = [
  { id: 1, text: "Task 1", column: "todo" },
  { id: 2, text: "Task 2", column: "inprogress" },
  { id: 3, text: "Task 3", column: "done" },
];

// Populate initial UI
function renderTasks() {
  const columns = { todo: "todo-tasks", inprogress: "inprogress-tasks", done: "done-tasks" };
  const tasksByColumn = tasks.reduce((acc, task) => {
    acc[task.column].push(task);
    return acc;
  }, { todo: [], inprogress: [], done: [] });

  for (const [column, taskIds] of Object.entries(tasksByColumn)) {
    const container = document.getElementById(columns[column]);
    container.innerHTML = taskIds
      .map(task => `<div class="task" data-id="${task.id}" data-column="${column}">${task.text}</div>`)
      .join("");
  }
}

// Drag-and-drop logic
document.addEventListener("dragstart", (e) => {
  e.dataTransfer.setData("text/plain", e.target.dataset.id);
  e.dataTransfer.effectAllowed = "move";
});

document.addEventListener("dragover", (e) => {
  e.preventDefault();
  e.dataTransfer.dropEffect = "move";
});

document.addEventListener("drop", (e) => {
  e.preventDefault();
  const taskId = e.dataTransfer.getData("text/plain");
  const targetColumn = e.target.closest(".column").id;

  const task = tasks.find(t => t.id == taskId);
  task.column = targetColumn;

  // Broadcast update to server
  socket.send(JSON.stringify({ type: "taskMove", taskId, newColumn: targetColumn }));
});

// Listen for real-time updates
socket.onmessage = (event) => {
  const update = JSON.parse(event.data);
  if (update.type === "taskMove") {
    const taskId = update.taskId;
    const newColumn = update.newColumn;
    const task = tasks.find(t => t.id == taskId);
    task.column = newColumn;
    renderTasks();
  }
};

// Initialize
renderTasks();
