```jsx
import React, { useState, useEffect } from 'react';
import { v4 as uuidv4 } from 'uuid';

const App = () => {
  const [columns, setColumns] = useState([
    { id: 'todo', title: 'To Do' },
    { id: 'inprogress', title: 'In Progress' },
    { id: 'done', title: 'Done' },
  ]);
  const [tasks, setTasks] = useState([
    { id: uuidv4(), columnId: 'todo', text: 'Task 1' },
    { id: uuidv4(), columnId: 'todo', text: 'Task 2' },
  ]);

  // Connect to real-time server
  useEffect(() => {
    const socket = new WebSocket('ws://localhost:5000');

    socket.onmessage = (event) => {
      const updatedTask = JSON.parse(event.data);
      setTasks((prevTasks) =>
        prevTasks.map((task) =>
          task.id === updatedTask.id ? updatedTask : task
        )
      );
    };

    return () => socket.close();
  }, []);

  // Drag-and-drop logic
  const handleDragStart = (e, taskId) => {
    e.dataTransfer.setData('taskId', taskId);
  };

  const handleDragOver = (e) => {
    e.preventDefault(); // Allow drop
  };

  const handleDrop = (e, columnId) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    setTasks((prevTasks) =>
      prevTasks.map((task) =>
        task.id === taskId
          ? { ...task, columnId }
          : task
      )
    );

    // Broadcast update to server
    const updatedTask = tasks.find((task) => task.id === taskId);
    if (updatedTask) {
      socket.emit('taskMoved', updatedTask);
    }
  };

  return (
    <div style={{ padding: '20px' }}>
      <h1>Task Board</h1>
      <div style={{ display: 'flex', gap: '20px' }}>
        {columns.map((column) => (
          <div
            key={column.id}
            style={{
              border: '1px solid #ccc',
              padding: '10px',
              width: '300px',
            }}
          >
            <h3>{column.title}</h3>
            <div
              style={{ minHeight: '100px', border: '1px dashed #ccc' }}
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, column.id)}
            >
              {tasks
                .filter((task) => task.columnId === column.id)
                .map((task) => (
                  <div
                    key={task.id}
                    draggable
                    onDragStart={(e) => handleDragStart(e, task.id)}
                    style={{ margin: '10px 0', padding: '8px', border: '1px solid #ddd' }}
                  >
                    {task.text}
                  </div>
                ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;
```

