### **2. Rust Example: Concurrent Message Processing with Tokio**
```rust
use tokio::sync::mpsc;
use tokio::task;
use std::sync::Arc;
use std::thread;

#[derive(Debug)]
struct TradeMessage {
    symbol: String,
    price: f64,
}

#[tokio::main]
async fn main() {
    // Create a channel for message passing
    let (tx, mut rx) = mpsc::channel(100);

    // Spawn a background task to process messages
    let tx_clone = tx.clone();
    task::spawn(async move {
        while let Some(msg) = rx.recv().await {
            process_message(msg);
        }
    });

    // Simulate sending messages
    let tx_clone = tx.clone();
    thread::spawn(move || {
        for i in 0..10 {
            let msg = TradeMessage {
                symbol: format!("AAPL{}", i),
                price: 150.0 + i as f64,
            };
            tx_clone.send(msg).unwrap();
        }
    });

    // Stop after processing
    drop(tx);
}

fn process_message(msg: TradeMessage) {
    // Simulate low-latency processing (e.g., order matching, market data)
    println!("Processed: {:?}", msg);
}
