// Low-latency message queue (ring buffer for minimal overhead)
template <typename T, size_t N>
class RingBuffer {
public:
    RingBuffer() : head(0), tail(0), full(false) {}

    bool try_push(T item) {
        std::lock_guard<std::mutex> lock(mutex);
        if ((tail + 1) % N == head) return false; // Full
        buffer[tail] = item;
        tail = (tail + 1) % N;
        full = (tail == head);
        cond.notify_one();
        return true;
    }

    bool try_pop(T& item) {
        std::lock_guard<std::mutex> lock(mutex);
        if (head == tail && !full) return false; // Empty
        item = buffer[head];
        head = (head + 1) % N;
        full = false;
        cond.notify_one();
        return true;
    }

private:
    std::vector<T> buffer;
    size_t head, tail;
    bool full;
    std::mutex mutex;
    std::condition_variable cond;
};

// Thread pool for scalable processing
class ThreadPool {
public:
    ThreadPool(size_t threads) : stop(false) {
        for (size_t i = 0; i < threads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::function<void()> task;
                    {
                        std::unique_lock<std::mutex> lock(queue_mutex);
                        cond.wait(lock, [this] { return stop || !tasks.empty(); });
                        if (stop && tasks.empty()) return;
                        task = std::move(tasks.front());
                        tasks.pop();
                    }
                    task();
                }
            });
        }
    }

    ~ThreadPool() {
        stop = true;
        cond.notify_all();
        for (std::thread& worker : workers) worker.join();
    }

    template <class F>
    void enqueue(F&& f) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            tasks.emplace(std::forward<F>(f));
        }
        cond.notify_one();
    }

private:
    std::vector<std::thread> workers;
    std::queue<std::function<void()>> tasks;
    std::mutex queue_mutex;
    std::condition_variable cond;
    bool stop;
};

