        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& [price, buyOrdersList] : buyOrders) {
            if (sellOrders.find(price) != sellOrders.end()) {
                for (auto& buyOrder : buyOrdersList) {
                    auto& sellOrdersAtPrice = sellOrders[price];
                    if (buyOrder.quantity > 0 && sellOrdersAtPrice.size() > 0) {
