// 1. Order Book (Lock-Free Design)
class OrderBook {
public:
    using Price = int64_t;
    using Quantity = uint64_t;

    void addOrder(Price price, Quantity quantity, bool isBuy) {
        std::lock_guard<std::mutex> lock(mutex_);
        if (isBuy) {
            bids_[price] += quantity;
        } else {
            asks_[price] += quantity;
        }
    }

    void matchOrders() {
        // Simplified matching logic
        auto it = bids_.rbegin();
        while (it != bids_.rend() && !asks_.empty()) {
            Price bidPrice = it->first;
            Quantity bidQty = it->second;
            auto askIt = asks_.begin();
            if (askIt->first <= bidPrice) {
                Quantity askQty = askIt->second;
                Quantity matched = std::min(bidQty, askQty);
                std::cout << "Matched " << matched << " at " << askIt->first << std::endl;
                it->second -= matched;
                askIt->second -= matched;
                if (it->second == 0) {
                    it = bids_.erase(it);
                }
                if (askIt->second == 0) {
                    asks_.erase(askIt);
                }
            } else {
                break;
            }
        }
    }

private:
    std::mutex mutex_;
    std::unordered_map<Price, Quantity> bids_;
    std::unordered_map<Price, Quantity> asks_;
};

// 2. Message Handler (Asynchronous I/O)
class MessageHandler {
public:
    void processMessage(const std::string& message) {
        // Simulate low-latency parsing
        std::cout << "Received: " << message << std::endl;
        // Parse and route to order book
        if (message.find("BUY") != std::string::npos) {
            parseOrder(message, true);
        } else if (message.find("SELL") != std::string::npos) {
            parseOrder(message, false);
        }
    }

private:
