        // Extract price and quantity (simplified)
        size_t pos = msg.find(" ");
        std::string priceStr = msg.substr(0, pos);
        std::string qtyStr = msg.substr(pos + 1);
        OrderBook::Price price = std::stoll(priceStr);
        OrderBook::Quantity qty = std::stoull(qtyStr);
        orderBook_.addOrder(price, qty, isBuy);
        orderBook_.matchOrders();
    }

    OrderBook orderBook_;
};

// 3. Thread Pool for Scalability
class ThreadPool {
public:
    ThreadPool(size_t numThreads) : stop_(false) {
        for (size_t i = 0; i < numThreads; ++i) {
            workers_.emplace_back([this] { workerThread(); });
        }
    }

    ~ThreadPool() {
        stop_ = true;
        for (auto& w : workers_) {
            w.join();
        }
    }

    void enqueue(std::function<void()>&& task) {
        std::lock_guard<std::mutex> lock(queueMutex_);
        tasks_.push_back(std::move(task));
        queueCond_.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            std::function<void()> task;
            {
                std::unique_lock<std::mutex> lock(queueMutex_);
                queueCond_.wait(lock, [this] { return stop_ || !tasks_.empty(); });
                if (stop_ && tasks_.empty()) break;
                task = std::move(tasks_.back());
                tasks_.pop_back();
            }
            task();
        }
    }

    std::vector<std::thread> workers_;
    std::queue<std::function<void()>> tasks_;
    std::mutex queueMutex_;
    std::condition_variable queueCond_;
    bool stop_;
};

