    public:
        using Price = uint64_t;
        using Quantity = uint64_t;

        void addOrder(Price price, Quantity quantity, bool isBuy) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (isBuy) {
                bids_[price] += quantity;
            } else {
                asks_[price] += quantity;
            }
        }

        void removeOrder(Price price, Quantity quantity, bool isBuy) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (isBuy && bids_.count(price)) {
                bids_[price] -= quantity;
                if (bids_[price] == 0) bids_.erase(price);
            } else if (!isBuy && asks_.count(price)) {
                asks_[price] -= quantity;
                if (asks_[price] == 0) asks_.erase(price);
            }
        }

        std::vector<Price> getBidPrices() const {
            std::lock_guard<std::mutex> lock(mutex_);
            return std::vector<Price>(bids_.begin(), bids_.end());
        }

        std::vector<Price> getAskPrices() const {
            std::lock_guard<std::mutex> lock(mutex_);
            return std::vector<Price>(asks_.begin(), asks_.end());
        }

    private:
        std::unordered_map<Price, Quantity> bids_;
        std::unordered_map<Price, Quantity> asks_;
        mutable std::mutex mutex_;
    };

    // Market Data Feed: Simulates real-time data
    class MarketDataFeed {
    public:
        void start() {
            thread_ = std::thread(&MarketDataFeed::run, this);
        }

        void stop() {
            running_ = false;
            if (thread_.joinable()) thread_.join();
        }

    private:
        void run() {
            while (running_) {
                // Simulate receiving market data (e.g., from exchange)
                Price price = 10000 + rand() % 100;
                Quantity volume = 1000 + rand() % 500;
                std::cout << "Received: " << price << " @ " << volume << std::endl;

                // Update order book
                orderBook_.addOrder(price, volume, true); // Simulate buy order
                std::this_thread::sleep_for(std::chrono::milliseconds(1));
            }
        }

        std::thread thread_;
        std::atomic<bool> running_{true};
        OrderBook orderBook_;
    };

    // Execution Engine: Matches orders and executes trades
    class ExecutionEngine {
    public:
        void processOrder(Price price, Quantity quantity, bool isBuy) {
            std::lock_guard<std::mutex> lock(mutex_);
            if (isBuy) {
                // Match with best ask
                auto it = orderBook_.getAskPrices().begin();
                if (it != orderBook_.getAskPrices().end()) {
                    Price bestAsk = *it;
                    if (orderBook_.asks_[bestAsk] >= quantity) {
                        // Full match
                        orderBook_.removeOrder(bestAsk, quantity, false);
                        std::cout << "Executed: " << quantity << " @ " << bestAsk << std::endl;
                    } else {
                        // Partial match
                        orderBook_.removeOrder(bestAsk, orderBook_.asks_[bestAsk], false);
                        orderBook_.addOrder(bestAsk, quantity - orderBook_.asks_[bestAsk], isBuy);
                    }
                }
            } else {
                // Match with best bid
                auto it = orderBook_.getBidPrices().begin();
                if (it != orderBook_.getBidPrices().end()) {
                    Price bestBid = *it;
                    if (orderBook_.bids_[bestBid] >= quantity) {
                        // Full match
                        orderBook_.removeOrder(bestBid, quantity, true);
                        std::cout << "Executed: " << quantity << " @ " << bestBid << std::endl;
                    } else {
                        // Partial match
                        orderBook_.removeOrder(bestBid, orderBook_.bids_[bestBid], true);
                        orderBook_.addOrder(bestBid, quantity - orderBook_.bids_[bestBid], isBuy);
                    }
                }
            }
        }

    private:
        std::mutex mutex_;
        OrderBook orderBook_;
    };

    // Latency Monitoring: Tracks critical operations
    class LatencyMonitor {
    public:
        void recordLatency(size_t latencyMs) {
            std::lock_guard<std::mutex> lock(mutex_);
            latencySamples_.push_back(latencyMs);
            if (latencySamples_.size() > MAX_LATENCY_SAMPLES) {
                latencySamples_.erase(latencySamples_.begin());
            }
        }

        void printStats() {
            std::lock_guard<std::mutex> lock(mutex_);
            if (latencySamples_.empty()) return;
            auto min = *std::min_element(latencySamples_.begin(), latencySamples_.end());
            auto max = *std::max_element(latencySamples_.begin(), latencySamples_.end());
            auto avg = std::accumulate(latencySamples_.begin(), latencySamples_.end(), 0) / latencySamples_.size();
            std::cout << "Latency Stats: Min=" << min << "ms, Max=" << max << "ms, Avg=" << avg << "ms" << std::endl;
        }

    private:
        std::vector<size_t> latencySamples_;
        mutable std::mutex mutex_;
    };

    // Main Trading Platform
    class TradingPlatform {
    public:
        TradingPlatform() : marketDataFeed_(true), executionEngine_(), latencyMonitor_() {
            marketDataFeed_.start();
        }

        ~TradingPlatform() {
            marketDataFeed_.stop();
        }

        void simulateTrade() {
            // Simulate a trade (e.g., from user input or external system)
            Price price = 10000 + rand() % 100;
            Quantity quantity = 100 + rand() % 50;
            bool isBuy = rand() % 2 == 0;

            auto start = std::chrono::high_resolution_clock::now();
            executionEngine_.processOrder(price, quantity, isBuy);
            auto end = std::chrono::high_resolution_clock::now();
            auto latency = std::chrono::duration_cast<std::chrono::milliseconds>(end - start).count();
            latencyMonitor_.recordLatency(latency);
        }

        void run() {
            while (true) {
                simulateTrade();
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
        }
    };
}

