	ob.mu.Lock()
	defer ob.mu.Unlock()

	if order.Type == "buy" {
		ob.Bids[order.Price] = append(ob.Bids[order.Price], order)
	} else {
		ob.Asks[order.Price] = append(ob.Asks[order.Price], order)
	}
	ob.LastUpdate = time.Now()
}

// MatchOrders matches incoming market data with existing orders
func (ob *OrderBook) MatchOrders(price float64, quantity int) {
	ob.mu.Lock()
	defer ob.mu.Unlock()

	// Check bids for matching asks
	if bids, exists := ob.Bids[price]; exists {
		for i := 0; i < len(bids); i++ {
			if bids[i].Remaining <= 0 {
				continue
			}
			if bids[i].Remaining >= quantity {
				bids[i].Remaining -= quantity
				quantity = 0
				break
			} else {
				quantity -= bids[i].Remaining
				bids[i].Remaining = 0
			}
		}
		if quantity > 0 {
			// No more bids matched, remove the price level if empty
			delete(ob.Bids, price)
		}
	}

	// Check asks for matching bids
	if asks, exists := ob.Asks[price]; exists {
		for i := 0; i < len(asks); i++ {
			if asks[i].Remaining <= 0 {
				continue
			}
			if asks[i].Remaining >= quantity {
				asks[i].Remaining -= quantity
				quantity = 0
				break
			} else {
				quantity -= asks[i].Remaining
				asks[i].Remaining = 0
			}
		}
		if quantity > 0 {
			delete(ob.Asks, price)
		}
	}
	ob.LastUpdate = time.Now()
}

