    std::mutex mtx;
    std::deque<Order> bids;  // Buy orders (sorted by price descending)
    std::deque<Order> asks;  // Sell orders (sorted by price ascending)

    void addOrder(const Order& order) {
        std::lock_guard<std::mutex> lock(mtx);
        if (order.isBuy) {
            bids.push_back(order);
        } else {
            asks.push_back(order);
        }
    }

    void matchOrders() {
        std::lock_guard<std::mutex> lock(mtx);
        if (!bids.empty() && !asks.empty()) {
            auto& bestBid = bids.back();
            auto& bestAsk = asks.front();

            if (bestBid.price >= bestAsk.price) {
                int tradeQuantity = std::min(bestBid.quantity, bestAsk.quantity);
                std::cout << "Trade executed: " << tradeQuantity << " at " << bestAsk.price << std::endl;
                bestBid.quantity -= tradeQuantity;
                bestAsk.quantity -= tradeQuantity;

                if (bestBid.quantity == 0) bids.pop_back();
                if (bestAsk.quantity == 0) asks.pop_front();
            }
        }
    }
