Here's a Go implementation of a real-time market data processor that computes price aggregates and streams results to subscribers. The code includes a mock data source, real-time aggregation, and a simple subscriber mechanism.

```go
package main

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// MarketData represents incoming market data
type MarketData struct {
	Symbol string
	Price  float64
}

// Aggregate tracks statistics for each symbol
type Aggregate struct {
	Count int
	Sum   float64
	Max   float64
	Min   float64
}

// AggregateResult contains the computed metrics
type AggregateResult struct {
	Symbol string
	Avg    float64
	Max    float64
	Min    float64
}

// Subscriber handles incoming results
type Subscriber struct {
	Results chan AggregateResult
}

func main() {
	// Initialize channels
	dataChan := make(chan MarketData)
	resultsChan := make(chan AggregateResult)
	subscribers := make([]Subscriber, 0)
	var wg sync.WaitGroup

	// Start mock data generator
	wg.Add(1)
	go func() {
		defer wg.Done()
		symbols := []string{"AAPL", "GOOG", "MSFT", "AMZN"}
		for {
			for _, symbol := range symbols {
				// Simulate real-time data with random prices
				price := 100.0 + (float64(rand.Intn(1000)) / 1000)
				dataChan <- MarketData{Symbol: symbol, Price: price}
			}
			time.Sleep(100 * time.Millisecond) // Simulate data rate
		}
	}()

	// Start processing goroutine
	wg.Add(1)
	go func() {
		defer wg.Done()
		currentAggregates := make(map[string]Aggregate)
		for data := range dataChan {
			symbol := data.Symbol
			price := data.Price

			// Update aggregate for this symbol
			if agg, exists := currentAggregates[symbol]; exists {
				agg.Count++
				agg.Sum += price
				if price > agg.Max {
					agg.Max = price
				}
				if price < agg.Min {
					agg.Min = price
				}
				currentAggregates[symbol] = agg
			} else {
				currentAggregates[symbol] = Aggregate{
					Count: 1,
					Sum:   price,
					Max:   price,
					Min:   price,
				}
			}

			// Calculate average and send result
			avg := currentAggregates[symbol].Sum / float64(currentAggregates[symbol].Count)
			resultsChan <- AggregateResult{
				Symbol: symbol,
				Avg:    avg,
				Max:    currentAggregates[symbol].Max,
				Min:    currentAggregates[symbol].Min,
			}
		}
	}()

	// Create and register subscribers
	wg.Add(1)
	subscriber1 := Subscriber{Results: make(chan AggregateResult)}
	subscriber2 := Subscriber{Results: make(chan AggregateResult)}
	subscribers = append(subscribers, subscriber1, subscriber2)

	// Start subscriber goroutines
	for _, sub := range subscribers {
		go func(sub Subscriber) {
			defer wg.Done()
			for result := range sub.Results {
				fmt.Printf("Subscriber: Symbol: %s, Avg: %.2f, Max: %.2f, Min: %.2f\n",
					result.Symbol, result.Avg, result.Max, result.Min)
			}
		}(sub)
	}

	// Wait for all goroutines to complete
	wg.Wait()
}
```

### Key Features
1. **Concurrency Model**: Uses Go's lightweight goroutines for concurrent processing
2. **Real-Time Aggregation**: Calculates rolling average, max, and min prices
3. **Subscriber Model**: Supports multiple subscribers to receive results
4. **Mock Data Source**: Simulates real-time market data with random prices
5. **Efficient Memory Management**: Uses maps for O(1) lookup of symbol aggregates

### Architecture Overview
```
[Mock Data Source] → [Data Channel] → [Processing Goroutine] → [Results Channel]
                                      ↘
                                      [Subscriber Goroutines]
```

### Execution Flow
1. Mock data generator sends MarketData to `dataChan`
2. Processing goroutine updates aggregates and sends results to `resultsChan`
3. Each subscriber receives results via their own channel and processes them
4. The main function waits for all goroutines to complete

