// Define data structures
type Tick struct {
	Symbol string
	Price  float64
	Volume int
}

type SymbolData struct {
	Sum     float64
	Count   int
	Max     float64
	Min     float64
}

type Aggregate struct {
	Symbol string
	Price  float64
	Count  int
	Max    float64
	Min    float64
	Sum    float64
}

func main() {
	// Channels for data ingestion and result streaming
	tickChan := make(chan Tick)
	resultChan := make(chan Aggregate)

	// Processor goroutine: computes aggregates
	go func() {
		symbolData := make(map[string]SymbolData)
		for tick := range tickChan {
			// Update symbol data
			data, exists := symbolData[tick.Symbol]
			if !exists {
				data = SymbolData{
					Sum:     tick.Price,
					Count:   1,
					Max:     tick.Price,
					Min:     tick.Price,
				}
			} else {
				data.Sum += tick.Price
				data.Count++
				if tick.Price > data.Max {
					data.Max = tick.Price
				}
				if tick.Price < data.Min {
					data.Min = tick.Price
				}
			}
			symbolData[tick.Symbol] = data

			// Stream result
			resultChan <- Aggregate{
				Symbol: tick.Symbol,
				Price:  data.Sum / float64(data.Count),
				Count:  data.Count,
				Max:    data.Max,
				Min:    data.Min,
				Sum:    data.Sum,
			}
		}
	}()

	// Subscriber goroutine: consumes and processes results
	go func() {
		for result := range resultChan {
			fmt.Printf("Received aggregate for %s: Avg=%.2f, Count=%d, Max=%.2f, Min=%.2f, Sum=%.2f\n",
				result.Symbol, result.Price, result.Count, result.Max, result.Min, result.Sum)
		}
	}()

	// Simulate market data ingestion
	for i := 0; i < 10; i++ {
		tick := Tick{
			Symbol: "AAPL",
			Price:  150.0 + float64(i),
			Volume: 100,
		}
		tickChan <- tick
		time.Sleep(100 * time.Millisecond)
	}

	// Signal completion and close channels
	close(tickChan)
	close(resultChan)
}
```

