Here's a Go implementation of a real-time market data processor that computes price aggregates and streams results to subscribers. This example uses a simple TCP server for streaming and simulates market data ingestion.

```go
package main

import (
	"bufio"
	"fmt"
	"net"
	"sync"
	"time"
)

// MarketData represents a single market data point
type MarketData struct {
	Symbol string
	Price  float64
	Volume int
}

// Aggregate computes a simple moving average of the last 10 prices
func computeAggregate(data []MarketData) float64 {
	var sum float64
	for _, d := range data {
		sum += d.Price
	}
	return sum / float64(len(data))
}

func main() {
	// Channels for data ingestion and result streaming
	dataChan := make(chan MarketData)
	resultChan := make(chan MarketData)
	subscriberChan := make(chan net.Conn)

	// Simulate market data ingestion
	go func() {
		for {
			// Simulate market data (AAPL with random price and volume)
			symbol := "AAPL"
			price := 150.0 + (float64(time.Now().UnixNano()) / 1e9) // Random price
			volume := 1000 + int(time.Now().UnixNano()%1000)
			dataChan <- MarketData{Symbol: symbol, Price: price, Volume: volume}
			time.Sleep(100 * time.Millisecond)
		}
	}()

	// Processing loop with moving average calculation
	var priceHistory []MarketData
	const windowSize = 10
	go func() {
		for data := range dataChan {
			priceHistory = append(priceHistory, data)
			if len(priceHistory) > windowSize {
				priceHistory = priceHistory[1:]
			}
			aggregate := computeAggregate(priceHistory)
			resultChan <- MarketData{Symbol: data.Symbol, Price: aggregate, Volume: data.Volume}
		}
	}()

	// TCP server to stream results to subscribers
	listener, err := net.Listen("tcp", ":8080")
	if err != nil {
		panic(err)
	}
	defer listener.Close()
	fmt.Println("Server listening on :8080")

	// Handle subscriber connections
	var wg sync.WaitGroup
	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err)
			continue
		}
		fmt.Printf("New connection from %s\n", conn.RemoteAddr())
		wg.Add(1)
		go func(conn net.Conn) {
			defer wg.Done()
			defer conn.Close()

			// Stream results to this subscriber
			writer := bufio.NewWriter(conn)
			for result := range resultChan {
				// Format and send the result
				_, _ = writer.WriteString(fmt.Sprintf("%s: %.2f, Volume: %d\n", result.Symbol, result.Price, result.Volume))
				_, _ = writer.Flush()
			}
		}(conn)
	}
}
```

**Key Features:**
1. **Concurrency Model:** Uses Go's goroutines and channels for efficient concurrent processing.
2. **Real-Time Processing:** Computes a simple moving average of the last 10 prices.
3. **Streaming:** Streams results to multiple subscribers via a TCP server.
4. **Scalability:** Easily extendable to handle multiple symbols and complex aggregates.

