type WebSocketServer struct {
	clients   map[*websocket.Conn]bool
	aggregate Aggregate
	mu        sync.Mutex
}

func NewWebSocketServer() *WebSocketServer {
	return &WebSocketServer{
		clients: make(map[*websocket.Conn]bool),
	}
}

func (s *WebSocketServer) HandleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		fmt.Println("Upgrade error:", err)
		return
	}

	// Register client
	s.clients[conn] = true
	defer delete(s.clients, conn)

	// Send initial aggregate
	s.mu.Lock()
	if s.aggregate.Price > 0 {
		if err := conn.WriteJSON(s.aggregate); err != nil {
			fmt.Println("Write error:", err)
		}
	}
	s.mu.Unlock()

	// Read messages from client (e.g., subscription requests)
	_, _, err = conn.ReadMessage()
	if err != nil {
		fmt.Println("Read error:", err)
	}
}

func (s *WebSocketServer) BroadcastAggregate() {
	s.mu.Lock()
	defer s.mu.Unlock()

	// Simulate market data (replace with real data source)
	symbol := "AAPL"
	price := rand.Float64()*100 + 100 // Simulate price between 100 and 200
	s.aggregate = Aggregate{
		Symbol:     symbol,
		Price:      price,
		MovingAvg:  (s.aggregate.MovingAvg*4 + price) / 5, // Simple moving average
		LastUpdate: time.Now(),
	}

	// Broadcast to all clients
	for client := range s.clients {
		if err := client.WriteJSON(s.aggregate); err != nil {
			fmt.Println("Broadcast error:", err)
		}
	}
}

func main() {
	// Initialize server
	server := NewWebSocketServer()
	http.HandleFunc("/ws", server.HandleWebSocket)
	go func() {
		for {
			server.BroadcastAggregate()
			time.Sleep(1 * time.Second) // Simulate real-time data updates
		}
	}()

