// Define data structures
type MarketData struct {
	Symbol string
	Price  float64
	Time   time.Time
}

type Result struct {
	Symbol       string
	Aggregate    float64
	AggregateType string
	Time         time.Time
}

// Processor handles real-time data
func processMarketData(incomingData <-chan MarketData, outgoingResults chan<- Result) {
	// Map to track price history for each symbol
	priceHistory := make(map[string][]float64)
	windowSize := 10 // Moving average window

	for data := range incomingData {
		// Update price history for the symbol
		prices, exists := priceHistory[data.Symbol]
		if !exists {
			prices = []float64{}
		}
		prices = append(prices, data.Price)
		if len(prices) > windowSize {
			prices = prices[1:] // Keep only the last N prices
		}
		priceHistory[data.Symbol] = prices

		// Compute moving average if window is full
		if len(prices) >= windowSize {
			var sum float64
			for _, p := range prices {
				sum += p
			}
			avg := sum / float64(windowSize)
			result := Result{
				Symbol:       data.Symbol,
				Aggregate:    avg,
				AggregateType: "MovingAverage",
				Time:         data.Time,
			}
			outgoingResults <- result
		}
	}
}

// Subscriber listens to results and processes them
func subscribe(results <-chan Result, wg *sync.WaitGroup) {
	defer wg.Done()
	for result := range results {
		fmt.Printf("Subscriber received: Symbol=%s, Aggregate=%.2f, Type=%s, Time=%s\n",
			result.Symbol, result.Aggregate, result.AggregateType, result.Time)
	}
}

// Simulate real-time market data
func simulateMarketData(incomingData chan<- MarketData, duration time.Duration) {
	rand.Seed(time.Now().UnixNano())
	for {
		symbol := fmt.Sprintf("AAPL%02d", rand.Intn(100))
		price := 100.0 + float64(rand.Intn(100))
		data := MarketData{
			Symbol: symbol,
			Price:  price,
			Time:   time.Now(),
		}
		incomingData <- data
		time.Sleep(100 * time.Millisecond) // Simulate real-time data flow
	}
}

func main() {
	// Initialize channels
	incomingData := make(chan MarketData)
	outgoingResults := make(chan Result)

	// Start data simulation
	go simulateMarketData(incomingData, 10*time.Second)

	// Start data processor
	go processMarketData(incomingData, outgoingResults)

	// Start subscribers
	var wg sync.WaitGroup
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go subscribe(outgoingResults, &wg)
	}

	// Wait for all subscribers to finish
	wg.Wait()
}
