			if agg, exists := aggregates[update.Symbol]; exists {
				agg.Price += update.Price
				agg.Count++
				aggregates[update.Symbol] = agg
			} else {
				aggregates[update.Symbol] = Aggregate{
					Symbol: update.Symbol,
					Price:  update.Price,
					Count:  1,
				}
			}

			// Compute average
			avg := aggregates[update.Symbol].Price / float64(aggregates[update.Symbol].Count)
			resultChan <- Aggregate{
				Symbol: update.Symbol,
				Price:  avg,
				Count:  aggregates[update.Symbol].Count,
			}
		}
	}()

	// Subscriber goroutine: receives and prints results
	go func() {
		for result := range resultChan {
			fmt.Printf("Subscriber received: %s, Average: %.2f, Count: %d\n", result.Symbol, result.Price, result.Count)
