type Aggregate struct {
    Avg float64
    Max float64
    Min float64
}

func main() {
    // Channel for incoming market data
    dataChan := make(chan float64)
    // Channel for outgoing aggregates
    aggregateChan := make(chan Aggregate)
    // Wait group to manage goroutines
    var wg sync.WaitGroup

    // Simulate market data source
    wg.Add(1)
    go func() {
        defer wg.Done()
        for {
            price := rand.Float64() * 100 // Simulate random prices
            dataChan <- price
            time.Sleep(100 * time.Millisecond) // Simulate real-time data
        }
    }()

    // Process data and compute aggregates
    wg.Add(1)
    go func() {
        defer wg.Done()
        var prices []float64
        for price := range dataChan {
            prices = append(prices, price)
            if len(prices) > 10 { // Sliding window of 10 prices
                prices = prices[1:]
            }
            avg := computeAverage(prices)
            max := computeMax(prices)
            min := computeMin(prices)
            aggregateChan <- Aggregate{Avg: avg, Max: max, Min: min}
        }
    }()

    // Subscriber that receives aggregates
    wg.Add(1)
    go func() {
        defer wg.Done()
        for agg := range aggregateChan {
            fmt.Printf("Aggregate: Avg=%.2f, Max=%.2f, Min=%.2f\n", agg.Avg, agg.Max, agg.Min)
        }
    }()

    // Wait for all goroutines to finish
    wg.Wait()
}

// Helper functions
func computeAverage(prices []float64) float64 {
    sum := 0.0
    for _, p := range prices {
        sum += p
    }
    return sum / float64(len(prices))
}

func computeMax(prices []float64) float64 {
    max := prices[0]
    for _, p := range prices {
        if p > max {
            max = p
        }
    }
    return max
}

func computeMin(prices []float64) float64 {
    min := prices[0]
    for _, p := range prices {
        if p < min {
            min = p
        }
    }
    return min
}
