package main

import (
	"fmt"
	"math/rand"
	"net/http"
	"time"

	"github.com/gorilla/websocket"
)

// WebSocket upgrader config
var upgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

// Market data structure
type MarketData struct {
	Price     float64
	Timestamp time.Time
}

// Aggregate results
type Aggregates struct {
	Count    int
	Min      float64
	Max      float64
	Average  float64
}

// Global variables for state
var (
	aggregates Aggregates
	clients    = make(map[*websocket.Conn]bool)
)

// Handle WebSocket connection
func handleWebSocket(w http.ResponseWriter, r *http.Request) {
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		fmt.Println("Upgrade error:", err)
		return
	}
	defer conn.Close()
	clients[conn] = true

	// Broadcast initial aggregates
	if err := conn.WriteJSON(aggregates); err != nil {
		fmt.Println("Write error:", err)
	}
}

// Process market data and update aggregates
func processMarketData() {
	rand.Seed(time.Now().UnixNano())
	for {
		// Simulate incoming market data
		price := rand.Float64() * 100 // Random price between 0 and 100
		data := MarketData{
			Price:     price,
			Timestamp: time.Now(),
		}

		// Update aggregates
		aggregates.Count++
		if aggregates.Count == 1 {
			aggregates.Min = price
			aggregates.Max = price
		} else {
			if price < aggregates.Min {
				aggregates.Min = price
			}
			if price > aggregates.Max {
				aggregates.Max = price
			}
		}
		aggregates.Average = (aggregates.Average*(float64(aggregates.Count-1) + price)) / float64(aggregates.Count)

		// Broadcast to all connected clients
		for conn := range clients {
			conn.WriteJSON(aggregates)
		}

		// Simulate data ingestion rate (100ms interval)
		time.Sleep(100 * time.Millisecond)
	}
}

// HTTP endpoint to get current aggregates
func getAggregates(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	if err := json.NewEncoder(w).Encode(aggregates); err != nil {
		http.Error(w, "Internal Server Error", http.StatusInternalServerError)
	}
}

func main() {
	// Start the market data processing goroutine
	go processMarketData()

	// HTTP server routes
	http.HandleFunc("/ws", handleWebSocket)
	http.HandleFunc("/aggregates", getAggregates)

