package main

import (
	"bufio"
	"fmt"
	"net"
	"sync"
	"time"
)

// Simulated market data source
var priceChannel = make(chan float64)

// Clients map to track active connections
var clients = make(map[string]*net.Conn)
var mu sync.Mutex

// Handle client connections
func handleConnection(conn net.Conn) {
	defer conn.Close()
	mu.Lock()
	clientID := fmt.Sprintf("%p", conn)
	clients[clientID] = &conn
	mu.Unlock()
	fmt.Fprintf(conn, "Connected to market data stream\n")
}

// Broadcast price updates to all subscribers
func broadcastPrice(price float64) {
	mu.Lock()
	for _, conn := range clients {
		conn.Write([]byte(fmt.Sprintf("Price: %.2f\n", price)))
	}
	mu.Unlock()
}

func main() {
	// Start TCP server
	listener, err := net.Listen("tcp", ":8080")
	if err != nil {
		panic(err)
	}
	defer listener.Close()
	fmt.Println("Server listening on :8080")

	// Accept incoming connections
	for {
		conn, err := listener.Accept()
		if err != nil {
			fmt.Println("Error accepting connection:", err)
			continue
		}
		go handleConnection(conn)
	}

	// Simulate real-time market data
	go func() {
		for {
			// Generate fake price data (e.g., random fluctuations)
			price := 100.0 + (float64(time.Now().UnixNano())%100)/100.0
			priceChannel <- price
			time.Sleep(100 * time.Millisecond) // Simulate 10 updates per second
		}
	}()

	// Process price updates and broadcast
	for price := range priceChannel {
		broadcastPrice(price)
	}
}
