package main

import (
	"fmt"
	"math/rand"
	"sync"
	"time"
)

// MarketData represents a price update
type MarketData struct {
	Symbol string
	Price  float64
}

// Aggregate computes the average price for each symbol
func computeAggregates(dataChan <-chan MarketData, resultChan chan<- map[string]float64) {
	aggregates := make(map[string]float64)
	counts := make(map[string]int)

	for data := range dataChan {
		counts[data.Symbol]++
		aggregates[data.Symbol] += data.Price
	}

	// Calculate averages
	for symbol, total := range aggregates {
		aggregates[symbol] = total / float64(counts[symbol])
	}

	resultChan <- aggregates
}

// Subscriber listens to results and prints them
func subscriber(resultChan <-chan map[string]float64) {
	for results := range resultChan {
		fmt.Println("Price Aggregates:", results)
	}
}

func main() {
	// Simulate real-time market data stream
	dataChan := make(chan MarketData)
	resultChan := make(chan map[string]float64)

	// Start processing goroutine
	go computeAggregates(dataChan, resultChan)

