Here's a high-performance Go implementation of a high-frequency messaging system with latency monitoring. This example uses goroutines for concurrency, channels for message routing, and precise timing for latency tracking.

```go
package main

import (
	"fmt"
	"sync"
	"time"
)

// Message represents a message with type and payload
type Message struct {
	Type  string
	Data  []byte
	Seq   uint64
}

// RouterConfig defines router parameters
type RouterConfig struct {
	NumWorkers     int
	MaxQueueSize   int
	Timeout        time.Duration
	StatsInterval  time.Duration
}

// MessageRouter handles message routing with latency monitoring
type MessageRouter struct {
	cfg        *RouterConfig
	incoming   chan *Message
	outgoing   chan *Message
	latency    chan time.Duration
	metrics    map[string]*LatencyStats
	mu         sync.RWMutex
	wg         sync.WaitGroup
}

// LatencyStats tracks latency metrics for different message types
type LatencyStats struct {
	Count     uint64
