		}

		latency := time.Since(start)
		r.latency <- latency

		// Update metrics
		r.mu.Lock()
		stats := r.metrics[msg.Type]
		stats.Count++
		stats.Total += latency
		stats.Min = min(stats.Min, latency)
		stats.Max = max(stats.Max, latency)
		stats.Last = latency
