	t.mu.Lock()
	defer t.mu.Unlock()

	stats, exists := t.stats[topic]
	if !exists {
		stats = &LatencyStats{
			TotalLatency: latency,
			Count:        1,
			MaxLatency:   latency,
		}
	} else {
		stats.TotalLatency += latency
		stats.Count++
		if latency > stats.MaxLatency {
			stats.MaxLatency = latency
		}
	}
	t.stats[topic] = stats
}

