// Router class for high-frequency messaging
class MessageRouter {
public:
    MessageRouter(size_t num_threads, const std::unordered_map<std::string, MessageHandler>& handlers)
        : stop(false), handlers(handlers), stats() {
        // Initialize thread pool
        for (size_t i = 0; i < num_threads; ++i) {
            workers.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(queue_mutex);
                    condition.wait(lock, [this] { return stop || !message_queue.empty(); });
                    if (stop && message_queue.empty()) break;

                    // Process message
                    auto msg = message_queue.front();
                    message_queue.pop();
                    lock.unlock();

                    // Route message
                    auto it = handlers.find(msg.destination);
                    if (it != handlers.end()) {
                        it->second(msg);
                        updateLatencyStats(msg);
                    } else {
                        std::cerr << "No handler found for destination: " << msg.destination << std::endl;
                    }
                }
            });
        }
    }

    ~MessageRouter() {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            stop = true;
        }
        condition.notify_all();
        for (auto& worker : workers) {
            worker.join();
        }
    }

    void sendMessage(const Message& msg) {
        {
            std::unique_lock<std::mutex> lock(queue_mutex);
            message_queue.push(msg);
        }
        condition.notify_one();
    }

    void updateLatencyStats(const Message& msg) {
        auto end_time = std::chrono::steady_clock::now();
        auto latency = std::chrono::duration_cast<std::chrono::microseconds>(end_time - msg.arrival_time).count();

        stats.message_count++;
        stats.total_latency += latency;
        stats.avg_latency = stats.total_latency / stats.message_count;
    }

    void printStats() const {
        std::cout << "Latency Stats:\n";
        std::cout << "  Messages processed: " << stats.message_count << "\n";
        std::cout << "  Total latency: " << stats.total_latency << " microseconds\n";
        std::cout << "  Average latency: " << stats.avg_latency << " microseconds\n";
    }

private:
    std::vector<std::thread> workers;
    std::queue<Message> message_queue;
    std::mutex queue_mutex;
    std::condition_variable condition;
    std::atomic<bool> stop;
    std::unordered_map<std::string, MessageHandler> handlers;
    LatencyStats stats;
};

