	r.mu.Lock()
	defer r.mu.Unlock()
	r.handlers[msgType] = handler
}

func (r *Router) Route(msg *Message) error {
	r.mu.RLock()
	defer r.mu.RUnlock()
	handler, exists := r.handlers[msg.Type]
	if !exists {
		return fmt.Errorf("no handler for message type: %s", msg.Type)
	}
	return handler(msg)
}

// LatencyMonitor tracks and reports latency metrics
