		metrics: make(map[string][]time.Duration),
	}
}

func (lm *LatencyMonitor) RecordLatency(msgType string, latency time.Duration) {
	lm.mu.Lock()
	defer lm.mu.Unlock()
	lm.metrics[msgType] = append(lm.metrics[msgType], latency)
}

func (lm *LatencyMonitor) PrintMetrics() {
	lm.mu.RLock()
	defer lm.mu.RUnlock()
	for msgType, latencies := range lm.metrics {
		avg := time.Duration(0)
		for _, l := range latencies {
			avg += l
		}
		avg /= time.Duration(len(latencies))
