func (lt *LatencyTracker) RecordLatency(latency time.Duration) {
	lt.mu.Lock()
	defer lt.mu.Unlock()
	lt.latency = append(lt.latency, latency)
}

func (lt *LatencyTracker) GetStats() map[string]float64 {
	lt.mu.Lock()
	defer lt.mu.Unlock()

	if len(lt.latency) == 0 {
		return map[string]float64{"avg": 0, "p99": 0}
	}

	// Sort latencies
	sort.Slice(lt.latency, func(i, j int) bool {
		return lt.latency[i] < lt.latency[j]
	})

	avg := float64(0)
	for _, d := range lt.latency {
		avg += float64(d)
	}
	avg /= float64(len(lt.latency))

	p99 := float64(lt.latency[len(lt.latency)-1])
	return map[string]float64{"avg": avg, "p99": p99}
}

