package main

import (
	"fmt"
	"log"
	"sync"
	"time"
)

// Message represents a message with a unique ID, payload, and metadata
type Message struct {
	ID        string
	Payload   []byte
	Header    map[string]string
	Timestamp time.Time
}

// LatencyStats tracks latency metrics
type LatencyStats struct {
	TotalMessages int
	MinLatency    time.Duration
	MaxLatency    time.Duration
	AvgLatency    time.Duration
	Stats         map[string][]time.Duration // Histogram buckets
}

// Router routes messages to destinations
func Router(messages <-chan Message, results chan<- Message, stats *LatencyStats, wg *sync.WaitGroup) {
	defer wg.Done()

	for msg := range messages {
		// Simulate routing logic (e.g., based on header)
		destination := msg.Header["destination"]
		if destination == "" {
			destination = "default"
		}

		// Simulate processing delay (adjust for real logic)
		processingTime := time.Duration(100+rand.Intn(500)) * time.Microsecond
		time.Sleep(processingTime)

		// Calculate latency
		latency := time.Since(msg.Timestamp)
		stats.TotalMessages++
		stats.MinLatency = min(stats.MinLatency, latency)
		stats.MaxLatency = max(stats.MaxLatency, latency)
		stats.AvgLatency = (stats.AvgLatency * (float64(stats.TotalMessages)-1) + float64(latency)) / float64(stats.TotalMessages)

		// Log latency to histogram
		bucket := getLatencyBucket(latency)
		stats.Stats[bucket] = append(stats.Stats[bucket], latency)

		// Forward message
		results <- Message{
			ID:        msg.ID,
			Payload:   msg.Payload,
			Header:    msg.Header,
			Timestamp: time.Now(),
		}
	}
}

// Helper functions
func min(a, b time.Duration) time.Duration {
	if a < b {
		return a
	}
	return b
}

func max(a, b time.Duration) time.Duration {
	if a > b {
		return a
	}
	return b
}

func getLatencyBucket(latency time.Duration) string {
	buckets := []time.Duration{100, 500, 1000, 5000, 10000}
	for _, b := range buckets {
		if latency < b {
			return fmt.Sprintf("<%dμs", b)
		}
	}
	return ">=10ms"
}

// Monitor updates latency stats periodically
func Monitor(stats *LatencyStats, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()

	for range ticker.C {
		fmt.Printf("Latency Stats:\n")
		fmt.Printf("  Total Messages: %d\n", stats.TotalMessages)
		fmt.Printf("  Min Latency: %v\n", stats.MinLatency)
		fmt.Printf("  Max Latency: %v\n", stats.MaxLatency)
		fmt.Printf("  Avg Latency: %v\n", stats.AvgLatency)
		fmt.Printf("  Histogram:\n")
		for bucket, durations := range stats.Stats {
			count := len(durations)
			if count > 0 {
				fmt.Printf("    %s: %d messages\n", bucket, count)
			}
		}
	}
}

func main() {
	// Initialize stats
	stats := &LatencyStats{
		Stats: make(map[string][]time.Duration),
	}

	// Setup workers
	const numWorkers = 100
	var wg sync.WaitGroup
	messages := make(chan Message, 10000)
	results := make(chan Message, 10000)

	// Start workers
	for i := 0; i < numWorkers; i++ {
		wg.Add(1)
		go Router(messages, results, stats, &wg)
	}

	// Start latency monitor
