// Memory pool for efficient message allocation
class MessagePool {
public:
    MessagePool(size_t size) : buffer_(new Message[size]), pool_(buffer_.get(), size) {}

    Message* allocate() {
        return pool_.allocate();
    }

    void deallocate(Message* msg) {
        pool_.deallocate(msg);
    }

private:
    std::aligned_storage<sizeof(Message), alignof(Message)>::type* buffer_;
    std::vector<Message*> pool_;
};

// Latency Monitor
class LatencyMonitor {
public:
    void recordLatency(const std::chrono::duration<double, std::nano>& latency) {
        std::lock_guard<std::mutex> lock(mutex_);
        latencies_.push_back(latency.count());
    }

    void printStats() {
        std::lock_guard<std::mutex> lock(mutex_);
        if (latencies_.empty()) return;

        double sum = 0.0;
        for (double l : latencies_) sum += l;
        double avg = sum / latencies_.size();

        std::cout << "Latency stats (avg: " << avg << " ns, count: " << latencies_.size() << ")\n";
    }

private:
    std::vector<double> latencies_;
    std::mutex mutex_;
};

