)

// Message struct with an ID and payload
type Message struct {
	ID      string
	Payload string
}

// LatencyRecorder tracks message latencies
type LatencyRecorder struct {
	metrics map[string]time.Duration
	mu      sync.Mutex
}

func NewLatencyRecorder() *LatencyRecorder {
	return &LatencyRecorder{
		metrics: make(map[string]time.Duration),
	}
}

func (lr *LatencyRecorder) RecordLatency(msgID string, duration time.Duration) {
	lr.mu.Lock()
	defer lr.mu.Unlock()
	lr.metrics[msgID] = duration
}

func (lr *LatencyRecorder) PrintLatencies() {
	fmt.Println("Latency Metrics:")
	for msgID, duration := range lr.metrics {
		fmt.Printf("Message %s: %v\n", msgID, duration)
	}
}

// Producer sends messages to a channel
func producer(ch chan<- Message, count int) {
	for i := 0; i < count; i++ {
		msg := Message{
			ID:      fmt.Sprintf("MSG-%d", i),
			Payload: fmt.Sprintf("Payload-%d", rand.Intn(1000)),
		}
		ch <- msg
	}
	close(ch)
}

// Router routes messages to destinations based on payload
func router(in <-chan Message, destinations map[string]chan Message, lr *LatencyRecorder) {
	for msg := range in {
		// Simulate routing logic: route based on payload length
		dest := "default"
		if len(msg.Payload) > 10 {
			dest = "high-priority"
		}
		destinations[dest] <- msg
	}
}

// Consumer processes messages and records latency
func consumer(in <-chan Message, lr *LatencyRecorder) {
	for msg := range in {
		start := time.Now()
		// Simulate processing (e.g., data transformation, DB write, etc.)
		time.Sleep(time.Millisecond * 1) // Simulate work
		latency := time.Since(start)
		lr.RecordLatency(msg.ID, latency)
	}
}

func main() {
	// Configuration
	const (
		msgCount     = 1000000 // 1 million messages
		numProducers = 10
		numConsumers = 4
	)

	// Setup channels
	messages := make(chan Message, 10000)
	destinations := map[string]chan Message{
		"default":  make(chan Message, 10000),
		"high-priority": make(chan Message, 10000),
	}

	// Start producers
	var wg sync.WaitGroup
	wg.Add(numProducers)
	for i := 0; i < numProducers; i++ {
		go func() {
			defer wg.Done()
			producer(messages, msgCount/numProducers)
		}()
	}

	// Start router
	go router(messages, destinations, NewLatencyRecorder())

	// Start consumers
	for i := 0; i < numConsumers; i++ {
		go consumer(destinations["default"], NewLatencyRecorder())
		go consumer(destinations["high-priority"], NewLatencyRecorder())
	}

	// Wait for producers to finish
	wg.Wait()
	close(destinations["default"])
	close(destinations["high-priority"])

	// Print latency metrics
	for _, lr := range []*LatencyRecorder{
		NewLatencyRecorder(), // Default consumer
		NewLatencyRecorder(), // High-priority consumer
	} {
		lr.PrintLatencies()
	}
}
