	}
}

func main() {
	// Configuration
	const (
		numConsumers    = 2
		msgCount        = 1000000 // 1 million messages
		msgSize         = 100    // bytes
		latencyInterval = 100 * time.Millisecond
	)

	// Initialize channels
	msgChan := make(chan Message, 1000) // Buffered for throughput
	latencyChan := make(chan time.Duration, msgCount)

	// Start consumers
	var wg sync.WaitGroup
	for i := 0; i < numConsumers; i++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			consumer(id, msgChan, latencyChan)
		}(i)
	}

	// Producer: send messages with timestamps
	startTime := time.Now()
	for i := 0; i < msgCount; i++ {
		msg := Message{
			ID:       i,
			Payload:  fmt.Sprintf("data-%d", i),
			StartTime: time.Now(),
		}
		msgChan <- msg
	}

	// Close channels to signal completion
	close(msgChan)

	// Wait for all consumers to finish
	wg.Wait()

	// Calculate and print average latency
	var totalLatency time.Duration
	var count int
	for latency := range latencyChan {
		totalLatency += latency
		count++
	}
	avgLatency := totalLatency / time.Duration(count)
	fmt.Printf("\nTotal messages: %d\nAverage latency: %v\n", msgCount, avgLatency)

	// Optional: Monitor latency in real-time (for demonstration)
	go func() {
		ticker := time.NewTicker(latencyInterval)
		defer ticker.Stop()
		for range ticker.C {
			var total time.Duration
			var cnt int
			for latency := range latencyChan {
				total += latency
				cnt++
			}
			if cnt > 0 {
				fmt.Printf("Current average latency: %v\n", total/cnt)
			}
		}
	}()
}
