Here's a **C** implementation of an ultra-low-latency networking service with packet-level filtering and forwarding. This example uses **libpcap** for packet capture and filtering, and **raw sockets** for forwarding. It includes basic filtering (e.g., TCP port 80) and assumes Linux (or similar Unix-like systems with `libpcap` support).

---

### ✅ **C Code: Ultra-Low-Latency Packet Filtering & Forwarding**
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>

#define FORWARD_INTERFACE "eth1"  // Replace with your forwarding interface
#define FILTER "tcp port 80"      // Example filter: TCP port 80

// Packet handler function
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Extract IP header (assuming Ethernet frame)
    struct ip *ip_header = (struct ip *)(packet + 14);  // Skip Ethernet header

    // Basic filtering: TCP port 80 (HTTP)
    if (ip_header->ip_p == IPPROTO_TCP) {
        struct tcphdr *tcp_header = (struct tcphdr *)((char *)ip_header + sizeof(struct ip));
        if (ntohs(tcp_header->th_sport) == 80 || ntohs(tcp_header->th_dport) == 80) {
            // Forward the packet
            int sockfd;
            struct sockaddr_in dest_addr;
            char buffer[65536];

            // Create raw socket
            sockfd = socket(AF_INET, SOCK_RAW, IPPROTO_RAW);
            if (sockfd < 0) {
                perror("Socket creation failed");
                return;
            }

            // Set destination address
            memset(&dest_addr, 0, sizeof(dest_addr));
            dest_addr.sin_family = AF_INET;
            dest_addr.sin_port = htons(80);  // Example: forward to port 80
            inet_aton("192.168.1.2", &dest_addr.sin_addr);  // Replace with target IP

            // Send packet
            if (sendto(sockfd, packet, pkthdr->len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
                perror("Packet forwarding failed");
            }

            close(sockfd);
        }
    }
}

int main(int argc, char *argv[]) {
    pcap_t *handle;
    char errbuf[PCAP_ERRBUF_SIZE];
    struct bpf_program fp;
    char *dev = "eth0";  // Replace with your capture interface

    // Open live capture
    handle = pcap_open_live(dev, 65536, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return -1;
    }

    // Compile filter
    if (pcap_compile(handle, &fp, FILTER, 0, PCAP_NETMASK_DEFAULT) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", FILTER, pcap_geterr(handle));
        return -1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't set filter %s: %s\n", FILTER, pcap_geterr(handle));
        return -1;
    }

    // Start packet capture
    pcap_loop(handle, 0, packet_handler, NULL);

    pcap_close(handle);
    return 0;
}
```

