void forward_packet(const u_char *packet, int packet_len, const char *dest_iface) {
    int sockfd;
    struct sockaddr_ll dest_addr;
    struct ifreq ifr;
    char buffer[PACKET_BUFFER_SIZE];

    // Open raw socket
