        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Get interface index
    strcpy(ifr.ifr_name, dest_iface);
    if (ioctl(sockfd, SIOCGIFINDEX, &ifr) < 0) {
        perror("ioctl");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    // Set destination address
    memset(&dest_addr, 0, sizeof(dest_addr));
    dest_addr.sll_family = AF_PACKET;
    dest_addr.sll_ifindex = ifr.ifr_ifindex;
    dest_addr.sll_hatype = 0;
    dest_addr.sll_pkttype = 0;
    dest_addr.sll_halen = 0;  // Leave blank for default

    // Forward packet
    if (sendto(sockfd, packet, packet_len, 0, (struct sockaddr *)&dest_addr, sizeof(dest_addr)) < 0) {
        perror("sendto");
    }

    close(sockfd);
}

