### 📦 **Minimal Ultra-Low-Latency Networking Service (C)**  
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <linux/if_packet.h>
#include <net/ethernet.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <net/if.h>

// Simple packet filtering: forward packets not destined for loopback
int main() {
    int sockfd;
    struct sockaddr_ll sll;
    char buffer[65536];
    int bytes_read;

    // Create raw socket for packet capture (requires root)
    sockfd = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sockfd < 0) {
        perror("socket");
        exit(EXIT_FAILURE);
    }

    // Bind to a specific interface (e.g., eth0)
    memset(&sll, 0, sizeof(sll));
    sll.sll_family = AF_PACKET;
    sll.sll_ifindex = if_nametoindex("eth0");
    sll.sll_protocol = htons(ETH_P_ALL);

    if (bind(sockfd, (struct sockaddr*)&sll, sizeof(sll)) < 0) {
        perror("bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        bytes_read = read(sockfd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            perror("read");
            continue;
        }

        // Parse Ethernet header
        struct ethhdr *eth = (struct ethhdr*)buffer;
        if (ntohs(eth->h_proto) == ETH_P_IP) {
            // Extract IP header
            struct iphdr *ip = (struct iphdr*)(buffer + sizeof(struct ethhdr));
            if (ip->daddr != htonl(INADDR_LOOPBACK)) {
                // Forward packet (simplified example)
                struct sockaddr_ll sll_out;
                memset(&sll_out, 0, sizeof(sll_out));
                sll_out.sll_family = AF_PACKET;
                sll_out.sll_ifindex = if_nametoindex("eth1"); // Forward to another interface
                sll_out.sll_protocol = htons(ETH_P_ALL);

                if (sendto(sockfd, buffer, bytes_read, 0, (struct sockaddr*)&sll_out, sizeof(sll_out)) < 0) {
                    perror("sendto");
                }
            }
        }
    }

    close(sockfd);
    return 0;
}
```

