### 📌 **Minimal Ultra-Low-Latency Networking Service in C**
```c
#include <pcap.h>
#include <stdio.h>
#include <string.h>
#include <arpa/inet.h>

// Packet handler: filter and forward packets
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    // Example: Filter TCP packets on port 80
    // Extract Ethernet header
    struct ether_header *eth_hdr = (struct ether_header *)packet;
    if (ntohs(eth_hdr->ether_type) != ETHERTYPE_IP) return; // Skip non-IP packets

    // Extract IP header
    struct ip *ip_hdr = (struct ip *)(packet + sizeof(struct ether_header));
    if (ip_hdr->ip_p != IPPROTO_TCP) return; // Skip non-TCP packets

    // Extract TCP header
    struct tcphdr *tcp_hdr = (struct tcphdr *)((char *)ip_hdr + (ip_hdr->ip_hl * 4));
    if (ntohs(tcp_hdr->th_dport) != 80) return; // Skip non-HTTP traffic

    // Forward the packet (e.g., to another interface)
    // Replace "eth1" with the target interface
    pcap_t *forward_handle = (pcap_t *)user_data;
    if (pcap_sendpacket(forward_handle, packet, pkthdr->len) != 0) {
        fprintf(stderr, "Error sending packet: %s\n", pcap_geterr(forward_handle));
    }
}

int main() {
    pcap_t *capture_handle, *forward_handle;
    char errbuf[PCAP_ERRBUF_SIZE];
    char *dev = "eth0"; // Capture interface
    char *forward_dev = "eth1"; // Forward interface
    char *filter_exp = "tcp port 80"; // Filter rule

    // Open capture interface
    capture_handle = pcap_open_live(dev, 65536, 1, 1000, errbuf);
    if (!capture_handle) {
        fprintf(stderr, "Failed to open capture interface: %s\n", errbuf);
        return -1;
    }

    // Open forward interface
    forward_handle = pcap_open_live(forward_dev, 65536, 1, 1000, errbuf);
    if (!forward_handle) {
        fprintf(stderr, "Failed to open forward interface: %s\n", errbuf);
        pcap_close(capture_handle);
        return -1;
    }

    // Compile and apply filter
    struct bpf_program fp;
    if (pcap_compile(capture_handle, &fp, filter_exp, 0, PCAP_NETMASK_UNKNOWN) < 0) {
        fprintf(stderr, "Filter compilation failed: %s\n", pcap_geterr(capture_handle));
        pcap_close(capture_handle);
        pcap_close(forward_handle);
        return -1;
    }
    if (pcap_setfilter(capture_handle, &fp) < 0) {
        fprintf(stderr, "Filter application failed: %s\n", pcap_geterr(capture_handle));
        pcap_close(capture_handle);
        pcap_close(forward_handle);
        return -1;
    }

    // Start packet capture
    if (pcap_loop(capture_handle, 0, packet_handler, (u_char *)forward_handle) < 0) {
        fprintf(stderr, "Packet capture failed: %s\n", pcap_geterr(capture_handle));
    }

    pcap_close(capture_handle);
    pcap_close(forward_handle);
    return 0;
}
```

