                return;
            }

            // Set destination MAC address (e.g., loopback)
            dest_addr.sll_family = AF_PACKET;
            dest_addr.sll_protocol = htons(ETH_P_ALL);
            dest_addr.sll_ifindex = 1; // lo interface
            dest_addr.sll_hatype = 0;
            dest_addr.sll_pkttype = 0;
            dest_addr.sll_halen = 0;
            dest_addr.sll_addr[0] = 0xff; // Loopback MAC
            dest_addr.sll_addr[1] = 0xff;
            dest_addr.sll_addr[2] = 0xff;
            dest_addr.sll_addr[3] = 0xff;
            dest_addr.sll_addr[4] = 0xff;
            dest_addr.sll_addr[5] = 0xff;

            // Forward the packet
            if (sendto(sockfd, packet, pkthdr->len, 0, (struct sockaddr *)&dest_addr, addr_len) < 0) {
                perror("Packet forwarding failed");
            }

            close(sockfd);
        }
    }
