#include <mutex>
#include <condition_variable>
#include <cstdint>

// Configuration
constexpr size_t BUFFER_SIZE = 1 << 16; // 64KB buffer for minimal memory
constexpr size_t MAX_CONCURRENT_THREADS = 4;

// Custom data structure for parsed records
struct Record {
    std::string key;
    std::string value;
};

// Thread-safe queue for processed records
class RecordQueue {
public:
    void push(const Record& record) {
        std::lock_guard<std::mutex> lock(mutex_);
        queue_.push_back(record);
        cv_.notify_one();
    }

    Record pop() {
        std::unique_lock<std::mutex> lock(mutex_);
        cv_.wait(lock, [this] { return !queue_.empty(); });
        Record record = queue_.front();
        queue_.pop_front();
        return record;
    }

    bool empty() const {
        std::lock_guard<std::mutex> lock(mutex_);
        return queue_.empty();
    }

private:
    std::deque<Record> queue_;
    mutable std::mutex mutex_;
    std::condition_variable cv_;
};

// Parser thread function
void parse_stream(std::ifstream& input, RecordQueue& queue) {
    char buffer[BUFFER_SIZE];
    std::atomic<bool> running = true;

    while (running) {
        // Read data in chunks
        size_t bytesRead = input.read(buffer, BUFFER_SIZE).gcount();
        if (bytesRead == 0) {
            if (input.eof()) running = false;
            continue;
        }

        // Process buffer (e.g., split lines, parse records)
        size_t offset = 0;
        while (offset < bytesRead) {
            // Find newline delimiter
            size_t newlinePos = std::string(buffer + offset).find('\n');
            if (newlinePos == std::string::npos) {
                // No newline in buffer, process remaining data
                break;
            }

            // Extract line
            std::string line(buffer + offset, newlinePos);
            offset += newlinePos + 1;

            // Parse line (example: key=value)
            size_t eqPos = line.find('=');
            if (eqPos != std::string::npos) {
                Record record;
                record.key = line.substr(0, eqPos);
                record.value = line.substr(eqPos + 1);
                queue.push(record);
            }
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <input_file>" << std::endl;
        return 1;
    }

    std::ifstream input(argv[1], std::ios::binary | std::ios::ate);
    if (!input) {
        std::cerr << "Error opening file" << std::endl;
        return 1;
    }

    // Calculate file size
    std::streamsize fileSize = input.tellg();
    input.seekg(0, std::ios::beg);

    // Initialize thread pool
    std::vector<std::thread> threads;
    RecordQueue queue;
    std::atomic<bool> allThreadsDone = false;

    for (size_t i = 0; i < MAX_CONCURRENT_THREADS && i < fileSize; ++i) {
        threads.emplace_back(parse_stream, std::ref(input), std::ref(queue));
    }

    // Process results from queue
    while (!allThreadsDone) {
        if (queue.empty()) {
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        } else {
            Record record = queue.pop();
            std::cout << "Parsed: " << record.key << " = " << record.value << std::endl;
        }
    }

    // Join threads
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
