// Memory-mapped file reader
class MappedFileReader {
public:
    MappedFileReader(const std::string& filename) : fd(-1), mapped_data(nullptr), size(0) {
        fd = open(filename.c_str(), O_RDONLY);
        if (fd == -1) {
            std::cerr << "Failed to open file: " << filename << "\n";
            exit(1);
        }

        struct stat st;
        if (fstat(fd, &st) == -1) {
            std::cerr << "Failed to get file size: " << filename << "\n";
            exit(1);
        }
        size = st.st_size;

        mapped_data = mmap(nullptr, size, PROT_READ, MAP_SHARED, fd, 0);
        if (mapped_data == MAP_FAILED) {
            std::cerr << "Failed to map file: " << filename << "\n";
            exit(1);
        }
    }

    ~MappedFileReader() {
        if (mapped_data != MAP_FAILED) munmap(mapped_data, size);
        if (fd != -1) close(fd);
    }

    const uint8_t* data() const { return mapped_data; }
    size_t size() const { return size; }
};

// Thread-safe buffer queue
class BufferQueue {
public:
    BufferQueue(size_t capacity) : capacity(capacity), buffer_count(0), head(0), tail(0) {}

    void enqueue(const std::vector<uint8_t>& buffer) {
        std::lock_guard<std::mutex> lock(mutex);
        if (buffer_count >= capacity) return; // Drop buffer if full
        buffers[head] = buffer;
        head = (head + 1) % capacity;
        buffer_count++;
    }

    std::vector<uint8_t> dequeue() {
        std::lock_guard<std::mutex> lock(mutex);
        if (buffer_count == 0) return {}; // No buffer available
        std::vector<uint8_t> buffer = buffers[tail];
        tail = (tail + 1) % capacity;
        buffer_count--;
        return buffer;
    }

private:
    std::vector<std::vector<uint8_t>> buffers;
    size_t capacity;
    size_t buffer_count;
    size_t head;
    size_t tail;
    std::mutex mutex;
};

// Consumer thread
void consumerThread(BufferQueue& queue, DataParser& parser) {
    std::vector<uint8_t> buffer(BUFFER_SIZE);
    while (true) {
        auto data = queue.dequeue();
        if (data.empty()) continue; // No data available

        // Process data in chunks
        size_t offset = 0;
        while (offset < data.size()) {
            size_t chunkSize = std::min(BUFFER_SIZE, data.size() - offset);
            std::copy(data.begin() + offset, data.begin() + offset + chunkSize, buffer.begin());
            parser.parse(buffer.data(), chunkSize);
            offset += chunkSize;
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <input_file>\n";
        return 1;
    }

    std::string filename = argv[1];
    MappedFileReader reader(filename);
    size_t fileSize = reader.size();

    // Initialize buffer queue
    BufferQueue bufferQueue(NUM_CONSUMER_THREADS * BUFFER_SIZE);

    // Start consumer threads
    std::vector<std::thread> threads;
    for (size_t i = 0; i < NUM_CONSUMER_THREADS; ++i) {
        threads.emplace_back(consumerThread, std::ref(bufferQueue), JSONParser());
    }

    // Producer: Read data in chunks and enqueue
    std::vector<uint8_t> chunk(BUFFER_SIZE);
    size_t offset = 0;
    while (offset < fileSize) {
        size_t remaining = fileSize - offset;
        size_t chunkSize = std::min(BUFFER_SIZE, remaining);
        std::copy(reader.data() + offset, reader.data() + offset + chunkSize, chunk.begin());
        bufferQueue.enqueue(chunk);
        offset += chunkSize;
    }

    // Join threads
    for (auto& t : threads) t.join();

    return 0;
}
