### ✅ **C Implementation**
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <sys/resource.h>

#define LOG_FILE "app.log"
#define MAX_LOG_SIZE (10 * 1024 * 1024) // 10 MB
#define MAX_BUFFER_SIZE 1024

// Signal handler for graceful shutdown
void handle_signal(int signum) {
    syslog(LOG_NOTICE, "Received signal %d, exiting...", signum);
    exit(EXIT_SUCCESS);
}

// Daemonize the process
void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "Failed to fork");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent exits
        exit(EXIT_SUCCESS);
    }

    // Child process
    if (setsid() < 0) {
        syslog(LOG_ERR, "Failed to create new session");
        exit(EXIT_FAILURE);
    }

    // Redirect standard file descriptors
    freopen("/dev/null", "r", stdin);
    freopen("/dev/null", "w", stdout);
    freopen("/dev/null", "w", stderr);

    // Change working directory
    if (chdir("/") < 0) {
        syslog(LOG_ERR, "Failed to change working directory");
        exit(EXIT_FAILURE);
    }
}

// Rotate log file
void rotate_log() {
    char new_log[256];
    snprintf(new_log, sizeof(new_log), "%s.1", LOG_FILE);

    // Rename current log to new_log
    if (rename(LOG_FILE, new_log) < 0) {
        syslog(LOG_ERR, "Failed to rename log file: %m");
        return;
    }

    // Truncate new log file
    int fd = open(LOG_FILE, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to create new log file: %m");
        return;
    }
    close(fd);

    syslog(LOG_NOTICE, "Log rotated: %s -> %s", LOG_FILE, new_log);
}

int main() {
    // Initialize syslog
    openlog("logrotate", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGHUP, handle_signal);

    // Daemonize
    daemonize();

    // Main loop
    while (1) {
        // Check log file size
        struct stat st;
        if (stat(LOG_FILE, &st) < 0) {
            syslog(LOG_ERR, "Failed to stat log file: %m");
            sleep(60); // Wait before retrying
            continue;
        }

        if (st.st_size > MAX_LOG_SIZE) {
            rotate_log();
        }

        // Sleep for a while before checking again
        sleep(60);
    }

    closelog();
    return 0;
}
```

