        perror("open /dev/null");
        exit(EXIT_FAILURE);
    }
    if (dup2(fd, STDIN_FILENO) < 0 || dup2(fd, STDOUT_FILENO) < 0 || dup2(fd, STDERR_FILENO) < 0) {
        perror("dup2");
        exit(EXIT_FAILURE);
    }
    if (close(fd) < 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }

    // Change working directory
    if (chdir("/") < 0) {
        perror("chdir");
        exit(EXIT_FAILURE);
    }
}

// Signal handler for graceful termination
void handle_signal(int sig) {
    printf("Received signal %d, terminating...\n", sig);
    exit(EXIT_SUCCESS);
