    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        exit(EXIT_FAILURE);
    }
    if (pid > 0) {
        exit(EXIT_SUCCESS); // Parent exits
    }

    // Child process continues
    if (setsid() < 0) {
        perror("setsid");
        exit(EXIT_FAILURE);
    }

    // Redirect standard file descriptors
    int fd = open("/dev/null", O_RDWR);
    if (fd < 0) {
        perror("open /dev/null");
        exit(EXIT_FAILURE);
    }
    if (dup2(fd, STDIN_FILENO) < 0 || dup2(fd, STDOUT_FILENO) < 0 || dup2(fd, STDERR_FILENO) < 0) {
        perror("dup2");
        exit(EXIT_FAILURE);
    }
    if (close(fd) < 0) {
        perror("close");
        exit(EXIT_FAILURE);
    }
}

// Function to get CPU usage (in %)
double get_cpu_usage() {
    struct rusage rusage;
    if (getrusage(RUSAGE_SELF, &rusage) < 0) {
        perror("getrusage");
        return -1.0;
    }
    return (double)rusage.ru_utime.tv_sec + (double)rusage.ru_utime.tv_usec / 1e6 +
           (double)rusage.ru_stime.tv_sec + (double)rusage.ru_stime.tv_usec / 1e6;
}

// Function to get memory usage (in MB)
double get_memory_usage() {
    FILE *fp = fopen("/proc/meminfo", "r");
    if (!fp) {
        perror("fopen /proc/meminfo");
        return -1.0;
    }

    double total = 0.0, free = 0.0;
    char line[128];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "MemTotal:", 9) == 0) {
            total = atof(line + 9);
        } else if (strncmp(line, "MemFree:", 8) == 0) {
            free = atof(line + 8);
        }
    }
    fclose(fp);
    return (total - free) / 1024.0; // Convert KiB to MiB
}

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        printf("Shutting down daemon...\n");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    // Daemonize the process
    daemonize();

    // Set up signal handlers
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Main monitoring loop
    while (1) {
        double cpu_usage = get_cpu_usage();
        double memory_usage = get_memory_usage();

        if (cpu_usage >= 0 && memory_usage >= 0) {
            FILE *log = fopen(LOG_FILE, "a");
            if (log) {
                fprintf(log, "[%ld] CPU: %.2f%% | Memory: %.2f MB\n", time(NULL), cpu_usage, memory_usage);
                fclose(log);
            }
        }

        // Sleep for the interval
        sleep(INTERVAL);
    }

    return 0;
}
