```go
package main

import (
	"bufio"
	"fmt"
	"log"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/shirou/gopsutil/cpu"
	"github.com/shirou/gopsutil/disk"
	"github.com/shirou/gopsutil/mem"
	"github.com/shirou/gopsutil/net"
)

// Daemonize the process
func daemonize() {
	// Fork once
	pid, err := os.Fork()
	if err != nil {
		log.Fatal("Fork failed:", err)
	}
	if pid > 0 {
		// Parent process exits
		os.Exit(0)
	}

	// Fork again
	pid, err = os.Fork()
	if err != nil {
		log.Fatal("Second fork failed:", err)
	}
	if pid > 0 {
		// Child process exits
		os.Exit(0)
	}

	// Detach from terminal
	os.Setpgid(0, 0)

	// Redirect stdin, stdout, stderr to /dev/null
	f, err := os.Open("/dev/null")
	if err != nil {
		log.Fatal("Failed to open /dev/null:", err)
	}
	os.Stdin = f
	os.Stdout = f
	os.Stderr = f
}

// Monitor system resources
func monitorResources() {
	for {
		// CPU usage
		cpuPercent, _ := cpu.Percent(0, false)
		fmt.Printf("CPU Usage: %.2f%%\n", cpuPercent[0])

		// Memory usage
		memInfo, _ := mem.VirtualMemory()
		fmt.Printf("Memory Usage: %.2f%% (%d MB)\n", memInfo.UsedPercent, memInfo.Used/1024/1024)

		// Disk usage (root partition)
		diskUsage, _ := disk.Usage("/")
		fmt.Printf("Disk Usage: %.2f%% (%d GB)\n", diskUsage.UsedPercent, diskUsage.Used/1024/1024/1024)

		// Network stats
		netStats, _ := net.IOCounters(true)
		for _, stat := range netStats {
			fmt.Printf("Network: %s - RX: %d bytes, TX: %d bytes\n", stat.Name, stat.BytesRecv, stat.BytesSent)
		}

		time.Sleep(5 * time.Second)
	}
}

func main() {
	// Daemonize the process
	daemonize()

	// Handle shutdown signals
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	// Start resource monitoring
	go monitorResources()

	// Wait for shutdown signal
	fmt.Println("System daemon started. Press Ctrl+C to exit.")
	<-sigChan
	fmt.Println("Shutting down system daemon...")
}
```

