    printf("Received signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

// Monitor CPU usage
void* monitor_cpu(void* arg) {
    struct rusage rusage;
    while (1) {
        getrusage(RUSAGE_SELF, &rusage);
        printf("CPU Usage: %ld.%06ld seconds\n", rusage.ru_utime.tv_sec, rusage.ru_utime.tv_usec);
        sleep(1); // Adjust interval as needed
    }
    return NULL;
}

// Monitor memory usage
void* monitor_memory(void* arg) {
    struct mallinfo meminfo = mallinfo();
    while (1) {
        printf("Memory Allocated: %d bytes\n", meminfo.uordblks);
        sleep(1);
    }
    return NULL;
}

// Monitor load average
void* monitor_load(void* arg) {
    double load[3];
    while (1) {
        getloadavg(load, 3);
        printf("Load Average: %.2f, %.2f, %.2f\n", load[0], load[1], load[2]);
        sleep(1);
    }
    return NULL;
}

int main() {
    // Set up signal handling
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    // Daemonize the process
    daemonize();

    printf("OS Resource Monitor Daemon Started\n");

    // Create threads for monitoring
    pthread_t cpu_thread, memory_thread, load_thread;
    pthread_create(&cpu_thread, NULL, monitor_cpu, NULL);
    pthread_create(&memory_thread, NULL, monitor_memory, NULL);
    pthread_create(&load_thread, NULL, monitor_load, NULL);

    // Wait for threads to finish (they run indefinitely)
    pthread_join(cpu_thread, NULL);
    pthread_join(memory_thread, NULL);
    pthread_join(load_thread, NULL);

    return 0;
}
