        if (strncmp(line, "MemTotal:", 9) == 0) {
            sscanf(line, "MemTotal: %ld kB", &total_memory);
        } else if (strncmp(line, "MemFree:", 8) == 0) {
            sscanf(line, "MemFree: %ld kB", &free_memory);
        }
    }

    used_memory = total_memory - free_memory;
    printf("Memory: Total=%ld KB | Free=%ld KB | Used=%ld KB\n", total_memory, free_memory, used_memory);
    fclose(fp);
}

// Function to read CPU usage from /proc/stat
void read_cpu_usage() {
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen /proc/stat");
        return;
    }

    char line[256];
    long user, nice, system, idle, iowait, irq, softirq, total;

    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "cpu ", 4) == 0) {
            sscanf(line, "cpu %ld %ld %ld %ld %ld %ld %ld %ld",
                   &user, &nice, &system, &idle, &iowait, &irq, &softirq, &total);
            break;
        }
    }

    long total_time = user + nice + system + idle + iowait + irq + softirq;
    long idle_time = idle + iowait;
    double cpu_usage = ((double)(total_time - idle_time) / total_time) * 100;
    printf("CPU Usage: %.2f%%\n", cpu_usage);
    fclose(fp);
}

// Function to read disk usage (e.g., root filesystem)
void read_disk_usage() {
    struct statvfs fs;
    if (statvfs("/", &fs) < 0) {
        perror("statvfs");
        return;
    }

    double total = (double)fs.f_blocks * fs.f_frsize;
    double free = (double)fs.f_bfree * fs.f_frsize;
    double used = total - free;
    double used_percent = (used / total) * 100;

    printf("Disk Usage: Total=%.2f GB | Free=%.2f GB | Used=%.2f%%\n", 
           total / 1e9, free / 1e9, used_percent);
}

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    printf("\nReceived signal %d. Exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    // Daemonize the process
    daemonize();

    // Set up signal handler
    signal(SIGTERM, handle_signal);
    signal(SIGINT, handle_signal);

    printf("System Resource Monitor Daemon started.\n");

    while (1) {
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        printf("[%02d:%02d:%02d] Collecting system metrics...\n", 
               tm_now->tm_hour, tm_now->tm_min, tm_now->tm_sec);

        read_memory_info();
        read_cpu_usage();
        read_disk_usage();

        // Sleep for 5 seconds
        sleep(5);
    }

    return 0;
}
```

