    if (setsid() < 0) exit(EXIT_FAILURE); // Detach from terminal
    if (chdir("/") < 0) exit(EXIT_FAILURE); // Change to root directory
    fclose(stdin);
    fclose(stdout);
    fclose(stderr);
    open("/dev/null", O_RDWR); // Redirect stdin/stdout to /dev/null
    dup2(0, 1); // stdout
    dup2(0, 2); // stderr
}

// Monitor resource usage
void monitor_resources() {
    struct rusage usage;
    struct timespec ts = {0, 500000000}; // 0.5 seconds

    while (1) {
        if (getrusage(RUSAGE_SELF, &usage) < 0) {
            perror("getrusage");
            exit(EXIT_FAILURE);
        }

        // Print CPU and memory usage
        printf("CPU Time: %.2f sec | Memory: %ld KB\n",
               (usage.ru_utime.tv_sec + usage.ru_stime.tv_sec),
               usage.ru_maxrss);

        nanosleep(&ts, NULL); // Avoid busy-waiting
    }
}

int main() {
    daemonize(); // Start as a daemon
    monitor_resources(); // Begin monitoring
    return 0;
}
