```rust
use std::time::{Duration, SystemTime};
use std::thread;
use std::fs::File;
use std::io::Write;
use nix::sys::wait::WaitId;
use nix::unistd::{fork, setsid, close};
use nix::sys::stat::fstat;
use nix::sys::stat::Stat;
use nix::sys::stat::StatFs;
use nix::sys::resource::{getrusage, RUSAGE_SELF, ResourceUsage};
use nix::sys::wait::waitpid;
use nix::unistd::getpid;
use daemonize::Daemonize;

fn main() {
    // Daemonize the process
    let daemonize = Daemonize::new()
        .pid_file("/var/run/os_monitor.pid")
        .user("nobody")
        .group("nogroup")
        .working_directory("/var/log")
        .start()
        .expect("Failed to daemonize");

    // Main monitoring loop
    loop {
        // Monitor CPU usage
        let usage = getrusage(RUSAGE_SELF).expect("Failed to get CPU usage");
        let cpu_usage = usage.ru_utime + usage.ru_stime;

        // Monitor memory usage
        let mut stat = Stat::new().expect("Failed to get memory stats");
        let mem_usage = stat.st_size;

        // Monitor disk usage
        let mut statfs = StatFs::new("/").expect("Failed to get disk stats");
        let disk_usage = statfs.f_blocks as f64 * statfs.f_frsize as f64;

        // Log resource data
        let log_entry = format!(
            "[{}] CPU: {:.2}%, Mem: {:.2}%, Disk: {:.2}%\n",
            SystemTime::now().duration_since(SystemTime::UNIX_EPOCH)
                .unwrap()
                .as_secs(),
            (cpu_usage.as_nanos() as f64 / 1_000_000_000.0) * 100.0,
            (mem_usage as f64 / 1_000_000.0) * 100.0,
            (disk_usage / 1_000_000_000.0) * 100.0
        );

        let mut file = File::create("os_monitor.log").expect("Failed to open log file");
        file.write_all(log_entry.as_bytes()).expect("Failed to write to log file");

        // Sleep for 5 seconds
        thread::sleep(Duration::from_secs(5));
    }
}
```

