Here's a performance-optimized C++ implementation for a network flow analyzer, designed for gigabit-scale traffic. This example uses `libpcap` for packet capture, `std::unordered_map` for flow tracking, and thread-safe concurrency via `std::mutex`.

---

### 🚀 **C++ Network Flow Analyzer (Gigabit-Scale)**
```cpp
#include <iostream>
#include <pcap.h>
#include <unordered_map>
#include <mutex>
#include <thread>
#include <atomic>
#include <chrono>
#include <iomanip>
#include <sstream>

// Flow definition (5-tuple)
struct Flow {
    std::string src_ip, dst_ip;
    uint16_t src_port, dst_port;
    uint32_t bytes, packets;
    std::chrono::steady_clock::time_point start_time;
};

// Global flow map (thread-safe)
std::unordered_map<std::string, Flow> flow_map;
std::mutex flow_mutex;
std::atomic<bool> running{true};

// Packet callback function
void packet_handler(u_char* user, const struct pcap_pkthdr* header, const u_char* packet) {
    if (!running) return;

    // Extract Ethernet header
    const struct ethhdr* eth = (struct ethhdr*)packet;
    if (ntohs(eth->h_proto) != ETH_P_IP) return; // Skip non-IP packets

    // Extract IP header
    const struct ip* ip = (struct ip*)(packet + sizeof(struct ethhdr));
    if (ip->ip_v != 4) return; // Only IPv4

    // Extract TCP/UDP header
    const void* transport = (void*)(packet + sizeof(struct ethhdr) + (ip->ip_hl * 4));
    uint16_t protocol = (ip->ip_p);
    uint16_t src_port, dst_port;
    uint32_t src_ip, dst_ip;

    // Parse IP addresses
    src_ip = ntohl(ip->ip_src.s_addr);
    dst_ip = ntohl(ip->ip_dst.s_addr);

    // Parse ports based on protocol
    if (protocol == IPPROTO_TCP) {
        const struct tcphdr* tcp = (struct tcphdr*)transport;
        src_port = ntohs(tcp->th_sport);
        dst_port = ntohs(tcp->th_dport);
    } else if (protocol == IPPROTO_UDP) {
        const struct udphdr* udp = (struct udphdr*)transport;
        src_port = ntohs(udp->uh_sport);
        dst_port = ntohs(udp->uh_dport);
    } else {
        return; // Unsupported protocol
    }

    // Key for flow map (src_ip:src_port -> dst_ip:dst_port)
    std::string key = std::to_string(src_ip) + ":" + std::to_string(src_port) + ":" + std::to_string(dst_ip) + ":" + std::to_string(dst_port);

    std::lock_guard<std::mutex> lock(flow_mutex);
    auto& flow = flow_map[key];

    // Update flow statistics
    flow.packets++;
    flow.bytes += header->len;

    // Initialize flow if not exists
    if (flow.start_time == std::chrono::steady_clock::time_point{}) {
        flow.start_time = std::chrono::steady_clock::now();
    }
}

// Main function
int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>" << std::endl;
        return 1;
    }

    // Initialize libpcap
    pcap_t* handle = pcap_open_live(argv[1], 65536, 1, 1000, nullptr);
    if (!handle) {
        std::cerr << "Error opening device " << argv[1] << std::endl;
