        pcap_loop(handle, 0, packet_handler, nullptr);
    });

    // Periodic flow reporting (e.g., every 10 seconds)
    std::chrono::steady_clock::time_point last_report = std::chrono::steady_clock::now();
    while (running) {
        std::this_thread::sleep_for(std::chrono::seconds(10));
        std::lock_guard<std::mutex> lock(flow_mutex);
        for (auto& [key, flow] : flow_map) {
            auto now = std::chrono::steady_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::seconds>(now - flow.start_time).count();
            std::cout << "Flow: " << key
                      << " | Duration: " << duration << "s"
                      << " | Packets: " << flow.packets
                      << " | Bytes: " << flow.bytes << std::endl;
        }
        last_report = now;
    }

    // Stop capture and join threads
    running = false;
    capture_thread.join();
    pcap_close(handle);
    return 0;
}
