// Flow key (5-tuple)
struct FlowKey {
    uint32_t src_ip;
    uint16_t src_port;
    uint32_t dst_ip;
    uint16_t dst_port;
    uint8_t protocol;

    bool operator==(const FlowKey& other) const {
        return src_ip == other.src_ip &&
               src_port == other.src_port &&
               dst_ip == other.dst_ip &&
               dst_port == other.dst_port &&
               protocol == other.protocol;
    }
};

// Custom hash for FlowKey
struct FlowKeyHash {
    std::size_t operator()(const FlowKey& key) const {
        std::size_t h = 0;
        h ^= key.src_ip + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= key.src_port + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= key.dst_ip + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= key.dst_port + 0x9e3779b9 + (h << 6) + (h >> 2);
        h ^= key.protocol + 0x9e3779b9 + (h << 6) + (h >> 2);
        return h;
    }
};

// Flow statistics
struct FlowStats {
    uint64_t bytes;
    uint64_t packets;
    std::chrono::steady_clock::time_point start_time;
};

// Global flow table (thread-safe)
std::unordered_map<FlowKey, FlowStats, FlowKeyHash> flow_table;
std::mutex flow_mutex;
std::atomic<bool> running{true};

// Packet processing thread
void process_packets(pcap_t* handle) {
    while (running) {
        struct pcap_pkthdr* header;
        const u_char* packet;
        if (pcap_next_ex(handle, &header, &packet) == 0) continue;

        // Extract Ethernet header
        const struct ethhdr* eth = (const struct ethhdr*)packet;
        if (ntohs(eth->h_proto) != ETHERTYPE_IP) continue; // Skip non-IP packets

        // Extract IP header
        const struct ip* ip = (const struct ip*)(packet + sizeof(struct ethhdr));
        uint32_t src_ip = ntohl(ip->ip_src.s_addr);
        uint32_t dst_ip = ntohl(ip->ip_dst.s_addr);
        uint8_t protocol = ip->ip_p;

        // Extract TCP/UDP header
        const void* transport_header = (const void*)(packet + sizeof(struct ethhdr) + sizeof(struct ip));
        uint16_t src_port, dst_port;
        if (protocol == IPPROTO_TCP) {
            const struct tcphdr* tcp = (const struct tcphdr*)transport_header;
            src_port = ntohs(tcp->th_sport);
            dst_port = ntohs(tcp->th_dport);
        } else if (protocol == IPPROTO_UDP) {
            const struct udphdr* udp = (const struct udphdr*)transport_header;
            src_port = ntohs(udp->uh_sport);
            dst_port = ntohs(udp->uh_dport);
        } else {
            continue; // Skip unsupported protocols
        }

        // Update flow statistics
        FlowKey key = {src_ip, src_port, dst_ip, dst_port, protocol};
        {
            std::lock_guard<std::mutex> lock(flow_mutex);
            auto& flow = flow_table[key];
            flow.bytes += header->len;
            flow.packets++;
            flow.start_time = std::chrono::steady_clock::now();
        }
    }
}

int main(int argc, char* argv[]) {
    if (argc != 2) {
        std::cerr << "Usage: " << argv[0] << " <interface>" << std::endl;
        return 1;
    }

    // Open live capture device
    pcap_t* handle = pcap_open_live(argv[1], 65536, 1, 1000, nullptr);
    if (!handle) {
        std::cerr << "Error opening device: " << pcap_geterr(handle) << std::endl;
        return 1;
    }

    // Start packet processing thread
    std::thread capture_thread(process_packets, handle);

    // Main thread (for user interaction or logging)
    std::cout << "Monitoring network traffic on " << argv[1] << std::endl;
    std::cout << "Use Ctrl+C to stop." << std::endl;

    // Wait for user input or signal
    try {
        std::cin.get();
    } catch (std::exception&) {
        running = false;
    }

    capture_thread.join();
    pcap_close(handle);

    // Output flow statistics
    std::cout << "\nFlow statistics:" << std::endl;
    for (const auto& [key, stats] : flow_table) {
        std::cout << "Flow: " << inet_ntoa(*(struct in_addr*)&key.src_ip)
