                flows[i].proto == proto) {
                flow_idx = i;
                break;
            }
        }
        if (flow_idx == -1) {
            if (flow_count < MAX_FLOWS) {
                flows[flow_count].src_ip = src_ip;
                flows[flow_count].dst_ip = dst_ip;
                flows[flow_count].src_port = src_port;
                flows[flow_count].dst_port = dst_port;
                flows[flow_count].proto = proto;
                flows[flow_count].packets = 1;
                flow_count++;
            }
        } else {
            flows[flow_idx].packets++;
        }
    } else if (proto == IPPROTO_UDP && payload_len >= sizeof(struct udphdr)) {
        udp_header = (struct udphdr *)(payload);
        uint16_t src_port = ntohs(udp_header->uh_sport);
        uint16_t dst_port = ntohs(udp_header->uh_dport);
        // Aggregate flow
        int flow_idx = -1;
        for (int i = 0; i < flow_count; i++) {
            if (flows[i].src_ip == src_ip && flows[i].dst_ip == dst_ip &&
                flows[i].src_port == src_port && flows[i].dst_port == dst_port &&
                flows[i].proto == proto) {
                flow_idx = i;
                break;
            }
        }
        if (flow_idx == -1) {
            if (flow_count < MAX_FLOWS) {
                flows[flow_count].src_ip = src_ip;
                flows[flow_count].dst_ip = dst_ip;
                flows[flow_count].src_port = src_port;
                flows[flow_count].dst_port = dst_port;
                flows[flow_count].proto = proto;
                flows[flow_count].packets = 1;
                flow_count++;
            }
        } else {
            flows[flow_idx].packets++;
        }
    }
}

void print_flows() {
    printf("\nFlow Statistics:\n");
    for (int i = 0; i < flow_count; i++) {
        char src_ip[INET_ADDR_LEN];
        char dst_ip[INET_ADDR_LEN];
        inet_ntop(AF_INET, &flows[i].src_ip, src_ip, INET_ADDR_LEN);
        inet_ntop(AF_INET, &flows[i].dst_ip, dst_ip, INET_ADDR_LEN);
        printf("Flow: %s:%d -> %s:%d | Packets: %lu\n",
               src_ip, ntohs(flows[i].src_port),
               dst_ip, ntohs(flows[i].dst_port),
               flows[i].packets);
    }
}

void signal_handler(int sig) {
    print_flows();
    exit(0);
}

int main(int argc, char *argv[]) {
    char *dev = "eth0"; // Adjust interface as needed
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct bpf_program fp;
    char filter_exp[] = "tcp or udp"; // Filter for TCP/UDP flows
    int optim = 1;

    // Open device for live capture
    handle = pcap_open_live(dev, MAX_PACKET_SIZE, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return -1;
    }

    // Compile filter
    if (pcap_compile(handle, &fp, filter_exp, optim, PCAP_NETMASK_DEFAULT) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return -1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't set filter: %s\n", pcap_geterr(handle));
        return -1;
    }

    // Set buffer size for high throughput
    if (pcap_set_buffer_size(handle, 1024 * 1024 * 10) == -1) {
        fprintf(stderr, "Couldn't set buffer size: %s\n", pcap_geterr(handle));
        return -1;
    }

    // Handle signals for graceful exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Start packet capture
    pcap_loop(handle, 0, packet_handler, NULL);

    pcap_close(handle);
    return 0;
}
