    const struct ether_header* eth_header = (const struct ether_header*)packet;
    if (ntohs(eth_header->ether_type) != ETHERTYPE_IP) return; // Skip non-IP packets

    const struct ip_header* ip_header = (const struct ip_header*)(packet + sizeof(ether_header));
    uint8_t ip_version = (ip_header->ip_vhl >> 4) & 0x0F;
    if (ip_version != 4) return; // Skip non-IPv4 packets

    uint16_t ip_protocol = ip_header->ip_protocol;

    // Calculate offset to TCP/UDP header
    size_t ip_header_len = (ip_header->ip_vhl & 0x0F) * 4;
    const uint8_t* tcp_udp_start = packet + sizeof(ether_header) + ip_header_len;

    if (ip_protocol == IPPROTO_TCP) {
        const struct tcp_header* tcp_header = (const struct tcp_header*)tcp_udp_start;
        uint16_t source_port = ntohs(tcp_header->th_sport);
        uint16_t destination_port = ntohs(tcp_header->th_dport);

        std::ostringstream key;
        key << std::hex << ip_header->ip_src << ":" << ip_header->ip_dst << ":" << source_port << ":" << destination_port << ":" << ip_protocol;
        flow_map[key.str()]++;
    } else if (ip_protocol == IPPROTO_UDP) {
        const struct udp_header* udp_header = (const struct udp_header*)tcp_udp_start;
        uint16_t source_port = ntohs(udp_header->uh_sport);
        uint16_t destination_port = ntohs(udp_header->uh_dport);

        std::ostringstream key;
        key << std::hex << ip_header->ip_src << ":" << ip_header->ip_dst << ":" << source_port << ":" << destination_port << ":" << ip_protocol;
        flow_map[key.str()]++;
    }
}

