```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>
#include <pthread.h>

#define MAX_PACKET_SIZE 65536
#define FLOW_TABLE_SIZE 1024

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint32_t bytes;
    uint64_t packets;
} FlowEntry;

typedef struct {
    FlowEntry entries[FLOW_TABLE_SIZE];
    pthread_mutex_t lock;
} FlowTable;

FlowTable flow_table;
unsigned int flow_count = 0;

// Hash function for IP and port pairs
unsigned int hash_flow(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port, uint16_t dst_port) {
    unsigned int h = 0;
    h ^= (src_ip >> 24) ^ (src_ip >> 16) ^ (src_ip >> 8) ^ src_ip;
    h ^= (dst_ip >> 24) ^ (dst_ip >> 16) ^ (dst_ip >> 8) ^ dst_ip;
    h ^= src_port ^ dst_port;
    return h % FLOW_TABLE_SIZE;
}

// Packet handler
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    const struct ether_header *eth_hdr = (struct ether_header *)packet;
    const struct ip *ip_hdr = (struct ip *)(packet + sizeof(struct ether_header));
    const struct tcphdr *tcp_hdr = NULL;
    const struct udphdr *udp_hdr = NULL;
    uint16_t eth_type = ntohs(eth_hdr->ether_type);

    // Skip non-IP traffic
    if (eth_type != ETHERTYPE_IP) return;

    // Extract IP header
    uint32_t src_ip = ntohl(ip_hdr->ip_src.s_addr);
    uint32_t dst_ip = ntohl(ip_hdr->ip_dst.s_addr);
    uint16_t ip_len = ntohs(ip_hdr->ip_len);
    uint16_t ip_hdr_len = (ip_hdr->ip_hl) * 4;

    // Extract transport layer header
    uint8_t *transport_data = (uint8_t *)ip_hdr + ip_hdr_len;
    if (ip_hdr->ip_p == IPPROTO_TCP) {
        tcp_hdr = (struct tcphdr *)transport_data;
        uint16_t src_port = ntohs(tcp_hdr->th_sport);
        uint16_t dst_port = ntohs(tcp_hdr->th_dport);
        uint16_t payload_len = ntohs(ip_hdr->ip_len) - ip_hdr_len - (tcp_hdr->th_off * 4);
        if (payload_len > 0) {
            // Update flow stats
            pthread_mutex_lock(&flow_table.lock);
            unsigned int h = hash_flow(src_ip, dst_ip, src_port, dst_port);
            FlowEntry *entry = &flow_table.entries[h];
            entry->bytes += payload_len;
            entry->packets++;
            pthread_mutex_unlock(&flow_table.lock);
        }
    } else if (ip_hdr->ip_p == IPPROTO_UDP) {
        udp_hdr = (struct udphdr *)transport_data;
        uint16_t src_port = ntohs(udp_hdr->uh_sport);
        uint16_t dst_port = ntohs(udp_hdr->uh_dport);
        uint16_t payload_len = ntohs(udp_hdr->uh_len) - sizeof(struct udphdr);
        if (payload_len > 0) {
            pthread_mutex_lock(&flow_table.lock);
            unsigned int h = hash_flow(src_ip, dst_ip, src_port, dst_port);
            FlowEntry *entry = &flow_table.entries[h];
            entry->bytes += payload_len;
            entry->packets++;
            pthread_mutex_unlock(&flow_table.lock);
        }
    }
}

int main(int argc, char *argv[]) {
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct bpf_program fp;
    char *dev = "eth0"; // Replace with your interface
    char *filter_exp = "tcp or udp"; // Filter for flow analysis

    // Open live capture
    handle = pcap_open_live(dev, MAX_PACKET_SIZE, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return -1;
    }

    // Compile filter
    if (pcap_compile(handle, &fp, filter_exp, 0, PCAP_NETMASK_DEFAULT) == -1) {
        fprintf(stderr, "Couldn't parse filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return -1;
    }

    if (pcap_setfilter(handle, &fp) == -1) {
        fprintf(stderr, "Couldn't set filter %s: %s\n", filter_exp, pcap_geterr(handle));
        return -1;
    }

    // Initialize flow table
    pthread_mutex_init(&flow_table.lock, NULL);

    // Start packet capture
    pcap_loop(handle, 0, packet_handler, NULL);

    // Cleanup
    pcap_freecode(&fp);
    pcap_close(handle);
    pthread_mutex_destroy(&flow_table.lock);

    return 0;
}
