    uint64_t bytes = 0;
};

void process_packet(u_char* user_data, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    // Ethernet header (14 bytes)
    const struct ether_header* eth_hdr = (const struct ether_header*)packet;
    if (ntohs(eth_hdr->ether_type) != ETHERTYPE_IP) return; // Skip non-IP traffic

    // IP header (20 bytes for IPv4)
    const struct ip* ip_hdr = (const struct ip*)(packet + sizeof(struct ether_header));
    if (ip_hdr->ip_v != 4) return; // Skip non-IPv4 traffic

    // Extract source and destination IPs
    std::string src_ip = inet_ntoa(ip_hdr->ip_src);
    std::string dst_ip = inet_ntoa(ip_hdr->ip_dst);
    uint16_t src_port = 0, dst_port = 0;
    uint8_t protocol = ip_hdr->ip_p;

    // Extract TCP/UDP port numbers
    const uint8_t* payload = (const uint8_t*)(packet + sizeof(struct ether_header) + sizeof(struct ip));
    switch (protocol) {
        case IPPROTO_TCP:
            const struct tcphdr* tcp_hdr = (const struct tcphdr*)payload;
            src_port = ntohs(tcp_hdr->th_sport);
            dst_port = ntohs(tcp_hdr->th_dport);
            break;
        case IPPROTO_UDP:
            const struct udphdr* udp_hdr = (const struct udphdr*)payload;
            src_port = ntohs(udp_hdr->uh_sport);
            dst_port = ntohs(udp_hdr->uh_dport);
            break;
        default:
            return; // Skip unsupported protocols
    }

    // Create a unique flow key
    std::string flow_key = src_ip + ":" + std::to_string(src_port) + ":" + dst_ip + ":" + std::to_string(dst_port) + ":" + std::to_string(protocol);

    // Update flow statistics
    static std::unordered_map<std::string, FlowStats> flow_map;
    auto& flow = flow_map[flow_key];
    flow.packets++;
    flow.bytes += pkthdr->len;

    // Print flow info (for debugging)
    std::cout << "Flow: " << flow_key << " | Packets: " << flow.packets << " | Bytes: " << flow.bytes << std::endl;
}

