#include <unistd.h>

// Define packet header structures
struct ethhdr {
    uint8_t  ether_dhost[6];
    uint8_t  ether_shost[6];
    uint16_t ether_type;
};

struct iphdr {
    uint8_t  ihl:4,
             version:4;
    uint8_t  tos;
    uint16_t tot_len;
    uint16_t id;
    uint16_t frag_off;
    uint8_t  ttl;
    uint8_t  protocol;
    uint16_t check;
    uint32_t saddr;
    uint32_t daddr;
};

struct tcphdr {
    uint16_t source;
    uint16_t dest;
    uint32_t seq;
    uint32_t ack_seq;
    uint16_t res1:4,
             doff:4,
             fin:1,
             syn:1,
             rst:1,
             psh:1,
             ack:1,
             urg:1,
             res2:2;
    uint16_t window;
    uint16_t check;
    uint16_t urg_ptr;
};

// Flow tracking structure
typedef struct {
    uint32_t saddr;
    uint32_t daddr;
    uint16_t sport;
    uint16_t dport;
    uint64_t count;
} Flow;

// Global flow tracking (simplified for minimalism)
#define MAX_FLOWS 1024
Flow flows[MAX_FLOWS];
int flow_count = 0;

// Simple hash function for flow keys
uint32_t flow_hash(uint32_t saddr, uint32_t daddr, uint16_t sport, uint16_t dport) {
    return (saddr ^ daddr) + (sport + dport);
}

// Packet handler
void packet_handler(u_char *args, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    const struct ethhdr *eth = (const struct ethhdr *)packet;
    if (ntohs(eth->ether_type) != ETHERTYPE_IP) return;

    const struct iphdr *ip = (const struct iphdr *)(packet + sizeof(struct ethhdr));
    if (ip->version != 4) return;

    const struct tcphdr *tcp = (const struct tcphdr *)((char *)ip + (ip->ihl * 4));
    if (tcp->protocol != IPPROTO_TCP) return;

    uint32_t saddr = ip->saddr;
    uint32_t daddr = ip->daddr;
    uint16_t sport = ntohs(tcp->source);
    uint16_t dport = ntohs(tcp->dest);

    // Hash and track flow
    uint32_t hash = flow_hash(saddr, daddr, sport, dport);
    int idx = hash % MAX_FLOWS;

    // Simplified flow tracking (no collision handling)
    if (flow_count < MAX_FLOWS && flows[idx].saddr == saddr && flows[idx].daddr == daddr && flows[idx].sport == sport && flows[idx].dport == dport) {
        flows[idx].count++;
    } else {
        if (flow_count < MAX_FLOWS) {
            flows[flow_count].saddr = saddr;
            flows[flow_count].daddr = daddr;
            flows[flow_count].sport = sport;
            flows[flow_count].dport = dport;
            flows[flow_count].count = 1;
            flow_count++;
        }
    }
}

// Main function
int main(int argc, char *argv[]) {
    char *dev = "eth0"; // Interface to capture from
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;

    // Open live capture
    handle = pcap_open_live(dev, 65536, 1, 1000, errbuf);
    if (handle == NULL) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return 2;
    }

    // Set promiscuous mode and start capture
    pcap_set_promisc(handle, 1);
    pcap_loop(handle, 0, packet_handler, NULL);

    // Print flow statistics (simplified)
    printf("\nFlow statistics:\n");
    for (int i = 0; i < flow_count; i++) {
        printf("Flow %d: %s:%d -> %s:%d, Packets: %lu\n",
               i + 1,
               inet_ntoa(*(struct in_addr *)&flows[i].saddr),
               flows[i].sport,
               inet_ntoa(*(struct in_addr *)&flows[i].daddr),
               flows[i].dport,
               flows[i].count);
    }

    pcap_close(handle);
    return 0;
}
