// Flow key: (src_ip, dst_ip, src_port, dst_port, protocol)
struct FlowKey {
    std::string src_ip;
    std::string dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
};

// Flow data: bytes, packets, start time
struct FlowData {
    uint64_t bytes;
    uint64_t packets;
    time_t start_time;
};

// Global flow map (thread-safe)
std::unordered_map<FlowKey, FlowData> flow_map;
std::mutex flow_mutex;

// Packet handler
void packet_handler(u_char* user_data, const struct pcap_pkthdr* pkthdr, const u_char* packet) {
    // Extract Ethernet header
    const struct ethhdr* eth = (struct ethhdr*)packet;
    if (ntohs(eth->h_proto) != ETH_P_IP) return; // Only process IPv4

    // Extract IP header
    const struct ip* ip = (struct ip*)(packet + sizeof(struct ethhdr));
    uint32_t src_ip = ntohl(ip->ip_src.s_addr);
    uint32_t dst_ip = ntohl(ip->ip_dst.s_addr);
    uint8_t protocol = ip->ip_p;

    // Extract TCP/UDP header
    const void* tcpudp = (void*)(packet + sizeof(struct ethhdr) + sizeof(struct ip));
    uint16_t src_port, dst_port;

    if (protocol == IPPROTO_TCP) {
        const struct tcphdr* tcp = (struct tcphdr*)tcpudp;
        src_port = ntohs(tcp->th_sport);
        dst_port = ntohs(tcp->th_dport);
