Here’s a minimal working example of a **performance-critical network flow analyzer** in **C**, optimized for gigabit-scale traffic. This code uses `libpcap` for packet capture, parses Ethernet/IP/TCP/UDP headers, and tracks basic flow information (5-tuple: source IP, destination IP, source port, destination port, protocol). It prioritizes speed and low overhead, suitable for embedded systems or high-performance servers.

---

### 🧠 Key Design Choices:
1. **C**: For raw performance and low-level control.
2. **libpcap**: Efficient packet capture with minimal overhead.
3. **Zero-copy parsing**: Directly access packet buffers to avoid data copying.
4. **Simple flow tracking**: Store flow data in a hash table for quick lookup (expandable).
5. **Non-blocking I/O**: Use `pcap_set_immediate_mode` for real-time processing.

---

### 📜 Code: `network_flow_analyzer.c`
```c
#include <pcap.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>
#include <netinet/udp.h>
#include <arpa/inet.h>

#define MAX_PACKET_SIZE 65536
#define FLOW_TABLE_SIZE 1024

typedef struct {
    uint32_t src_ip;
    uint32_t dst_ip;
    uint16_t src_port;
    uint16_t dst_port;
    uint8_t protocol;
    uint64_t packets;
} FlowEntry;

FlowEntry flow_table[FLOW_TABLE_SIZE];
int flow_table_index = 0;

// Hash function for flow table
unsigned int hash_flow(uint32_t src_ip, uint32_t dst_ip, uint16_t src_port, uint16_t dst_port, uint8_t protocol) {
    unsigned int hash = 0;
    hash = (hash * 31) + src_ip;
    hash = (hash * 31) + dst_ip;
    hash = (hash * 31) + src_port;
    hash = (hash * 31) + dst_port;
    hash = (hash * 31) + protocol;
    return hash % FLOW_TABLE_SIZE;
}

// Packet callback function
void packet_handler(u_char *user_data, const struct pcap_pkthdr *pkthdr, const u_char *packet) {
    const struct ethhdr *eth = (struct ethhdr *)packet;
    const struct iphdr *ip = (struct iphdr *)(packet + sizeof(struct ethhdr));
    const struct tcphdr *tcp = NULL;
    const struct udphdr *udp = NULL;

    // Check if packet is IPv4
    if (ntohs(eth->h_proto) == ETH_P_IP) {
        // Parse IP header
        if (ip->ihl < 5) return; // Invalid IP header

        // Check protocol (TCP/UDP)
        switch (ip->protocol) {
            case IPPROTO_TCP:
                tcp = (struct tcphdr *)(packet + sizeof(struct ethhdr) + (ip->ihl * 4));
                break;
            case IPPROTO_UDP:
                udp = (struct udphdr *)(packet + sizeof(struct ethhdr) + (ip->ihl * 4));
                break;
            default:
                return;
        }

        // Extract flow information
        uint32_t src_ip = ip->saddr;
        uint32_t dst_ip = ip->daddr;
        uint16_t src_port = (tcp ? tcp->source : udp->source);
        uint16_t dst_port = (tcp ? tcp->dest : udp->dest);
        uint8_t protocol = ip->protocol;

        // Hash and update flow table
        unsigned int index = hash_flow(src_ip, dst_ip, src_port, dst_port, protocol);
        FlowEntry *entry = &flow_table[index];

        // Simple flow tracking (count packets)
        entry->packets++;

        // Print flow details
        printf("Flow: %s -> %s | %d:%d | Protocol: %d | Packets: %lu\n",
               inet_ntoa(*(struct in_addr *)&src_ip),
               inet_ntoa(*(struct in_addr *)&dst_ip),
               ntohs(src_port), ntohs(dst_port),
               protocol, entry->packets);
    }
}

int main(int argc, char *argv[]) {
    char *dev = "eth0"; // Network interface
    char errbuf[PCAP_ERRBUF_SIZE];
    pcap_t *handle;
    struct pcap_pkthdr header;
    const u_char *packet;

    // Open device
    handle = pcap_open_live(dev, MAX_PACKET_SIZE, 1, 1000, errbuf);
    if (!handle) {
        fprintf(stderr, "Couldn't open device %s: %s\n", dev, errbuf);
        return -1;
    }

    // Set immediate mode for real-time processing
    pcap_set_immediate_mode(handle, 1);

    // Start packet capture
    pcap_loop(handle, 0, packet_handler, NULL);

    pcap_close(handle);
    return 0;
}
```

