    // Store in circular buffer
    sum -= sensorValues[sampleIndex]; // Subtract old value
    sensorValues[sampleIndex++] = rawValue; // Add new value
    sum += rawValue;

    // Reset index if buffer is full
    if (sampleIndex >= SAMPLE_COUNT) {
        sampleIndex = 0;
    }

    // Calculate averaged temperature (LM35: 10mV/°C)
    float voltage = (sum / SAMPLE_COUNT) * (5.0 / 1023.0); // Convert to volts
    averagedTemp = voltage / 0.01; // Convert to °C

    // Output result
