#include <Eigen/Dense>  // For linear algebra (Kalman filter)

// Simulated sensor data
struct SensorData {
    Eigen::Vector3d imu_accel;  // Accelerometer (m/s²)
    Eigen::Vector3d imu_gyro;   // Gyroscope (rad/s)
    double encoder_pos;         // Encoder position (radians)
};

// Kalman Filter for sensor fusion
class KalmanFilter {
public:
    Eigen::Vector3d state;      // Estimated state (position, velocity, orientation)
    Eigen::MatrixXd P;          // Error covariance
    Eigen::MatrixXd Q;          // Process noise covariance
    Eigen::MatrixXd R;          // Measurement noise covariance
    Eigen::MatrixXd H;          // Measurement matrix

    KalmanFilter() {
        // Initialize state and covariance
        state = Eigen::Vector3d::Zero();
        P = Eigen::MatrixXd::Identity(3, 3) * 1.0;
        Q = Eigen::MatrixXd::Identity(3, 3) * 0.01;
        R = Eigen::MatrixXd::Identity(3, 3) * 0.1;
        H = Eigen::MatrixXd::Identity(3, 3);
    }

    Eigen::Vector3d update(const SensorData& data) {
        // Predict step
        state += (data.imu_gyro * 0.01);  // Simple integration for orientation
        P += Q;

        // Update step
        Eigen::Vector3d z = data.imu_accel;  // Measurement
        Eigen::VectorXd y = z - H * state;   // Innovation
        Eigen::MatrixXd S = H * P * H.transpose() + R;
        Eigen::MatrixXd K = P * H.transpose() * S.inverse();
        state += K * y;
        P = (Eigen::MatrixXd::Identity(3, 3) - K * H) * P;

        return state;
    }
};

// PID Controller for motor control
class PIDController {
public:
    double Kp, Ki, Kd;
    double prev_error;
    double integral;

    PIDController(double Kp, double Ki, double Kd) : Kp(Kp), Ki(Ki), Kd(Kd), prev_error(0), integral(0) {}

    double compute(double setpoint, double measured, double dt) {
        double error = setpoint - measured;
        integral += error * dt;
        double derivative = (error - prev_error) / dt;

        double output = Kp * error + Ki * integral + Kd * derivative;
        prev_error = error;
        return output;
    }
};

