    static double imu_angle = 0.0;
    static double encoder_pos = 0.0;
    static double dt = 0.01; // 100ms update interval

    // Simulate sensor drift and noise
    imu_angle += 0.1 * dt; // Simulated angular velocity
    encoder_pos += 0.5 * dt; // Simulated encoder movement

    return {imu_angle, encoder_pos};
}

// Simple sensor fusion (e.g., averaging for demonstration)
SensorData fuse_sensors(const std::vector<SensorData>& inputs) {
    double sum_angle = 0.0, sum_pos = 0.0;
    for (const auto& data : inputs) {
        sum_angle += data.imu_angle;
        sum_pos += data.encoder_pos;
    }
    return {sum_angle / inputs.size(), sum_pos / inputs.size()};
}

// Basic PID controller for motor control
MotorCommand control_loop(const SensorData& fused_data) {
    static double prev_error = 0.0;
    static double integral = 0.0;
    double Kp = 1.0, Ki = 0.1, Kd = 0.05;
    double error = 0.0; // Example: target angle is 0

    // Simulate error (e.g., angle deviation from target)
    error = -fused_data.imu_angle; // Assume target is 0

    integral += error;
    double derivative = error - prev_error;

    double output = Kp * error + Ki * integral + Kd * derivative;
    prev_error = error;

    // Convert control output to motor speeds
    return {output, -output}; // Simple differential drive
}

// Main control loop with real-time timing
void run_control_loop() {
    const double loop_rate = 100.0; // Hz
    const auto period = std::chrono::milliseconds(static_cast<int>(1000.0 / loop_rate));

    while (true) {
        auto start = std::chrono::high_resolution_clock::now();

        // 1. Sensor fusion
        std::vector<SensorData> sensor_inputs = {get_sensor_data()};
        SensorData fused_data = fuse_sensors(sensor_inputs);

