#include <stdio.h>
#include <stdint.h>
#include <math.h>

// Configuration
#define SAMPLE_RATE 100  // Hz
#define BUFFER_SIZE 100  // Size of moving average buffer
#define THRESHOLD 2.0    // Anomaly detection threshold (adjust based on sensor specs)

// Simulated accelerometer data (replace with real hardware read)
float get_accelerometer_data() {
    // Simulate random data (replace with actual sensor read)
    return (float)(rand() % 1000) / 100.0 - 5.0; // Range: -5.0 to +5.0
}

// Moving average filter
float moving_average(float *buffer, int size, float new_sample) {
    static float sum = 0.0;
    sum -= buffer[0]; // Remove oldest sample
    for (int i = 0; i < size - 1; i++) {
        buffer[i] = buffer[i + 1]; // Shift buffer
    }
    buffer[size - 1] = new_sample;
    sum += new_sample;
    return sum / size;
}

// Anomaly detection
int detect_anomaly(float current_value, float avg) {
    // Simple threshold-based detection
    return (fabs(current_value - avg) > THRESHOLD);
}

int main() {
    float buffer[BUFFER_SIZE] = {0};
    float avg = 0.0;
    int anomaly_count = 0;

    printf("Accelerometer Anomaly Detection Pipeline\n");

    while (1) {
        // Step 1: Acquire raw data
        float raw_data = get_accelerometer_data();
        printf("Raw Data: %.2f\n", raw_data);

        // Step 2: Apply moving average filter
        avg = moving_average(buffer, BUFFER_SIZE, raw_data);

        // Step 3: Detect anomalies
        if (detect_anomaly(raw_data, avg)) {
            printf("Anomaly Detected! Value: %.2f, Average: %.2f\n", raw_data, avg);
            anomaly_count++;
        } else {
            printf("Normal Data. Value: %.2f, Average: %.2f\n", raw_data, avg);
        }

        // Step 4: Optional: Log or trigger action
        if (anomaly_count > 5) {
            printf("Critical Anomaly: Triggering alert or shutdown...\n");
            // Replace with hardware alert, logging, or system reset
            break;
        }

        // Simulate real-time delay
        for (volatile int i = 0; i < 100000; i++); // Simple delay
    }

    return 0;
}
