bool detectAnomaly(const std::vector<double>& window) {
    double mean = 0.0, variance = 0.0;

    // Calculate mean
    for (double val : window) {
        mean += val;
    }
    mean /= window.size();

    // Calculate variance
    for (double val : window) {
        variance += std::pow(val - mean, 2);
    }
    variance /= window.size();

    // Check for anomalies
    for (double val : window) {
        double zScore = std::abs(val - mean) / std::sqrt(variance);
        if (zScore > THRESHOLD) {
            return true;
        }
    }
    return false;
}

