#include <iostream>
#include <vector>
#include <cmath>
#include <deque>

// Constants
const int BUFFER_SIZE = 100;  // Number of samples for moving average
const double THRESHOLD = 3.0; // Z-score threshold for anomaly detection

// Simulated accelerometer data stream
double read_accelerometer() {
    // In a real system, this would interface with hardware
    static int count = 0;
    return sin(0.1 * count++) + (rand() % 100) / 100.0; // Simulate noise
}

// Process data and detect anomalies
bool detect_anomaly(const std::vector<double>& data) {
    if (data.size() < BUFFER_SIZE) return false; // Not enough data

    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        sum += data[i];
    }
    double mean = sum / BUFFER_SIZE;

    double sum_squares = 0.0;
    for (int i = 0; i < BUFFER_SIZE; ++i) {
        sum_squares += std::pow(data[i] - mean, 2);
    }
    double std_dev = std::sqrt(sum_squares / BUFFER_SIZE);

    // Check if the latest value is an anomaly
    return std::abs(data.back() - mean) > THRESHOLD * std_dev;
}

int main() {
    std::deque<double> buffer;
    bool anomaly_detected = false;

    std::cout << "Accelerometer Anomaly Detection Pipeline\n";
    std::cout << "------------------------------------------\n";

    while (true) {
        double new_sample = read_accelerometer();
        buffer.push_back(new_sample);

        // Maintain buffer size
        if (buffer.size() > BUFFER_SIZE) {
            buffer.pop_front();
        }

        // Detect anomalies
        if (buffer.size() == BUFFER_SIZE) {
            anomaly_detected = detect_anomaly(std::vector<double>(buffer.begin(), buffer.end()));
        }

        // Output results
        std::cout << "Sample: " << new_sample 
                  << " | Anomaly: " << (anomaly_detected ? "YES" : "NO") << std::endl;

        // Simulate real-time processing (sleep for 100ms)
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
    }

    return 0;
}
