    }
}

// Preprocess data: low-pass filter and moving average
void preprocess_data(float *input, float *output, int count) {
    float alpha = 0.1; // Filter coefficient (adjust for system dynamics)
    output[0] = input[0];
    for (int i = 1; i < count; i++) {
        output[i] = alpha * input[i] + (1 - alpha) * output[i - 1];
    }
}

// Feature extraction: calculate RMS (Root Mean Square)
float extract_features(float *data, int count) {
    float sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += data[i] * data[i];
    }
    return sqrt(sum / count);
}

// Anomaly detection: compare RMS to threshold
