```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h> // For usleep()

// Constants
#define SENSOR_BUFFER_SIZE 5
#define THRESHOLD 70
#define SAMPLE_RATE 100000 // 100ms delay between samples

// Simulated sensor data
int sensor_data[SENSOR_BUFFER_SIZE];
int buffer_index = 0;
int filtered_value = 0;

// Function to simulate sensor input
void read_sensor() {
    static int last_value = 0;
    // Simulate random sensor data (0-100)
    last_value = (last_value + rand() % 20 - 10) % 100;
    sensor_data[buffer_index++] = last_value;
    buffer_index %= SENSOR_BUFFER_SIZE;
}

// Simple moving average filter
void filter_data() {
    int sum = 0;
    for (int i = 0; i < SENSOR_BUFFER_SIZE; i++) {
        sum += sensor_data[i];
    }
    filtered_value = sum / SENSOR_BUFFER_SIZE;
}

// Actuator control logic
void manage_actuators() {
    if (filtered_value > THRESHOLD) {
        printf("Actuator activated: High value detected (%d)\n", filtered_value);
        // Simulate actuator activation (e.g., relay, LED, motor)
    } else {
        printf("Actuator inactive: Normal value (%d)\n", filtered_value);
    }
}

int main() {
    srand(time(NULL)); // Seed random number generator

    while (1) {
        read_sensor();
        filter_data();
        manage_actuators();
        usleep(SAMPLE_RATE); // Simulate real-time sampling
    }

    return 0;
}
