```csharp
using UnityEngine;

public class SpriteAnimation : MonoBehaviour
{
    public Sprite[] idleSprites;
    public Sprite[] runSprites;
    public Sprite[] jumpSprites;

    private SpriteRenderer spriteRenderer;
    private int currentFrame = 0;
    private float frameTime = 0.1f;
    private float timer = 0f;
    private string currentAnimation = "Idle";

    void Start()
    {
        spriteRenderer = GetComponent<SpriteRenderer>();
        Play("Idle");
    }

    void Update()
    {
        timer += Time.deltaTime;
        if (timer >= frameTime)
        {
            NextFrame();
            timer = 0f;
        }
    }

    public void Play(string animation)
    {
        currentAnimation = animation;
        currentFrame = 0;
        timer = 0f;
    }

    void NextFrame()
    {
        switch (currentAnimation)
        {
            case "Idle":
                currentFrame = (currentFrame + 1) % idleSprites.Length;
                spriteRenderer.sprite = idleSprites[currentFrame];
                break;
            case "Run":
                currentFrame = (currentFrame + 1) % runSprites.Length;
                spriteRenderer.sprite = runSprites[currentFrame];
                break;
            case "Jump":
                currentFrame = (currentFrame + 1) % jumpSprites.Length;
                spriteRenderer.sprite = jumpSprites[currentFrame];
                break;
        }
    }
}
```

