### 🌐 **Real-Time 3D Scene Viewer with Dynamic Lighting & Shaders (JavaScript + Three.js)**

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>3D Scene Viewer</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <!-- Include Three.js via CDN -->
  <script src="https://cdn.jsdelivr.net/npm/three@0.155.0/build/three.min.js"></script>
  <script src="https://cdn.jsdelivr.net/npm/three@0.155.0/examples/js/controls/OrbitControls.js"></script>
  <script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
    camera.position.set(0, 1, 5);

    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Lighting
    const ambientLight = new THREE.AmbientLight(0x404040, 1.5); // Soft light
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 1);
    directionalLight.position.set(1, 1, 1);
    scene.add(directionalLight);

    const pointLight = new THREE.PointLight(0xff0000, 1, 100);
    pointLight.position.set(0, 2, 3);
    scene.add(pointLight);

    // Custom Shader Material (Fragment Shader with Dynamic Lighting)
    const vertexShader = `
      varying vec3 vNormal;
      void main() {
        vNormal = normalize(normalMatrix * normal);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `;

    const fragmentShader = `
      varying vec3 vNormal;
      uniform vec3 lightDirection;
      uniform vec3 lightColor;
      uniform float lightIntensity;
      void main() {
        // Diffuse lighting
        vec3 normal = normalize(vNormal);
        float diff = max(dot(normal, lightDirection), 0.0);
        vec3 diffuse = lightColor * diff * lightIntensity;

        // Simple shader effect (e.g., glowing edges)
        float edge = smoothstep(0.8, 1.0, dot(normal, vec3(0, 1, 0))); // Vertical edge detection
        vec3 glow = vec3(1.0, 0.5, 0.2) * edge;

        gl_FragColor = vec4(diffuse + glow, 1.0);
      }
    `;

    const material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        lightDirection: { value: new THREE.Vector3(1, 1, 1) },
        lightColor: { value: new THREE.Color(0xffffff) },
        lightIntensity: { value: 1.0 }
      }
    });

    // Cube geometry
    const geometry = new THREE.BoxGeometry();
    const cube = new THREE.Mesh(geometry, material);
    scene.add(cube);

    // Controls
    const controls = new THREE.OrbitControls(camera, renderer.domElement);

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      // Update dynamic lighting (e.g., rotate light direction)
      material.uniforms.lightDirection.value.x = Math.sin(Date.now() * 0.001) * 2;
      material.uniforms.lightDirection.value.z = Math.cos(Date.now() * 0.001) * 2;

      // Update light position for real-time effect
      pointLight.position.x = Math.sin(Date.now() * 0.002) * 3;
      pointLight.position.z = Math.cos(Date.now() * 0.002) * 3;

      renderer.render(scene, camera);
    }

    animate();

    // Handle window resize
    window.addEventListener('resize', () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    });
  </script>
</body>
</html>
```

