#### 2. **Shader Code: Dynamic Lighting (Unlit Shader)**
```csharp
// MyDynamicShader.shader
Shader "Custom/MyDynamicShader"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _LightColor ("Light Color", Color) = (1,1,1,1)
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 200

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag

            #include "UnityCG.cginc"

            struct appdata
            {
                float4 vertex : POSITION;
                float3 normal : NORMAL;
            };

            struct v2f
            {
                float4 pos : SV_POSITION;
                float3 worldNormal : WORLDNORMAL;
            };

            sampler2D _MainTex;
            float4 _LightColor;

            v2f vert (appdata v)
            {
                v2f o;
                o.pos = UnityObjectToClipPos(v.vertex);
                o.worldNormal = normalize(mul(v.normal, (float3x3)unity_WorldToObject));
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // Calculate diffuse lighting
                float3 lightDir = normalize(_WorldSpaceLightPos0.xyz);
                float3 normal = i.worldNormal;
                float3 lightColor = _LightColor.rgb;
                float diffuse = max(0, dot(normal, lightDir));
                fixed4 col = tex2D(_MainTex, i.pos.xy / 2.0f) * (lightColor * diffuse);
                return col;
            }
            ENDCG
        }
    }
}
```

