#### 3. **C# Script: Dynamic Light Control**
```csharp
using UnityEngine;

public class DynamicLightController : MonoBehaviour
{
    public Light directionalLight;
    public float lightIntensity = 1.5f;
    public float lightRotationSpeed = 100f;

    void Start()
    {
        if (directionalLight == null)
        {
            directionalLight = FindObjectOfType<Light>();
        }
    }

    void Update()
    {
        // Dynamic lighting (e.g., rotate light direction)
        directionalLight.transform.Rotate(Vector3.up, lightRotationSpeed * Time.deltaTime);

        // Adjust light intensity dynamically
        directionalLight.intensity = Mathf.PingPong(Time.time, 1.0f) * lightIntensity;
    }
}
```

