### 📜 **HTML + JavaScript Code**
```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <title>3D Scene Viewer</title>
  <style>
    body { margin: 0; overflow: hidden; }
    canvas { display: block; }
  </style>
</head>
<body>
  <!-- Include Three.js from CDN -->
  <script src="https://cdn.jsdelivr.net/npm/three@0.155.0/build/three.min.js"></script>
  <script>
    // Scene setup
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Lighting (dynamic)
    const light = new THREE.DirectionalLight(0xffffff, 1);
    light.position.set(5, 5, 5);
    scene.add(light);

    // Shader Material (custom fragment shader for effects)
    const vertexShader = `
      varying vec3 vNormal;
      varying vec3 vPosition;
      void main() {
        vNormal = normal;
        vPosition = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `;

    const fragmentShader = `
      uniform vec3 lightDirection;
      uniform vec3 lightColor;
      varying vec3 vNormal;
      varying vec3 vPosition;
      void main() {
        // Calculate diffuse lighting
        vec3 normal = normalize(vNormal);
        vec3 lightDir = normalize(lightDirection - vPosition);
        float diff = max(dot(normal, lightDir), 0.0);
        vec3 diffuse = diff * lightColor;

        // Shader effect: glow based on lighting
        vec3 finalColor = diffuse + vec3(0.2, 0.2, 0.2);
        gl_FragColor = vec4(finalColor, 1.0);
      }
    `;

    const material = new THREE.ShaderMaterial({
      vertexShader,
      fragmentShader,
      uniforms: {
        lightDirection: { value: light.position.clone().normalize() },
        lightColor: { value: light.color }
      }
    });

    // Cube geometry
    const geometry = new THREE.BoxGeometry();
    const cube = new THREE.Mesh(geometry, material);
    scene.add(cube);

    // Camera position
    camera.position.z = 5;

    // Animation loop
    function animate() {
      requestAnimationFrame(animate);

      // Update light direction dynamically
      light.position.x = Math.sin(Date.now() * 0.002) * 10;
      light.position.y = Math.cos(Date.now() * 0.002) * 10;
      light.position.z = 5;
      material.uniforms.lightDirection.value.copy(light.position.clone().normalize());
      material.uniforms.lightColor.value.copy(light.color);

      renderer.render(scene, camera);
    }

    animate();

    // Resize handler
