// Define a simple AABB (Axis-Aligned Bounding Box)
struct AABB {
    float minX, minY, minZ;
    float maxX, maxY, maxZ;

    bool intersects(const AABB& other) const {
        return (minX < other.maxX && maxX > other.minX &&
                minY < other.maxY && maxY > other.minY &&
                minZ < other.maxZ && maxZ > other.minZ);
    }
};

// RigidBody class
class RigidBody {
public:
    RigidBody(float mass, const AABB& bounds)
        : mass(mass), bounds(bounds), velocity({0.0f, 0.0f, 0.0f}) {}

    void applyForce(const std::vector<float>& force) {
        // Simple impulse-based force application
        for (size_t i = 0; i < force.size(); ++i) {
            velocity[i] += force[i] / mass;
        }
    }

    void update(float deltaTime) {
        // Simple Euler integration
        for (size_t i = 0; i < 3; ++i) {
            bounds.minX += velocity[i] * deltaTime;
            bounds.maxX += velocity[i] * deltaTime;
        }
    }

    const AABB& getBounds() const { return bounds; }

private:
    float mass;
    AABB bounds;
    std::vector<float> velocity; // 3D velocity (x, y, z)
};

// PhysicsPlugin class
class PhysicsPlugin {
public:
    PhysicsPlugin() : gravity({0.0f, -9.81f, 0.0f}) {}

    void Initialize() {
        std::cout << "PhysicsPlugin initialized.\n";
