// Represents a rigid body in the physics world
class RigidBody {
public:
    RigidBody(float mass, float radius, float x, float y)
        : mass(mass), radius(radius), x(x), y(y), velocity(0.0f, 0.0f), force(0.0f, 0.0f) {}

    void ApplyForce(float fx, float fy) {
        force.x += fx;
        force.y += fy;
    }

    void Update(float deltaTime) {
        // Integrate forces into acceleration
        float ax = force.x / mass;
        float ay = force.y / mass;

        // Update velocity and position
        velocity.x += ax * deltaTime;
        velocity.y += ay * deltaTime;
        x += velocity.x * deltaTime;
        y += velocity.y * deltaTime;

        // Reset force for next frame
        force = {0.0f, 0.0f};
    }

    float x, y;           // Position
    float velocity[2];    // Velocity (x, y)
    float force[2];       // Force (x, y)
    float mass;           // Mass
    float radius;         // Collision radius
};

// Core physics plugin class
class PhysicsPlugin {
public:
    PhysicsPlugin() : timeStep(0.016f) {} // ~60 FPS

    void Initialize() {
        // Initialize physics systems (e.g., collision detection, solver)
    }

    void AddRigidBody(RigidBody* body) {
        bodies.push_back(body);
    }

    void Update(float deltaTime) {
        // Step 1: Apply forces to all bodies
        for (auto body : bodies) {
            body->ApplyForce(0.0f, -9.81f * body->mass); // Gravity
        }

        // Step 2: Integrate physics (velocity and position)
        for (auto body : bodies) {
            body->Update(deltaTime);
        }

        // Step 3: Collision detection and resolution
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                ResolveCollision(bodies[i], bodies[j]);
            }
        }
    }

    void ResolveCollision(RigidBody* a, RigidBody* b) {
        // Simple circle-circle collision detection
        float dx = b->x - a->x;
        float dy = b->y - a->y;
        float distance = std::sqrt(dx * dx + dy * dy);

        if (distance < a->radius + b->radius) {
            // Calculate normal vector
            float overlap = a->radius + b->radius - distance;
            float nx = dx / distance;
            float ny = dy / distance;

            // Apply impulse to resolve collision
            float impulse = (2.0f * (a->velocity[0] * nx + a->velocity[1] * ny) * a->mass * b->mass) /
                            (a->mass + b->mass);
            a->velocity[0] -= impulse * nx;
            a->velocity[1] -= impulse * ny;
            b->velocity[0] += impulse * nx;
            b->velocity[1] += impulse * ny;
        }
    }

    std::vector<RigidBody*> bodies;
    float timeStep;
};
