// Forward declarations
class PhysicsBody;
class CollisionHandler;

// Represents a physical object in the game world
class PhysicsBody {
public:
    PhysicsBody(float mass, float radius)
        : mass(mass), radius(radius), position(0.0f, 0.0f), velocity(0.0f, 0.0f) {}

    void applyForce(float fx, float fy) {
        acceleration.x += fx / mass;
        acceleration.y += fy / mass;
    }

    void update(float deltaTime) {
        velocity.x += acceleration.x * deltaTime;
        velocity.y += acceleration.y * deltaTime;
        position.x += velocity.x * deltaTime;
        position.y += velocity.y * deltaTime;
        acceleration.x = 0.0f;
        acceleration.y = 0.0f;
    }

    float getMass() const { return mass; }
    float getRadius() const { return radius; }
    float getX() const { return position.x; }
    float getY() const { return position.y; }

private:
    float mass;
    float radius;
    float position[2];
    float velocity[2];
    float acceleration[2];
};

// Manages collision detection and resolution
class CollisionHandler {
public:
    void detectCollisions(const std::vector<std::shared_ptr<PhysicsBody>>& bodies) {
        for (size_t i = 0; i < bodies.size(); ++i) {
            for (size_t j = i + 1; j < bodies.size(); ++j) {
                auto& bodyA = *bodies[i];
                auto& bodyB = *bodies[j];

                // Simple circle-circle collision detection
                float dx = bodyB.getX() - bodyA.getX();
                float dy = bodyB.getY() - bodyA.getY();
                float distance = std::sqrt(dx * dx + dy * dy);
                float minDistance = bodyA.getRadius() + bodyB.getRadius();

                if (distance < minDistance) {
                    resolveCollision(bodyA, bodyB, dx, dy, distance, minDistance);
                }
            }
        }
    }

private:
    void resolveCollision(PhysicsBody& a, PhysicsBody& b, float dx, float dy, float distance, float minDistance) {
        // Calculate overlap
        float overlap = minDistance - distance;
        float normalX = dx / distance;
        float normalY = dy / distance;

        // Calculate impulse for collision response
        float j = (2.0f * a.getMass() * b.getMass()) / (a.getMass() + b.getMass()) * overlap;
        float impulseX = j * normalX;
        float impulseY = j * normalY;

        // Apply impulse to velocities
        a.velocity[0] -= impulseX / a.getMass();
        a.velocity[1] -= impulseY / a.getMass();
        b.velocity[0] += impulseX / b.getMass();
        b.velocity[1] += impulseY / b.getMass();
