    objects.push_back(obj);
}

void PhysicsEngine::Update(float deltaTime) {
    for (auto& obj : objects) {
        if (!obj.active) continue;

        // Apply gravity
        obj.vy += gravity * deltaTime;
        obj.y += obj.vy * deltaTime;
        obj.x += obj.vx * deltaTime;

        // Simple boundary collision (floor)
        if (obj.y < 0.0f) {
            obj.y = 0.0f;
            obj.vy *= -0.5f; // Bounce with energy loss
        }
    }
}

void PhysicsEngine::CheckCollisions() {
    for (size_t i = 0; i < objects.size(); ++i) {
        for (size_t j = i + 1; j < objects.size(); ++j) {
            const auto& a = objects[i];
            const auto& b = objects[j];

            // Simple AABB collision detection
            if (a.x < b.x + 1.0f && a.x + 1.0f > b.x &&
                a.y < b.y + 1.0f && a.y + 1.0f > b.y) {
                // Basic collision response (simplified)
                float overlap = (a.x + 1.0f - b.x) * 0.5f;
                a.x -= overlap;
                b.x += overlap;
                a.vx *= -0.5f;
                b.vx *= -0.5f;
            }
        }
    }
}
