// Represents a rigid body with position, velocity, and mass
class RigidBody {
public:
    RigidBody(float mass, float x = 0.0f, float y = 0.0f)
        : mass(mass), position(x, y), velocity(0.0f, 0.0f) {}

    // Apply a force to the body
    void ApplyForce(float fx, float fy) {
        acceleration.x += fx / mass;
        acceleration.y += fy / mass;
    }

    // Update the body's state (position and velocity)
    void Update(float deltaTime) {
        velocity.x += acceleration.x * deltaTime;
        velocity.y += acceleration.y * deltaTime;

        position.x += velocity.x * deltaTime;
        position.y += velocity.y * deltaTime;

        // Reset acceleration for next frame
        acceleration.x = 0.0f;
        acceleration.y = 0.0f;
    }

    // Get position
    float GetX() const { return position.x; }
    float GetY() const { return position.y; }

private:
    float mass;
    float position[2] = {0.0f, 0.0f};
    float velocity[2] = {0.0f, 0.0f};
    float acceleration[2] = {0.0f, 0.0f};
};

// Physics engine class managing rigid bodies
class PhysicsEngine {
public:
    // Add a rigid body to the engine
    void AddBody(std::unique_ptr<RigidBody> body) {
        bodies.push_back(std::move(body));
    }

    // Apply gravity to all bodies
    void ApplyGravity(float gravity = 9.81f) {
        for (auto& body : bodies) {
            body->ApplyForce(0.0f, -gravity * body->mass);
        }
    }

    // Update all bodies (including collision with ground)
    void Update(float deltaTime) {
        ApplyGravity();

        for (auto& body : bodies) {
            body->Update(deltaTime);

            // Simple ground collision (y = 0)
            if (body->GetY() < 0.0f) {
                body->position[1] = 0.0f;
                body->velocity[1] = std::max(body->velocity[1], -10.0f); // Bounce dampening
            }
        }
    }

private:
    std::vector<std::unique_ptr<RigidBody>> bodies;
};
```

