#include <iostream>
#include <chrono>
#include <thread>
#include <bullet/btBulletDynamicsWorld.h>
#include <bullet/btRigidBody.h>
#include <bullet/btCollisionShape.h>

// Constants
const float FIXED_TIME_STEP = 1.0f / 60.0f; // 60 FPS
const float MAX_DELTA_TIME = 0.1f;         // Max time between steps to avoid instability

int main() {
    // Initialize Bullet Physics
    btDefaultCollisionConfiguration* collisionConfig = new btDefaultCollisionConfiguration();
    btCollisionDispatcher* dispatcher = new btCollisionDispatcher(collisionConfig);
    btBroadphaseInterface* broadphase = new btDbvtBroadphase();
    btConstraintSolver* solver = new btSequentialImpulseConstraintSolver();
    btDynamicsWorld* dynamicsWorld = new btDiscreteDynamicsWorld(dispatcher, broadphase, solver, collisionConfig);
    dynamicsWorld->setGravity(btVector3(0, -9.81, 0));

    // Create a rigid body (box)
    btCollisionShape* groundShape = new btBoxShape(btVector3(50, 1, 50));
    btScalar mass = 1.0f;
    btVector3 localInertia(0, 0, 0);
    groundShape->calculateLocalInertia(mass, localInertia);

    btRigidBody* groundBody = new btRigidBody(mass, nullptr, groundShape, localInertia);
    groundBody->setCollisionFlags(groundBody->getCollisionFlags() | btCollisionObject::CF_KINEMATIC_OBJECT);
    groundBody->setAngularVelocity(btVector3(0, 0, 0));
    dynamicsWorld->addRigidBody(groundBody);

    // Create a dynamic rigid body (sphere)
    btCollisionShape* shape = new btSphereShape(1.0f);
    mass = 10.0f;
    shape->calculateLocalInertia(mass, localInertia);

    btRigidBody* body = new btRigidBody(mass, nullptr, shape, localInertia);
    body->setLinearVelocity(btVector3(0, 5, 0)); // Initial velocity
    dynamicsWorld->addRigidBody(body);

    // Main loop
    auto lastTime = std::chrono::steady_clock::now();
    while (true) {
        auto now = std::chrono::steady_clock::now();
        auto delta = std::chrono::duration_cast<std::chrono::duration<float>>(now - lastTime).count();
        lastTime = now;

        // Accumulate delta time for variable frame rates
        static float accumulatedTime = 0.0f;
        accumulatedTime += delta;

        // Step simulation with fixed time step
        while (accumulatedTime >= FIXED_TIME_STEP) {
            dynamicsWorld->stepSimulation(FIXED_TIME_STEP, 1);
            accumulatedTime -= FIXED_TIME_STEP;
        }

        // Optional: Limit maximum frame time (e.g., for rendering)
        if (delta > MAX_DELTA_TIME) {
            std::cerr << "Frame time exceeded max delta time: " << delta << "s" << std::endl;
        }

        // Render/update UI here (placeholder)
