### 🧾 **C++ Code**
```cpp
#include <iostream>
#include <thread>
#include <chrono>

// Constants
const float GRAVITY = 9.81f; // m/s²
const float FIXED_TIMESTEP = 1.0f / 60.0f; // 60 FPS
const float GROUND_Y = 0.0f;
const float BOUNCE_COEFFICIENT = 0.8f;

// Rigid Body
struct RigidBody {
    float x = 0.0f;
    float y = 10.0f; // Initial height
    float vx = 0.0f;
    float vy = 0.0f;
    float mass = 1.0f;
};

// Update physics with fixed time step
void updatePhysics(RigidBody& body, float deltaTime) {
    // Apply gravity
    float acceleration = GRAVITY;
    body.vy += acceleration * deltaTime;

    // Update velocity and position
    body.x += body.vx * deltaTime;
    body.y += body.vy * deltaTime;

    // Collision with ground
    if (body.y <= GROUND_Y) {
        body.y = GROUND_Y;
        body.vy *= -BOUNCE_COEFFICIENT; // Bounce
    }
}

// Main simulation loop
int main() {
    RigidBody body;
    float lastTime = 0.0f;
    float accumulator = 0.0f;

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        float currentTime = std::chrono::duration_cast<std::chrono::duration<float>>(now.time_since_epoch()).count();
        float deltaTime = currentTime - lastTime;
        lastTime = currentTime;

        // Accumulate time for variable frame rates
        accumulator += deltaTime;

        // Process fixed time steps
        while (accumulator >= FIXED_TIMESTEP) {
            updatePhysics(body, FIXED_TIMESTEP);
            accumulator -= FIXED_TIMESTEP;
        }

        // Cap frame rate (e.g., 60 FPS)
        if (deltaTime < 1.0f / 60.0f) {
            std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<long long>(1000.0f / 60.0f - deltaTime * 1000.0f)));
        }

        // Output current state
        std::cout << "Position: (" << body.x << ", " << body.y << ") | Velocity: (" << body.vx << ", " << body.vy << ")\n";
    }

    return 0;
}
```

