```cpp
#include <iostream>
#include <vector>
#include <cmath>
#include <chrono>
#include <thread>

// Constants
const float GRAVITY = -9.81f;  // m/s²
const float FIXED_TIMESTEP = 1.0f / 60.0f;  // 60 Hz fixed time step
const float MAX_DELTA_TIME = 0.1f;  // Max delta time to prevent large updates

// Rigid Body class
class RigidBody {
public:
    float position = 0.0f;     // Position (simplified to 1D for brevity)
    float velocity = 0.0f;
    float mass = 1.0f;
    float force = 0.0f;

    void applyForce(float force) {
        this->force += force;
    }

    void integrate(float dt) {
        // Euler integration
        velocity += (force / mass) * dt;
        position += velocity * dt;
        force = 0.0f;  // Reset force after integration
    }
};

int main() {
    // Initialize simulation
    std::vector<RigidBody> bodies = { {0.0f, 0.0f, 1.0f} };  // Single rigid body
    bool running = true;

    // Frame-rate control
    auto lastTime = std::chrono::high_resolution_clock::now();
    float accumulatedTime = 0.0f;

    while (running) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        float deltaTime = std::chrono::duration_cast<std::chrono::duration<float>>(currentTime - lastTime).count();
        lastTime = currentTime;

        // Apply gravity (simplified to 1D)
        bodies[0].applyForce(GRAVITY * bodies[0].mass);

        // Accumulate delta time and step simulation
        accumulatedTime += deltaTime;
        while (accumulatedTime >= FIXED_TIMESTEP) {
            for (auto& body : bodies) {
                body.integrate(FIXED_TIMESTEP);
            }
            accumulatedTime -= FIXED_TIMESTEP;
        }

        // Output simulation state (simplified)
        std::cout << "Position: " << bodies[0].position << " | Velocity: " << bodies[0].velocity << std::endl;

        // Simulate frame-rate constraint (sleep to maintain target frame rate)
        if (deltaTime < MAX_DELTA_TIME) {
            std::this_thread::sleep_for(std::chrono::milliseconds(static_cast<int>(MAX_DELTA_TIME * 1000) - static_cast<int>(deltaTime * 1000)));
        }

        // Exit on user input (e.g., press 'q')
        if (std::cin.get() == 'q') {
            running = false;
        }
    }

    return 0;
}
