#include <iostream>
#include <chrono>
#include <thread>

// Rigid Body Class
class RigidBody {
public:
    float position = 0.0f;     // Position (y-axis)
    float velocity = 0.0f;     // Velocity
    float mass = 1.0f;         // Mass
    float gravity = -9.81f;    // Gravity (negative for downward direction)
    float groundLevel = 0.0f;  // Ground level (y = 0)

    void update(float deltaTime) {
        // Apply gravity
        velocity += gravity * deltaTime;

        // Update position
        position += velocity * deltaTime;

        // Collision with ground (bounce)
        if (position < groundLevel) {
            position = groundLevel;
            velocity = -velocity * 0.8f; // 80% bounce coefficient
        }
    }
};

// Main Simulation Loop
int main() {
    const float fixedDeltaTime = 1.0f / 60.0f; // 60 Hz physics updates
    RigidBody body;

    auto lastTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto currentTime = std::chrono::high_resolution_clock::now();
        auto elapsedTime = std::chrono::duration_cast<std::chrono::duration<float>>(currentTime - lastTime).count();
        lastTime = currentTime;

        // Use fixed time step for physics
        float deltaTime = fixedDeltaTime;
        body.update(deltaTime);

        // Render (console output)
        std::cout << "Position: " << body.position << " | Velocity: " << body.velocity << std::endl;
        std::cout << "-----------------------------" << std::endl;

        // Optional: Control simulation speed with user input
        std::cout << "Press Enter to continue... ";
        std::cin.get();

        // Sleep to maintain frame rate (optional for real-time)
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    return 0;
}
