#include <thread>

// Constants
const float GRAVITY = -9.81f; // m/s²
const float FIXED_TIME_STEP = 1.0f / 60.0f; // 60Hz fixed time step
const float MAX_DELTA_TIME = 0.1f; // Prevent large time jumps

// RigidBody class
class RigidBody {
public:
    float x, y;         // Position
    float vx, vy;       // Velocity
    float mass = 1.0f;  // Mass
    float radius = 0.5f; // Collision radius

    RigidBody(float x, float y) : x(x), y(y), vx(0.0f), vy(0.0f) {}

    void applyForce(float fx, float fy) {
        vx += fx / mass * FIXED_TIME_STEP;
        vy += fy / mass * FIXED_TIME_STEP;
    }

    void integrate(float deltaTime) {
        x += vx * deltaTime;
        y += vy * deltaTime;
        vy += GRAVITY * deltaTime; // Apply gravity
    }

    void resolveCollision(float groundY) {
        if (y - radius <= groundY) {
            y = groundY + radius;
            vy = -vy * 0.8f; // Bounce with energy loss
        }
    }
};

// Simulation loop
void simulate(std::vector<RigidBody>& bodies, float deltaTime) {
    for (auto& body : bodies) {
        body.integrate(deltaTime);
        body.resolveCollision(-10.0f); // Ground at y = -10
    }
}

// Main function
int main() {
    // Initialize simulation
    std::vector<RigidBody> bodies;
    bodies.emplace_back(0.0f, 5.0f); // Ball
    bodies.emplace_back(5.0f, 5.0f); // Another ball

    auto lastTime = std::chrono::high_resolution_clock::now();
    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        auto deltaTime = std::chrono::duration_cast<std::chrono::duration<float>>(now - lastTime).count();
        lastTime = now;

        // Limit delta time to prevent instability
        if (deltaTime > MAX_DELTA_TIME) deltaTime = MAX_DELTA_TIME;

        // Apply forces (e.g., user input or physics)
        for (auto& body : bodies) {
            body.applyForce(0.0f, 0.0f); // No external force
        }

        // Update simulation with fixed time step
        simulate(bodies, FIXED_TIME_STEP);

        // Render (console output for simplicity)
        std::cout << "Frame: ";
        for (const auto& body : bodies) {
            std::cout << "(" << body.x << ", " << body.y << ") ";
        }
        std::cout << std::endl;

        // Control frame rate (optional, for testing)
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    return 0;
}
