### 📌 **Minimal Real-Time Physics Simulation (C++)**

```cpp
#include <iostream>
#include <chrono>
#include <thread>
#include <cmath>

// Rigid body struct
struct RigidBody {
    double x, y;         // Position
    double vx, vy;       // Velocity
    double mass = 1.0;   // Mass
};

// Constants
const double GRAVITY = 9.81;  // m/s²
const double FIXED_TIMESTEP = 1.0 / 60.0; // 60 Hz fixed time step
const double GROUND_Y = 0.0;

// Update physics with fixed time step
void updatePhysics(RigidBody& body, double deltaTime) {
    // Apply gravity
    body.vy -= GRAVITY * deltaTime;
    body.y += body.vy * deltaTime;
    body.x += body.vx * deltaTime;

    // Collision with ground
    if (body.y < GROUND_Y) {
        body.y = GROUND_Y;
        body.vy = 0.0; // Prevent penetration
    }
}

// Main simulation loop
int main() {
    RigidBody body = {0.0, 10.0, 0.0, -5.0}; // Initial position and velocity
    auto lastTime = std::chrono::steady_clock::now();

    while (true) {
        auto now = std::chrono::steady_clock::now();
        auto deltaTime = std::chrono::duration_cast<std::chrono::duration<double>>(now - lastTime).count();
        lastTime = now;

        // Accumulate delta time for fixed time steps
        static double accumulatedTime = 0.0;
        accumulatedTime += deltaTime;

        while (accumulatedTime >= FIXED_TIMESTEP) {
            updatePhysics(body, FIXED_TIMESTEP);
            accumulatedTime -= FIXED_TIMESTEP;
        }

        // Frame-rate constraint: sleep to maintain target frame rate
        double sleepTime = FIXED_TIMESTEP - (accumulatedTime > 0 ? accumulatedTime : 0);
        if (sleepTime > 0) {
            std::this_thread::sleep_for(std::chrono::duration<double>(sleepTime));
        }

        // Output simulation state
        std::cout << "Position: (" << body.x << ", " << body.y << ")  ";
        std::cout << "Velocity: (" << body.vx << ", " << body.vy << ")\r";
        std::cout.flush();
    }

    return 0;
}
```

