### ✅ **Minimal Real-Time Physics Simulation in C++**
```cpp
#include <iostream>
#include <chrono>
#include <thread>

// Rigid Body Structure
struct RigidBody {
    double position = 0.0;
    double velocity = 0.0;
    double mass = 1.0;
    double force = 0.0;
};

// Constants
const double GRAVITY = -9.81;  // m/s²
const double FIXED_TIMESTEP = 1.0 / 60.0;  // 60 Hz fixed time step
const double MAX_DELTA_TIME = 0.1;  // Max allowed frame time to prevent instability

// Physics Update Function
void updatePhysics(RigidBody& body, double deltaTime) {
    // Apply force (e.g., gravity)
    body.force += GRAVITY * body.mass;

    // Integrate velocity and position using Euler method
    body.velocity += body.force / body.mass * deltaTime;
    body.position += body.velocity * deltaTime;

    // Reset force for next frame
    body.force = 0.0;
}

// Frame-Rate Controlled Simulation Loop
void runSimulation() {
    RigidBody body;
    auto lastTime = std::chrono::high_resolution_clock::now();

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        auto deltaTime = std::chrono::duration_cast<std::chrono::duration<double>>(now - lastTime).count();
        lastTime = now;

        // Cap delta time to prevent instability
        if (deltaTime > MAX_DELTA_TIME) deltaTime = MAX_DELTA_TIME;

        // Update physics with fixed time step
        updatePhysics(body, FIXED_TIMESTEP);

        // Print position to console (for real-time feedback)
        std::cout << "Position: " << body.position << " m" << std::endl;

        // Sleep to maintain target frame rate
        std::this_thread::sleep_for(std::chrono::duration<double>(FIXED_TIMESTEP));
    }
}

int main() {
    runSimulation();
    return 0;
}
```

