#include <SFML/Graphics.hpp>
#include <iostream>
#include <chrono>

// Rigid Body Class
class Body {
public:
    sf::Vector2f position;
    sf::Vector2f velocity;
    float mass = 1.0f;
};

// Physics Update Function
void update(Body& body, float dt, float gravity) {
    // Apply gravity
    body.velocity.y += gravity * dt;
    body.position += body.velocity * dt;

    // Collision with ground (y=0)
    if (body.position.y <= 0) {
        body.position.y = 0;
        body.velocity.y *= -0.8; // Bounce with energy loss
    }
}

int main() {
    // Initialize SFML window
    sf::RenderWindow window(sf::VideoMode(800, 600), "Physics Simulation");
    window.setFramerateLimit(60); // Cap frame rate to 60 FPS

    // Create a rigid body (ball)
    Body body = {sf::Vector2f(400, 500), sf::Vector2f(0, -5)}; // Initial position and velocity
    float gravity = 9.81f;
    const float fixedDeltaTime = 1.0f / 60.0f; // Fixed time step for physics
    auto lastTime = std::chrono::high_resolution_clock::now();

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        auto now = std::chrono::high_resolution_clock::now();
        auto dt = std::chrono::duration_cast<std::chrono::milliseconds>(now - lastTime).count() / 1000.0f;
        lastTime = now;

        // Accumulate delta time and process fixed time steps
        static float accumulatedTime = 0.0f;
        accumulatedTime += dt;

        while (accumulatedTime >= fixedDeltaTime) {
            update(body, fixedDeltaTime, gravity);
            accumulatedTime -= fixedDeltaTime;
        }

        // Clear window
        window.clear();

        // Draw the body as a red circle
        sf::CircleShape shape(20);
        shape.setPosition(body.position);
        shape.setFillColor(sf::Color::Red);
        window.draw(shape);

        // Display the frame
        window.display();
    }

    return 0;
}
