### 🧾 **Code Example**
```cpp
#include <iostream>
#include <chrono>
#include <thread>

class RigidBody {
public:
    float x, y;
    float vx, vy;
    float mass;

    RigidBody(float x, float y, float mass) : x(x), y(y), vx(0), vy(0), mass(mass) {}

    void update(float dt) {
        // Apply gravity
        vy += 9.81f * dt / mass;
        // Update position
        x += vx * dt;
        y += vy * dt;
        // Collision with ground
        if (y < 0) {
            y = 0;
            vy = -vy * 0.8f; // Bounce with energy loss
        }
    }
};

int main() {
    const float fixed_dt = 1.0f / 60.0f; // 60 FPS
    RigidBody body(0.0f, 10.0f, 1.0f);  // Initial position and mass

    auto last_time = std::chrono::high_resolution_clock::now();

    while (true) {
        auto now = std::chrono::high_resolution_clock::now();
        auto delta_time = std::chrono::duration_cast<std::chrono::duration<float>>(now - last_time).count();
        last_time = now;

        // Apply fixed time step
        while (delta_time > fixed_dt) {
            body.update(fixed_dt);
            delta_time -= fixed_dt;
        }

        // Cap frame rate to ~60 FPS
        std::this_thread::sleep_for(std::chrono::milliseconds(16));

        // Output position
        std::cout << "Position: (" << body.x << ", " << body.y << ")\n";
    }

    return 0;
}
```

