#include <atomic>
#include <cmath>

// Constants
const float GRAVITY = 9.81f; // m/s²
const float FIXED_TIME_STEP = 1.0f / 60.0f; // 60 FPS
const float MAX_SPEED = 50.0f; // m/s
const float JUMP_FORCE = 10.0f; // m/s²

// Rigid body struct
struct RigidBody {
    float position = 0.0f; // m
    float velocity = 0.0f; // m/s
    float mass = 1.0f;     // kg
};

// Update physics with fixed time step
void updatePhysics(RigidBody& body, float deltaTime) {
    // Apply gravity
    body.velocity += GRAVITY * deltaTime;
    body.position += body.velocity * deltaTime;

    // Clamp velocity to prevent excessive speed
    if (std::abs(body.velocity) > MAX_SPEED) {
        body.velocity = MAX_SPEED * (body.velocity > 0 ? 1.0f : -1.0f);
    }
}

// Main simulation loop
int main() {
    RigidBody ball;
    bool isJumping = false;

    std::atomic<bool> running(true);

    // Main loop
    while (running) {
        // Simulate fixed time step
        float deltaTime = FIXED_TIME_STEP;
        updatePhysics(ball, deltaTime);

        // Handle input (e.g., spacebar to jump)
        if (isJumping) {
            ball.velocity = JUMP_FORCE;
            isJumping = false;
        }

        // Output current state
        std::cout << "Position: " << ball.position << "m | Velocity: " << ball.velocity << "m/s\n";

        // Frame-rate constraint: sleep to maintain 60 FPS
        std::this_thread::sleep_for(std::chrono::milliseconds(16)); // ~60 FPS
    }

    return 0;
}
