// Mock database for accounts and balances
class AccountDatabase {
    private final Map<String, Double> accounts = new ConcurrentHashMap<>();
    private final Logger logger = Logger.getLogger(AccountDatabase.class.getName());

    public void addAccount(String accountId, double balance) {
        accounts.put(accountId, balance);
        logger.info("Account added: " + accountId + " with balance: " + balance);
    }

    public boolean hasAccount(String accountId) {
        return accounts.containsKey(accountId);
    }

    public double getBalance(String accountId) {
        return accounts.getOrDefault(accountId, 0.0);
    }

    public void updateBalance(String accountId, double amount) {
        if (hasAccount(accountId)) {
            accounts.put(accountId, accounts.get(accountId) + amount);
            logger.info("Balance updated for " + accountId + ": " + getBalance(accountId));
        } else {
            logger.warning("Account not found: " + accountId);
        }
    }
}

// Transaction details
class Transaction {
    private final String fromAccountId;
    private final String toAccountId;
    private final double amount;
    private final String timestamp;

    public Transaction(String fromAccountId, String toAccountId, double amount) {
        this.fromAccountId = fromAccountId;
        this.toAccountId = toAccountId;
        this.amount = amount;
        this.timestamp = new java.util.Date().toString();
    }

    public String getFromAccountId() { return fromAccountId; }
    public String getToAccountId() { return toAccountId; }
    public double getAmount() { return amount; }
    public String getTimestamp() { return timestamp; }
}

// Payment processor
class PaymentProcessor {
    private final AccountDatabase database;
    private final Logger logger = Logger.getLogger(PaymentProcessor.class.getName());

    public PaymentProcessor(AccountDatabase database) {
        this.database = database;
    }

    public void processPayment(Transaction transaction) {
        if (transaction.getAmount() <= 0) {
            logger.severe("Invalid transaction amount: " + transaction.getAmount());
            return;
        }

        if (!database.hasAccount(transaction.getFromAccountId())) {
            logger.severe("Source account not found: " + transaction.getFromAccountId());
            return;
        }

        if (!database.hasAccount(transaction.getToAccountId())) {
            logger.severe("Destination account not found: " + transaction.getToAccountId());
            return;
        }

        double fromBalance = database.getBalance(transaction.getFromAccountId());
        if (fromBalance < transaction.getAmount()) {
            logger.severe("Insufficient balance in source account: " + fromBalance + " < " + transaction.getAmount());
            return;
        }

        // Simulate authorization (e.g., real system would call external API)
        boolean authorized = authorizePayment(transaction);
        if (!authorized) {
            logger.severe("Payment unauthorized: " + transaction.getFromAccountId() + " to " + transaction.getToAccountId());
            return;
        }

        // Execute transaction
        database.updateBalance(transaction.getFromAccountId(), -transaction.getAmount());
        database.updateBalance(transaction.getToAccountId(), transaction.getAmount());
        logger.info("Payment processed: " + transaction.getFromAccountId() + " -> " + transaction.getToAccountId() + " (" + transaction.getAmount() + ")");
    }

    private boolean authorizePayment(Transaction transaction) {
        // Simulate authorization logic (e.g., check fraud, limits, etc.)
        // In production, this would integrate with external systems
        return true; // Simplified for example
    }
}

// Main application
public class PaymentService {
