    public static void main(String[] args) {
        AccountDatabase database = new AccountDatabase();
        database.addAccount("ACCT123", 10000.0);
        database.addAccount("ACCT456", 5000.0);

        PaymentProcessor processor = new PaymentProcessor(database);

        ExecutorService executor = Executors.newFixedThreadPool(4);

        // Simulate concurrent transactions
        List<Runnable> tasks = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            String from = i % 2 == 0 ? "ACCT123" : "ACCT456";
            String to = i % 2 == 0 ? "ACCT456" : "ACCT123";
            double amount = Math.random() * 1000 + 100; // Random amount between 100 and 1100

            Transaction transaction = new Transaction(from, to, amount);
            tasks.add(() -> {
                try {
                    processor.processPayment(transaction);
                } catch (Exception e) {
                    logger.severe("Payment processing failed: " + e.getMessage());
                }
            });
        }

        // Submit tasks to executor
        for (Runnable task : tasks) {
            executor.submit(task);
        }

        // Shutdown executor
        executor.shutdown();
        try {
            if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
                executor.shutdownNow();
            }
        } catch (InterruptedException e) {
            executor.shutdownNow();
            Thread.currentThread().interrupt();
        }

        // Print final balances
        logger.info("Final balances:");
        database.accounts.forEach((accountId, balance) -> logger.info(accountId + ": " + balance));
    }
}
