    private static final Logger logger = LoggerFactory.getLogger(PaymentService.class);
    private static final String ENCRYPTION_KEY = "SecureKey12345678"; // Should be securely managed
    private static final ConcurrentHashMap<String, PaymentStatus> paymentStatusMap = new ConcurrentHashMap<>();
    private static final AtomicLong paymentIdGenerator = new AtomicLong(1000);

    @Autowired
    private PaymentGateway paymentGateway;

    @Transactional
    public PaymentResponse processPayment(PaymentRequest request) {
        // Validate input
        if (request.getAmount() <= 0) {
            throw new IllegalArgumentException("Payment amount must be positive");
        }

        // Encrypt sensitive data
        String encryptedCardNumber = encrypt(request.getCardNumber());
        String encryptedExpiry = encrypt(request.getExpiry());

        // Simulate payment processing
