// Configuration
var (
	db *sql.DB
)

// PaymentRequest represents a payment request
type PaymentRequest struct {
	CardNumber string `json:"card_number"`
	Expiry     string `json:"expiry"`
	CVV        string `json:"cvv"`
	Amount     float64 `json:"amount"`
}

// PaymentResponse represents a payment response
type PaymentResponse struct {
	TransactionID string `json:"transaction_id"`
	Status        string `json:"status"`
	Message       string `json:"message"`
}

// Initialize database connection
func initDB() {
	connStr := "user=postgres password=yourpassword dbname=payments sslmode=disable"
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatalf("Error connecting to database: %v", err)
	}
	if err = db.Ping(); err != nil {
		log.Fatalf("Error pinging database: %v", err)
	}
	fmt.Println("Connected to database")
}

// ProcessPayment handles payment processing
func ProcessPayment(w http.ResponseWriter, r *http.Request) {
	var req PaymentRequest
	if err := decodeJSON(r, &req); err != nil {
		http.Error(w, "Invalid request", http.StatusBadRequest)
		return
	}

	// Validate input
	if req.CardNumber == "" || req.Expiry == "" || req.CVV == "" || req.Amount <= 0 {
		http.Error(w, "Missing or invalid fields", http.StatusBadRequest)
		return
	}

	// Simulate fraud detection (real systems would use ML models)
	if isFraudulent(req.CardNumber) {
		http.Error(w, "Fraud detected", http.StatusForbidden)
		return
	}

	// Simulate payment processing
	transactionID := generateTransactionID()
	if err := processTransaction(req, transactionID); err != nil {
		http.Error(w, "Payment failed", http.StatusInternalServerError)
		return
	}

	// Respond with success
	resp := PaymentResponse{
		TransactionID: transactionID,
		Status:        "success",
		Message:       "Payment processed successfully",
	}
	encodeJSON(w, resp)
}

// decodeJSON decodes JSON from request body
func decodeJSON(r *http.Request, v interface{}) error {
	return json.NewDecoder(r.Body).Decode(v)
}

// encodeJSON encodes JSON to response writer
func encodeJSON(w http.ResponseWriter, v interface{}) {
	json.NewEncoder(w).Encode(v)
}

// isFraudulent checks if a card is fraudulent (mock)
func isFraudulent(cardNumber string) bool {
	// In real systems, this would use a fraud detection API or database
	return cardNumber == "4111111111111111" // Mock fraudulent card
}

// generateTransactionID creates a unique transaction ID
func generateTransactionID() string {
	return fmt.Sprintf("TXN-%d", time.Now().UnixNano())
}

// processTransaction simulates transaction processing
func processTransaction(req PaymentRequest, transactionID string) error {
	// In real systems, this would interact with payment gateways, update balances, etc.
	query := "INSERT INTO payments (transaction_id, card_number, expiry, cvv, amount, status) VALUES ($1, $2, $3, $4, $5, $6)"
	_, err := db.Exec(query, transactionID, req.CardNumber, req.Expiry, req.CVV, req.Amount, "success")
	return err
}

// main starts the server
func main() {
	// Initialize database
	initDB()
	defer db.Close()

	// Set up router
	r := mux.NewRouter()
	r.HandleFunc("/payments", ProcessPayment).Methods("POST")

	// Start server
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Server starting on :%s\n", port)
	log.Fatal(http.ListenAndServe(":"+port, r))
}
