        random.nextBytes(encrypted);
        return Base64.getEncoder().encodeToString(encrypted); // Simplified
    }

    public PaymentResponse processPayment(PaymentRequest request) {
        if (request == null || request.getAmount() <= 0 || request.getCardNumber() == null) {
            throw new IllegalArgumentException("Invalid payment request");
        }

        // Validate card (simplified check)
        if (!isValidCard(request.getCardNumber())) {
            throw new IllegalArgumentException("Invalid card number");
        }

        // Simulate fraud check (would integrate with external systems in production)
        if (isFraudulentTransaction(request)) {
            throw new SecurityException("Fraud detected");
        }

        // Generate transaction ID
        long transactionId = transactionIdCounter.getAndIncrement();

        // Store payment (in-memory for demo; use database in production)
        Payment payment = new Payment(
            transactionId,
            request.getAmount(),
            request.getCardNumber(),
            "AUTHORIZED"
        );
        repository.save(payment);

        return new PaymentResponse(transactionId, "Payment processed successfully");
    }

    private boolean isValidCard(String cardNumber) {
        // Simplified Luhn algorithm check
        int sum = 0;
        boolean alternate = false;
        for (int i = cardNumber.length() - 1; i >= 0; i--) {
            int digit = Character.getNumericValue(cardNumber.charAt(i));
            if (alternate) {
                digit *= 2;
                if (digit > 9) digit -= 9;
            }
            sum += digit;
            alternate = !alternate;
        }
        return sum % 10 == 0;
    }

    private boolean isFraudulentTransaction(PaymentRequest request) {
        // Simulate fraud detection (would use ML models or external APIs)
        return request.getAmount() > 100000; // Example rule
    }
