### 📌 **Minimal Payment Processing Service (Go)**

```go
package main

import (
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"sync"
	"time"
)

// Mock database (in-memory for simplicity)
var (
	accounts = map[string]float64{
		"123456": 1000.0, // Account ID: Balance
		"789012": 500.0,
	}
	mu sync.RWMutex
)

// PaymentRequest represents a payment transaction
type PaymentRequest struct {
	FromAccount string  `json:"from_account"`
	ToAccount   string  `json:"to_account"`
	Amount      float64 `json:"amount"`
}

// ProcessPayment handles payment logic
func ProcessPayment(req PaymentRequest) (string, error) {
	mu.RLock()
	defer mu.RUnlock()

	// Validate accounts
	if _, exists := accounts[req.FromAccount]; !exists {
		return "", fmt.Errorf("from account %s does not exist", req.FromAccount)
	}
	if _, exists := accounts[req.ToAccount]; !exists {
		return "", fmt.Errorf("to account %s does not exist", req.ToAccount)
	}

	// Validate amount
	if req.Amount <= 0 {
		return "", fmt.Errorf("amount must be positive")
	}

	// Check balance
	if accounts[req.FromAccount] < req.Amount {
		return "", fmt.Errorf("insufficient balance in from account")
	}

	// Deduct and add
	accounts[req.FromAccount] -= req.Amount
	accounts[req.ToAccount] += req.Amount

	// Log transaction
	log.Printf("Processed payment: %s -> %s | Amount: %.2f\n", req.FromAccount, req.ToAccount, req.Amount)
	return "Payment successful", nil
}

// PaymentHandler handles HTTP requests
func PaymentHandler(w http.ResponseWriter, r *http.Request) {
	var req PaymentRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid request payload", http.StatusBadRequest)
		return
	}

	result, err := ProcessPayment(req)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(map[string]string{"status": "success", "message": result})
}

// StartServer initializes and runs the payment service
func StartServer() {
	http.HandleFunc("/payment", PaymentHandler)
	fmt.Println("Payment service running on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}

func main() {
	// Simulate initial balance updates (for demo purposes)
	go func() {
		for {
			time.Sleep(5 * time.Second)
			mu.Lock()
			for id, balance := range accounts {
				log.Printf("Account %s: %.2f\n", id, balance)
			}
			mu.Unlock()
		}
	}()

	StartServer()
}
```

