    public ResponseEntity<String> processOrder(OrderRequest request) {
        // Type-safe validation
        if (request.getOrderId() == null || request.getCustomerId() == null) {
            return ResponseEntity.badRequest().body("Missing required fields");
        }

        // Ensure status is valid
        if (!isValidStatus(request.getStatus())) {
            return ResponseEntity.badRequest().body("Invalid order status");
        }

        // Save to database (integration with corporate DB)
