import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;

import java.util.*;

@SpringBootApplication
@RestController
@RequestMapping("/api/orders")
public class OrderService {

    // Mock legacy system integration (e.g., database or external API)
    private final LegacyInventoryService legacyInventoryService = new LegacyInventoryService();

    // Type-safe data model for orders
    record Order(String orderId, List<OrderItem> items) {}

    // Type-safe data model for order items
    record OrderItem(String productId, int quantity) {}

    // Mock legacy inventory service
    private static class LegacyInventoryService {
        public boolean checkInventory(String productId, int quantity) {
            // Simulate integration with legacy system
            return productId.equals("123") && quantity <= 100;
        }
    }

    // REST endpoint for processing orders
    @PostMapping
    public ResponseEntity<String> processOrder(@RequestBody Order order) {
        // Type-safe validation
        if (order == null || order.items() == null || order.items().isEmpty()) {
            return ResponseEntity.badRequest().body("Invalid order: missing items");
        }

        // Process each item
        for (OrderItem item : order.items()) {
            if (!legacyInventoryService.checkInventory(item.productId(), item.quantity())) {
                return ResponseEntity.status(400).body("Inventory insufficient for product: " + item.productId());
            }
        }

        // Simulate order processing
        return ResponseEntity.ok("Order processed successfully: " + order.orderId());
    }

    public static void main(String[] args) {
        SpringApplication.run(OrderService.class, args);
    }
}
```

