### 📁 `ProductRepository.cs` (Cosmos DB Integration)
```csharp
using Microsoft.Azure.Cosmos;
using System.Collections.Generic;
using System.Threading.Tasks;

public class ProductRepository : IProductRepository
{
    private readonly CosmosClient _client;
    private readonly Container _container;

    public ProductRepository()
    {
        var cosmosDbSettings = new CosmosDbSettings();
        _client = new CosmosClient(cosmosDbSettings.EndpointUri, cosmosDbSettings.PrimaryKey);
        _container = _client.GetDatabase(cosmosDbSettings.DatabaseId).GetContainer(cosmosDbSettings.ContainerId);
    }

    public async Task<IEnumerable<Product>> GetAllAsync()
    {
        var query = _container.GetItemQueryIterator<Product>(new QueryDefinition("SELECT * FROM c"));
        var results = new List<Product>();
        while (query.HasMoreResults)
        {
            var response = await query.ReadNextAsync();
            results.AddRange(response.ToList());
        }
        return results;
    }

    public async Task<Product> GetAsync(string id)
    {
        var response = await _container.ReadItemAsync<Product>(id, new PartitionKey(id));
        return response.Resource;
    }

    public async Task AddAsync(Product product)
    {
        await _container.CreateItemAsync(product, new PartitionKey(product.Id));
    }

    public async Task UpdateAsync(string id, Product product)
    {
        await _container.ReplaceItemAsync<Product>(product, id, new PartitionKey(id));
    }

    public async Task DeleteAsync(string id)
    {
        await _container.DeleteItemAsync<Product>(id, new PartitionKey(id));
    }
}
```

